"""
gpt2.py -- generated by llama_programs_v3/ab_compare/src/attn_study.py
          (study cell sol61_medium__seed1__n20), emitted with
          program_synthesis.emit_module

Model:     gpt2
Shape:     12 layers x 12 heads = 144 programs
Signature: (sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]
Scoring:   soft IoU (min/max), higher is better

Self-contained: every helper the programs call is defined below. Generated
programs are written out verbatim -- there is no text-rewriting conversion step.
"""
from typing import Tuple

from transformers import PreTrainedTokenizerBase

import numpy as np

_MODEL_ID = 'gpt2'
_nlp = None
_emb = None


def _get_nlp():
    global _nlp
    if _nlp is None:
        import spacy
        _nlp = spacy.load("en_core_web_sm")
    return _nlp


def _get_embeddings():
    """Input-embedding matrix of the model under study, loaded once."""
    global _emb
    if _emb is None:
        from transformers import AutoModel
        m = AutoModel.from_pretrained(_MODEL_ID)
        _emb = m.get_input_embeddings().weight.detach().to("cpu").float().numpy()
    return _emb


def tokenize(sentence, tokenizer):
    """Model tokens for `sentence`, as strings. This is the tokenization every
    program must use -- the attention matrix is aligned to it."""
    ids = tokenizer(sentence, return_tensors="pt").input_ids[0]
    return tokenizer.convert_ids_to_tokens(ids)


def spacy_parse(sentence):
    """spaCy Doc: .pos_, .dep_, .head, .ent_type_, .lemma_ ..."""
    return _get_nlp()(sentence)


def _char_spans(sentence, tokenizer):
    """(start, end) char span per model token. Uses fast-tokenizer offsets when
    available, else falls back to cumulative decoded length."""
    try:
        enc = tokenizer(sentence, return_offsets_mapping=True)
        om = enc["offset_mapping"]
        if om and any(e > s for s, e in om):
            return [tuple(x) for x in om]
    except Exception:
        pass
    spans, pos = [], 0
    for t in tokenize(sentence, tokenizer):
        clean = t.lstrip("\u0120").lstrip("##").lstrip()
        idx = sentence.find(clean, pos) if clean else pos
        if idx < 0:
            idx = pos
        spans.append((idx, idx + len(clean)))
        pos = idx + max(len(clean), 1)
    return spans


def align_tokens_to_spacy(sentence, tokens, tokenizer):
    """For each model token, the indices of spaCy tokens it overlaps."""
    doc = _get_nlp()(sentence)
    spans = _char_spans(sentence, tokenizer)
    out = []
    for (s, e) in spans[:len(tokens)]:
        out.append([k for k, w in enumerate(doc)
                    if not (w.idx + len(w.text) <= s or w.idx >= e)])
    while len(out) < len(tokens):
        out.append([])
    return out


def align_spacy_to_tokens(sentence, tokens, tokenizer):
    """Inverse map: for each spaCy token, the model-token indices covering it."""
    doc = _get_nlp()(sentence)
    fwd = align_tokens_to_spacy(sentence, tokens, tokenizer)
    out = [[] for _ in doc]
    for ti, sids in enumerate(fwd):
        for si in sids:
            if si < len(out):
                out[si].append(ti)
    return out


def get_modifying_adjectives(token):
    """spaCy children of `token` that are adjectival modifiers."""
    return [c for c in token.children if c.dep_ in ("amod", "advmod")]


def embedding_similarity(tokens, i, j, tokenizer):
    """Cosine similarity between tokens[i] and tokens[j] in the model's own
    input-embedding space. Use this instead of string equality to catch
    morphological and semantic relatives ("heard"/"hear", "cat"/"kitten")."""
    emb = _get_embeddings()
    try:
        a = emb[tokenizer.convert_tokens_to_ids(tokens[i])]
        b = emb[tokenizer.convert_tokens_to_ids(tokens[j])]
    except Exception:
        return 0.0
    na, nb = np.linalg.norm(a), np.linalg.norm(b)
    if na == 0 or nb == 0:
        return 0.0
    return float(np.dot(a, b) / (na * nb))


def make_row_stochastic(matrix):
    """Normalize each row to sum to 1; uniform-causal fallback for dead rows."""
    m = np.asarray(matrix, dtype=np.float64).copy()
    m[m < 0] = 0.0
    for i in range(m.shape[0]):
        s = m[i].sum()
        if s <= 0:
            m[i, : i + 1] = 1.0 / (i + 1)
        else:
            m[i] /= s
    return m


def apply_causal_mask(matrix):
    """Zero the strict upper triangle: token i may only attend to j <= i."""
    return np.tril(np.asarray(matrix, dtype=np.float64))



def prog_L0H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with lexical anchors; quoted dialogue additionally favors
    opening quotation marks, participant nouns, and reporting predicates.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "initial_sink_with_dialogue_keys", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos = []
    punctuation = []
    whitespace = []
    quote_marks = []
    for i, token in enumerate(tokens):
        clean = token.lstrip("\u0120").replace("\u010a", "\n")
        aligned = alignment[i]
        word = None
        for index in aligned:
            candidate = doc[index]
            if word is None or (word.is_space and not candidate.is_space):
                word = candidate

        pos.append(word.pos_ if word is not None else "")
        whitespace.append(not clean or clean.isspace())
        punctuation.append(
            bool(clean) and all(not c.isalnum() and not c.isspace() for c in clean)
        )
        quote_marks.append(
            any(c in "\"“”«»" for c in clean)
            or (word is not None and word.is_quote and punctuation[-1])
        )

    quote_anchors = []
    for i in range(1, n):
        if whitespace[i] or punctuation[i]:
            continue
        previous = i - 1
        while previous >= 0 and whitespace[previous]:
            previous -= 1
        if previous >= 0 and quote_marks[previous]:
            # Unspaced lexical tokens following quotes often become strong keys.
            if not tokens[i].startswith("\u0120"):
                quote_anchors.append(i)

    # Dialogue-only keys: quotation openings and nearby narrative participants.
    dialogue_openings = []
    dialogue_keys = {}
    for anchor in quote_anchors:
        opening = anchor - 1
        while opening >= 0 and whitespace[opening]:
            opening -= 1
        # Require a narrative predicate before the quote, not merely a quoted term.
        predicates = [
            j for j in range(max(1, opening - 8), opening)
            if pos[j] == "VERB"
        ]
        if predicates:
            dialogue_openings.append(opening)
            dialogue_keys[predicates[-1]] = 2.2

    if dialogue_openings:
        for j in range(1, n):
            if pos[j] in ("NOUN", "PROPN") and any(
                doc[k].dep_ in ("nsubj", "nsubjpass", "dobj", "obj", "pobj")
                for k in alignment[j]
            ):
                dialogue_keys[j] = 2.5

    key_strength = np.ones(n, dtype=np.float64)
    for j in range(n):
        if whitespace[j]:
            key_strength[j] = 0.35
        elif punctuation[j]:
            key_strength[j] = 0.55
        elif pos[j] == "VERB":
            key_strength[j] = 1.65
        elif pos[j] == "AUX":
            key_strength[j] = 1.05
        elif pos[j] in ("NOUN", "PROPN"):
            key_strength[j] = 1.15
        elif pos[j] in ("DET", "ADP", "CCONJ", "SCONJ", "PART"):
            key_strength[j] = 0.70

    if n > 1 and pos[0] == "DET" and pos[1] in ("NOUN", "PROPN"):
        key_strength[1] *= 1.45

    for i in range(n):
        distances = i - np.arange(i + 1)
        row = key_strength[:i + 1].copy()
        row *= 0.75 + 0.25 * np.exp(-distances / 7.0)

        for anchor in quote_anchors:
            if anchor <= i:
                row[anchor] *= 3.8
                if punctuation[i]:
                    row[anchor] *= 1.5

        if pos[i] == "AUX":
            row[i] *= 2.8
        elif pos[i] == "VERB":
            row[i] *= 1.15
        elif pos[i] in ("DET", "ADP", "PART", "PRON"):
            row[i] *= 0.80

        if punctuation[i] or quote_marks[i]:
            for j in range(i - 1, max(-1, i - 9), -1):
                if pos[j] == "VERB":
                    row[j] *= 1.8
                    break

        row[0] = 5.8 * np.exp(-i / 65.0)

        # Preserve all original diagonal weights and decay rates. Only dialogue
        # receives additional off-diagonal competition for the initial sink.
        if dialogue_openings and i >= 3:
            row[0] *= 0.65
            for j, multiplier in dialogue_keys.items():
                if j < i:
                    row[j] *= multiplier
            for opening in dialogue_openings:
                if opening < i:
                    row[opening] *= 5.0
            for anchor in quote_anchors:
                if anchor < i:
                    if pos[anchor] == "AUX":
                        row[anchor] /= 3.8
                    elif pos[i] in ("NOUN", "PROPN"):
                        row[anchor] *= 0.45

        attention[i, :i + 1] = row / row.sum()

    return "initial_sink_with_dialogue_keys", attention


def prog_L0H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Near-identity attention: each token overwhelmingly attends to itself.
    Approximate the dominant diagonal pattern without unsupported off-diagonal rules.
    """
    tokens = tokenize(sentence, tokenizer)
    attention_matrix = np.eye(len(tokens), dtype=np.float64)
    return "self_attention", attention_matrix


def prog_L0H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with boundary anchors; direct quotations retain their
    external governor and link matching punctuation across dialogue turns."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "initial_sink_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos = []
    speech = np.zeros(n, dtype=bool)
    comma = np.zeros(n, dtype=bool)
    quote = np.zeros(n, dtype=bool)
    terminal = np.zeros(n, dtype=bool)
    whitespace = np.zeros(n, dtype=bool)

    for i, token in enumerate(tokens):
        clean = token.lstrip("Ġ").lstrip("Ċ").strip()
        words = [doc[k] for k in alignment[i] if k < len(doc)]
        word = next((w for w in words if not w.is_space and not w.is_punct), None)
        pos.append(word.pos_ if word is not None else "PUNCT")

        whitespace[i] = not clean
        comma[i] = "," in clean
        quote[i] = any(c in clean for c in ('"', "“", "”", "«", "»"))
        terminal[i] = any(c in clean for c in (".", "!", "?"))

    for i in range(n):
        if pos[i] != "VERB":
            continue
        words = [doc[k] for k in alignment[i] if k < len(doc)]
        clausal = any(
            child.dep_ in ("ccomp", "parataxis")
            for word in words
            for child in word.children
        )
        nearby_quote = False
        for j in range(i + 1, min(n, i + 5)):
            if quote[j]:
                nearby_quote = True
                break
            if pos[j] in ("VERB", "AUX"):
                break
        speech[i] = clausal or nearby_quote

    # Only direct-quotation passages use the additional governor/boundary path.
    dialogue = np.count_nonzero(quote) >= 2
    quote_governor = np.full(n, -1, dtype=int)
    if dialogue:
        inside_quote = False
        governor = -1
        for i in range(n):
            if inside_quote:
                # A verb before a closing quote is not a quotation governor.
                speech[i] = False
            if quote[i]:
                if not inside_quote:
                    preceding = [j for j in range(i) if speech[j]]
                    governor = preceding[-1] if preceding else -1
                quote_governor[i] = governor
                inside_quote = not inside_quote

    key_weight = np.full(n, 1.2, dtype=np.float64)
    for j in range(n):
        if pos[j] == "AUX":
            key_weight[j] = 2.6
        elif pos[j] == "VERB":
            key_weight[j] = 1.7
        elif pos[j] == "CCONJ":
            key_weight[j] = 0.8
        if speech[j]:
            key_weight[j] = 3.8
        if comma[j]:
            key_weight[j] = 2.8
        if terminal[j]:
            key_weight[j] = 3.4
        if quote[j] and not terminal[j]:
            key_weight[j] = 0.7
        if whitespace[j]:
            key_weight[j] = 0.6

    attention[0, 0] = 1.0
    for i in range(1, n):
        distance = i - np.arange(i + 1)
        row = key_weight[:i + 1] * (0.8 + 0.2 * np.exp(-distance / 18.0))
        row[0] = 7.0
        row[i] = 1.6

        if i == 1:
            row[i] = 0.65 if pos[i] in ("NOUN", "PROPN", "ADJ", "DET") else 1.1
            if speech[i]:
                row[i] = 2.4

        if pos[i] == "CCONJ":
            row[i] = 12.0 + 0.4 * i
        if comma[i]:
            row[i] = 9.0
        if whitespace[i]:
            row[i] = 0.6

        if quote[i]:
            preceding = [j for j in range(1, i) if speech[j]]
            if preceding:
                nearest = preceding[-1]
                row[nearest] *= 4.5 if not terminal[i] else 2.5
            if not terminal[i]:
                row[i] = 0.6
        elif pos[i] in ("PRON", "DET"):
            for j in range(1, i):
                if speech[j]:
                    row[j] *= 1.6

        if dialogue:
            # Preserve self weights; strengthen only earlier boundary anchors.
            for j in range(1, i):
                if terminal[j] and quote[j]:
                    row[j] *= 4.0 if quote[i] or terminal[i] else 2.0
                if comma[i] and comma[j]:
                    row[j] *= 4.0

            if quote[i] and quote_governor[i] > 0:
                governor = quote_governor[i]
                preceding = [j for j in range(1, i) if speech[j]]
                nearest = preceding[-1] if preceding else -1
                # Replace a nearer attribution with the actual opening governor.
                if nearest != governor:
                    if nearest > 0:
                        row[nearest] /= 4.5 if not terminal[i] else 2.5
                    row[governor] *= 4.5 if not terminal[i] else 2.5
                row[governor] *= 1.5 if not terminal[i] else 1.8

        attention[i, :i + 1] = row / row.sum()

    return "initial_sink_dialogue_anchors", attention


def prog_L0H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predominantly self-attention, strongest on content tokens.
    Function words and punctuation leak attention to the recent past and start."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "lexically_modulated_self", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    self_by_pos = {
        "NOUN": 0.985,
        "PROPN": 0.985,
        "VERB": 0.980,
        "ADJ": 0.990,
        "ADV": 0.965,
        "NUM": 0.955,
        "INTJ": 0.980,
        "PRON": 0.895,
        "AUX": 0.850,
        "ADP": 0.845,
        "DET": 0.790,
        "CCONJ": 0.785,
        "SCONJ": 0.885,
        "PART": 0.760,
        "PUNCT": 0.710,
        "SPACE": 0.998,
    }

    for i, token in enumerate(tokens):
        if i == 0:
            attention[i, i] = 1.0
            continue

        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None
        self_mass = self_by_pos.get(word.pos_, 0.960) if word is not None else 0.960

        # Standalone whitespace has an especially sharp diagonal.
        clean = token.replace("Ġ", " ").replace("Ċ", "\n").replace("ĉ", "\t")
        if clean and clean.isspace():
            self_mass = 0.998

        # Clitic fragments preferentially look back to their host.
        clitic = (
            word is not None
            and word.pos_ in ("PART", "AUX")
            and clean.lstrip().startswith(("'", "’"))
        )
        if clitic:
            self_mass = 0.200

        attention[i, i] = self_mass
        remaining = 1.0 - self_mass

        if clitic:
            attention[i, i - 1] += remaining * 0.985
            attention[i, 0] += remaining * 0.015
        else:
            # Small causal background, with recency and a start-token sink.
            distances = i - np.arange(i, dtype=np.float64)
            background = np.exp(-distances / 2.5)
            background /= background.sum()
            attention[i, :i] += remaining * 0.65 * background
            attention[i, 0] += remaining * 0.35

    return "lexically_modulated_self", make_row_stochastic(attention)


def prog_L0H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Lexical self-attention with an initial sink; contraction and incomplete
    UTF-8 fragments preferentially retain their preceding tokenization anchor.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "lexical_self_with_fragment_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    owners = []
    for i, indices in enumerate(alignment):
        valid = [k for k in indices if k < len(doc)]
        for k in valid:
            inverse[k].append(i)
        nonspace = [k for k in valid if not doc[k].is_space]
        owners.append(nonspace[-1] if nonspace else (valid[-1] if valid else None))

    lexical_pos = ("NOUN", "PROPN", "ADJ", "VERB", "ADV", "NUM")
    strengths = np.zeros(n, dtype=np.float64)
    self_mass = np.zeros(n, dtype=np.float64)

    for i, raw in enumerate(tokens):
        clean = raw.replace("Ġ", " ").replace("Ċ", "\n").strip()
        owner = owners[i]
        word = doc[owner] if owner is not None else None
        pos = word.pos_ if word is not None else ""

        if not clean:
            mass, strength = 0.80, 0.75
        elif all(c in "\"'“”‘’«»" for c in clean):
            mass, strength = 0.88, 0.85
        elif word is not None and word.is_punct:
            mass, strength = 0.38, 0.12
        elif pos in ("NOUN", "PROPN"):
            mass, strength = 0.88, 1.00
        elif pos == "ADJ":
            mass, strength = 0.90, 1.00
        elif pos == "VERB":
            mass, strength = 0.76, 0.95
        elif pos == "ADV":
            mass, strength = 0.64, 0.65
        elif pos == "NUM":
            mass, strength = 0.65, 0.65
        elif pos == "AUX":
            mass, strength = 0.38, 0.50
        elif pos in ("PRON", "DET"):
            mass, strength = 0.23, 0.12
        elif pos in ("ADP", "PART"):
            mass, strength = 0.29, 0.20
        elif pos in ("CCONJ", "SCONJ"):
            mass, strength = 0.35, 0.20
        else:
            mass, strength = 0.48, 0.35

        if word is not None and word.dep_ in ("aux", "auxpass", "cop", "mark"):
            mass = min(mass, 0.38)

        # The initial position is a particularly strong competitor early on.
        if i == 1 and pos not in ("NOUN", "PROPN", "ADJ"):
            mass = min(mass, 0.12 if pos != "VERB" else 0.24)
        if i == 1 and owners[0] is not None:
            if doc[owners[0]].pos_ == "NUM" and pos == "NOUN":
                mass = 0.10
        if i <= 3 and word is not None and word.is_punct:
            mass = min(mass, 0.16)

        self_mass[i] = mass
        strengths[i] = strength

    attention[0, 0] = 1.0
    for i in range(1, n):
        scores = np.zeros(i, dtype=np.float64)
        distance = i - np.arange(i)
        scores[:] = (0.025 + strengths[:i]) * np.exp(-distance / 3.0)
        scores[0] += 0.32 + 2.8 * np.exp(-(i - 1) / 3.0)

        owner = owners[i]
        word = doc[owner] if owner is not None else None
        if word is not None:
            # Infinitival markers, auxiliaries, and prepositions often borrow
            # a preceding predicate's representation.
            if word.pos_ not in lexical_pos:
                for j in range(i - 1, -1, -1):
                    previous = owners[j]
                    if previous is not None and doc[previous].pos_ in lexical_pos:
                        scores[j] += 0.65 * np.exp(-(i - j - 1) / 6.0)
                        break

                head_pieces = inverse[word.head.i]
                preceding = [j for j in head_pieces if j < i]
                if preceding:
                    scores[preceding[0]] += 0.65

            # Short suffix pieces frequently retain the word's initial piece.
            pieces = inverse[owner]
            if pieces and pieces[0] < i:
                first = pieces[0]
                clean = tokens[i].replace("Ġ", " ").strip()
                if len(clean) <= 3 or word.pos_ in ("AUX", "PART", "ADV"):
                    self_mass[i] = min(self_mass[i], 0.24)
                    scores[first] += 3.0
                else:
                    scores[first] += 0.30

        scores /= scores.sum()
        attention[i, :i] = (1.0 - self_mass[i]) * scores
        attention[i, i] = self_mass[i]

    # GPT-2's reversible byte alphabet lets us recognize split UTF-8
    # characters independently of potentially incorrect spaCy alignment.
    visible_bytes = (
        list(range(33, 127)) + list(range(161, 173)) + list(range(174, 256))
    )
    byte_decoder = {chr(b): b for b in visible_bytes}
    extra = 0
    for b in range(256):
        if b not in visible_bytes:
            byte_decoder[chr(256 + extra)] = b
            extra += 1

    pending_anchor = None
    pending_bytes = b""
    for i, raw in enumerate(tokens):
        # Negated contraction tails can straddle two spaCy words. Do not
        # apply this rule to possessive or other apostrophe suffixes.
        clean = raw.replace("Ġ", " ").replace("Ċ", "\n").strip()
        owner = owners[i]
        word = doc[owner] if owner is not None else None
        if (
            i > 0
            and clean.startswith(("'", "’"))
            and clean[1:].isalpha()
            and len(clean) <= 3
            and word is not None
            and (word.dep_ == "neg" or "Neg" in word.morph.get("Polarity"))
        ):
            attention[i] *= 0.02
            attention[i, i - 1] += 0.87
            attention[i, i] += 0.11

        if not all(c in byte_decoder for c in raw):
            pending_anchor, pending_bytes = None, b""
            continue
        piece = bytes(byte_decoder[c] for c in raw)

        if (
            pending_anchor is not None
            and piece
            and 0x80 <= piece[0] <= 0xBF
        ):
            attention[i] *= 0.02
            attention[i, pending_anchor] += 0.93
            attention[i, i] += 0.05
            combined = pending_bytes + piece
            try:
                combined.decode("utf-8")
                pending_anchor, pending_bytes = None, b""
            except UnicodeDecodeError as exc:
                if exc.reason == "unexpected end of data":
                    pending_bytes = combined
                else:
                    pending_anchor, pending_bytes = None, b""
            continue

        pending_anchor, pending_bytes = None, b""
        try:
            piece.decode("utf-8")
        except UnicodeDecodeError as exc:
            if exc.reason == "unexpected end of data":
                pending_anchor, pending_bytes = i, piece
                attention[i] *= 0.06
                attention[i, i] += 0.94

    return "lexical_self_with_fragment_anchors", attention


def prog_L0H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sharp self-identity attention with explicit earlier-token copying.
    Exact tokenizer-token repeats bypass potentially unreliable embedding similarity.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "self_identity_with_exact_repeat_fallback", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    content_pos = {"NOUN", "PROPN", "VERB", "ADJ", "ADV", "NUM"}
    function_pos = {"DET", "ADP", "AUX", "PRON", "CCONJ", "SCONJ", "PART"}

    for i in range(n):
        positions = {doc[k].pos_ for k in alignment[i]}
        if positions & content_pos:
            temperature = 14.0
        elif positions & function_pos:
            temperature = 9.0
        elif "PUNCT" in positions:
            temperature = 10.0
        else:
            temperature = 13.0

        scores = np.empty(i + 1, dtype=np.float64)
        for j in range(i + 1):
            similarity = (
                1.0 if j == i
                else embedding_similarity(tokens, i, j, tokenizer)
            )

            # Exact model-token identity is not semantic relatedness:
            # guarantee that earlier copies receive the original match bonus.
            if j < i and tokens[j] == tokens[i]:
                similarity = 1.0

            scores[j] = temperature * similarity

            if j < i:
                # Preserve the original competition strength and distance bias.
                match_strength = max(0.0, (similarity - 0.75) / 0.25)
                scores[j] += match_strength * (
                    0.65 + 0.35 * (i - j) / (i + 1)
                )

        scores -= np.max(scores)
        weights = np.exp(scores)
        attention[i, :i + 1] = weights / weights.sum()

    return "self_identity_with_exact_repeat_fallback", attention


def prog_L0H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token anchoring with lexical salience.
    Predicative adjectives remain salient keys for subsequent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_anchor_predicate_salience", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos = []
    dep = []
    word_ids = []
    for indices in aligned:
        if indices:
            word = doc[indices[-1]]
            pos.append(word.pos_)
            dep.append(word.dep_)
            word_ids.append(word.i)
        else:
            pos.append("")
            dep.append("")
            word_ids.append(-1)

    salience = np.ones(n, dtype=np.float64)
    for j in range(n):
        if pos[j] in ("NOUN", "PROPN"):
            salience[j] = 2.5
        elif pos[j] == "ADJ":
            salience[j] = 1.8
        elif pos[j] == "VERB":
            salience[j] = 1.05
        elif pos[j] in ("DET", "ADP", "AUX", "CCONJ", "SCONJ"):
            salience[j] = 0.65
        elif pos[j] == "PUNCT":
            salience[j] = 0.45

        if dep[j] in ("nsubj", "nsubjpass", "csubj"):
            salience[j] *= 1.35

        # Split-word continuations should not become independent salient keys.
        if j > 0 and word_ids[j] >= 0 and word_ids[j] == word_ids[j - 1]:
            salience[j] *= 0.4

    # Only predicate adjectives, not ordinary attributive modifiers, receive
    # the additional persistent-key preference. Keep first BPE fragments only.
    predicate_adjectives = []
    for j in range(1, n):
        if pos[j] != "ADJ" or word_ids[j] == word_ids[j - 1]:
            continue
        word = doc[word_ids[j]]
        predicate = word
        while predicate.dep_ == "conj" and predicate.head.pos_ == "ADJ":
            predicate = predicate.head
        if predicate.dep_ in ("acomp", "attr", "oprd", "ROOT"):
            predicate_adjectives.append(j)

    quote_chars = "\"“”‘’"
    previous_quote = -1
    opening_quote = -1

    for i in range(n):
        distances = i - np.arange(i + 1)
        row = salience[:i + 1] * np.exp(-distances / 38.0)

        # The first position acts as an attention sink, particularly early on.
        if pos[0] in ("NOUN", "PROPN"):
            row[0] = 3.0 + 14.0 * np.exp(-i / 8.0)
        elif pos[0] in ("ADP", "ADV", "SCONJ"):
            row[0] = 0.9 + 20.0 * np.exp(-i / 4.6)
        else:
            row[0] = 0.8 + 14.0 * np.exp(-i / 4.6)

        if i > 0:
            row[i - 1] += 0.35

        # Infinitival particles often form conspicuous diagonal peaks.
        if pos[i] == "PART" and dep[i] in ("aux", "mark"):
            row[i] += 0.44 * row.sum()

        if pos[i] in ("NOUN", "PROPN", "ADJ"):
            row[i] *= 1.15

        # Function tokens preferentially retrieve earlier subject-like nominals.
        if pos[i] in ("PRON", "DET", "AUX", "CCONJ", "ADP"):
            for j in range(1, i):
                if dep[j] in ("nsubj", "nsubjpass", "csubj"):
                    row[j] += 1.8 * np.exp(-(i - j) / 30.0)

        # BPE fragments of a word often look back to its first fragment.
        if i > 0 and word_ids[i] >= 0:
            for j in range(i):
                if word_ids[j] == word_ids[i]:
                    row[j] += 0.35 * row.sum()
                    break

        clean = tokens[i].lstrip("Ġ")
        is_quote = any(c in clean for c in quote_chars)
        if is_quote:
            closes = any(c in clean for c in ".!?") or clean in ("”", "’")
            if opening_quote >= 0 and closes:
                row[opening_quote] += 0.85 * row.sum()
                opening_quote = -1
            else:
                if previous_quote >= 0:
                    row[previous_quote] += 0.65 * row.sum()
                opening_quote = i
            previous_quote = i

        # Targeted correction: boost only earlier predicate-adjective keys.
        # Original diagonal weights and distance-decay constants are untouched.
        for j in predicate_adjectives:
            if j >= i:
                break
            row[j] *= 2.6

        attention[i, :i + 1] = row / row.sum()

    return "first_anchor_predicate_salience", attention


def prog_L0H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict local anchors with an initial sink; dialogue spreads backward attention
    over nearby tokens and retains recent utterance-ending punctuation.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_anchors_with_dialogue_boundaries", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[indices[0]] if indices else None
        for indices in aligned
    ]

    anchor_pos = {"DET", "ADP", "CCONJ", "SCONJ", "PRON", "AUX", "PART"}
    modifier_deps = {"amod", "advmod", "compound", "poss", "det"}
    punctuation_chars = ".,;:!?\"'()[]{}—–-…“”‘’"

    # Restrict the added behavior to quoted or expressive utterances.
    dialogue = any(char in sentence for char in '"“”!?')

    is_punctuation = []
    for i, token in enumerate(tokens):
        surface = token.replace("Ġ", " ").replace("Ċ", "\n").strip()
        word = words[i]
        is_punctuation.append(
            bool(surface)
            and (
                all(char in punctuation_chars for char in surface)
                or (word is not None and word.is_punct)
            )
        )

    attention[0, 0] = 1.0
    for i in range(1, n):
        if i == 1:
            attention[i, 0] = 0.96
            attention[i, i] = 0.04
            continue

        distances = i - np.arange(i + 1)
        row = 0.70 * np.exp(-distances / 2.4)
        row[i] = 0.65
        row[i - 1] = 1.35

        for j in range(i + 1):
            word = words[j]
            if is_punctuation[j]:
                row[j] *= 1.55
            elif word is not None and word.pos_ in anchor_pos:
                row[j] *= 1.30

        current = words[i]
        if is_punctuation[i]:
            row[i] = 2.05
        elif current is not None and current.pos_ in anchor_pos:
            row[i] = 1.20

        # The first position is unusually attractive over the opening phrase.
        row[0] += 2.20 * np.exp(-0.65 * (i - 2))

        # Local grammatical links refine the positional prior, not replace it.
        if current is not None:
            for j in range(max(0, i - 3), i):
                previous = words[j]
                if previous is None:
                    continue
                if previous.i == current.i:
                    continue
                distance = i - j
                if previous.head.i == current.i and previous.dep_ in modifier_deps:
                    row[j] += 0.45 / distance
                if current.head.i == previous.i and previous.pos_ in anchor_pos:
                    row[j] += 0.35 / distance

        # Continuation pieces preferentially look at the immediately prior piece.
        surface = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        same_word = bool(set(aligned[i]).intersection(aligned[i - 1]))
        continuation = (
            same_word
            and bool(surface)
            and surface[0].isalnum()
            and not tokens[i].startswith(("Ġ", "Ċ"))
        )
        if continuation:
            row[i - 1] += 5.0
        elif surface.startswith(("'", "’")) and not tokens[i].startswith("Ġ"):
            row[i - 1] += 1.0

        if dialogue and i >= 3:
            # Do not let byte-fragment alignment or adverb suffixes masquerade
            # as the strong lexical continuation seen in names.
            lexical_continuation = (
                continuation
                and current is not None
                and current.text.isascii()
                and current.text.isalpha()
                and current.pos_ in {"NOUN", "PROPN", "ADJ", "VERB", "ADV"}
                and surface.isascii()
            )
            if continuation and not lexical_continuation:
                row[i - 1] -= 5.0
            elif lexical_continuation and current.pos_ == "ADV":
                row[i - 1] -= 4.5

            if not lexical_continuation or current.pos_ == "ADV":
                # Broaden only backward mass; retain the original self weight.
                row[i - 1] *= 0.65
                for j in range(max(0, i - 8), i - 1):
                    distance = i - j
                    row[j] += 0.40 * np.exp(-(distance - 2) / 2.4)

            # Closing utterance punctuation remains an anchor across spaces,
            # quote fragments, and the opening words of the next utterance.
            for j in range(max(0, i - 8), i):
                if any(char in tokens[j] for char in "!?"):
                    row[j] += 1.10 * np.exp(-(i - j - 1) / 4.0)

        attention[i, :i + 1] = row / row.sum()

    return "local_anchors_with_dialogue_boundaries", attention


def prog_L0H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict a first-token sink mixed with lexical boundary anchors.
    Prepositions and subordinators additionally anchor their following phrases.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_and_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = []
    for indices in alignment:
        candidates = [doc[k] for k in indices if not doc[k].is_space]
        words.append(candidates[-1] if candidates else None)

    pos = [w.pos_ if w is not None else "" for w in words]
    dep = [w.dep_ if w is not None else "" for w in words]
    clean = [t.lstrip("ĠĊ▁").strip() for t in tokens]
    punctuation = [
        bool(clean[i]) and (
            pos[i] == "PUNCT" or
            all(not c.isalnum() and not c.isspace() for c in clean[i])
        )
        for i in range(n)
    ]

    quotes = {'"', "“", "”", "«", "»"}
    quote_tokens = [any(c in quotes for c in t) for t in clean]
    determiners = [
        pos[i] == "DET" and dep[i] not in ("poss", "nmod:poss")
        for i in range(n)
    ]
    auxiliaries = [pos[i] == "AUX" for i in range(n)]
    coordinators = [pos[i] == "CCONJ" for i in range(n)]
    particles = [pos[i] == "PART" for i in range(n)]

    # Only previously unmodeled phrase-opening function words qualify.
    phrase_openers = [
        j > 0
        and pos[j] in ("ADP", "SCONJ")
        and not punctuation[j]
        and not quote_tokens[j]
        and (words[j - 1] is None or words[j].i != words[j - 1].i)
        for j in range(n)
    ]

    key_strength = np.full(n, 0.65, dtype=np.float64)
    for j in range(n):
        if determiners[j]:
            key_strength[j] = 3.4
        elif auxiliaries[j]:
            key_strength[j] = 2.0
        elif coordinators[j]:
            key_strength[j] = 3.8
        elif particles[j]:
            key_strength[j] = 3.8
        elif punctuation[j]:
            key_strength[j] = 4.0
        if quote_tokens[j]:
            key_strength[j] = 4.5

        if phrase_openers[j]:
            key_strength[j] = 5.0

    open_quote = None
    for i in range(n):
        distances = i - np.arange(i + 1)
        row = key_strength[:i + 1] * (
            0.48 + 0.52 * np.exp(-distances / 18.0)
        )
        row[0] = 6.5 * np.exp(-i / 45.0) + 0.35

        if determiners[i]:
            row[i] += 3.0 + 19.0 * np.exp(-i / 16.0)
            if i == 1:
                row[i] *= 0.48
        elif punctuation[i]:
            row[i] += 3.0 + 13.0 * np.exp(-i / 17.0)
        elif coordinators[i]:
            row[i] += 3.0 + 8.0 * np.exp(-i / 18.0)
        elif auxiliaries[i]:
            row[i] += 2.0 + 3.5 * np.exp(-i / 12.0)
        elif particles[i]:
            row[i] += 4.0 + 8.0 * np.exp(-i / 20.0)

        if phrase_openers[i]:
            row[i] += 3.0 + 8.0 * np.exp(-i / 16.0)

        # A determiner remains an anchor for the following nominal phrase.
        if pos[i] in ("NOUN", "PROPN", "ADJ", "ADP"):
            for j in range(i - 1, max(-1, i - 5), -1):
                if punctuation[j] or coordinators[j]:
                    break
                if determiners[j]:
                    row[j] += 4.0 * np.exp(-(i - j - 1) / 3.0)
                    break

        # Compound nouns can strongly favor their preceding nominal modifier.
        current = words[i]
        if current is not None and pos[i] in ("NOUN", "PROPN"):
            for j in range(max(0, i - 4), i):
                previous = words[j]
                if (
                    previous is not None
                    and previous.i != current.i
                    and previous.dep_ == "compound"
                    and previous.head.i == current.i
                ):
                    row[j] += 22.0

        # Opening quotes share mass with the preceding punctuation; closing
        # quotes preferentially retrieve their opening delimiter.
        if open_quote is not None:
            row[open_quote] += 4.0 * np.exp(-(i - open_quote) / 24.0)
        if quote_tokens[i]:
            if open_quote is None:
                row[i] += 4.0
                if i > 0 and punctuation[i - 1]:
                    row[i - 1] += 8.0
                open_quote = i
            else:
                row[open_quote] += 10.0
                open_quote = None

        attention[i, :i + 1] = row

    return "first_token_and_boundary_anchors", make_row_stochastic(attention)


def prog_L0H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with a diffuse POS background.
    In dialogue, weaken the sink and favor completed utterance boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_dialogue_boundaries", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    pos = []
    for indices in alignment:
        overlapping = [doc[k] for k in indices if not doc[k].is_space]
        pos.append(overlapping[0].pos_ if overlapping else "")

    salience = {
        "NOUN": 0.70,
        "PROPN": 0.65,
        "PRON": 0.95,
        "DET": 1.20,
        "ADJ": 0.85,
        "ADV": 0.95,
        "VERB": 1.00,
        "AUX": 1.20,
        "ADP": 1.05,
        "CCONJ": 1.30,
        "SCONJ": 1.10,
        "PART": 1.00,
        "PUNCT": 1.05,
    }
    key_weights = np.array(
        [salience.get(tag, 0.95) for tag in pos], dtype=np.float64
    )
    sink_weight = 3.70 if pos[0] == "DET" else 3.10

    quote_start = next(
        (j for j, token in enumerate(tokens)
         if any(mark in token for mark in ('"', "“", "”"))),
        n,
    )
    utterance_end = [
        pos[j] == "PUNCT" and any(mark in tokens[j] for mark in ("?", "!", "."))
        for j in range(n)
    ]

    for i in range(n):
        attention[i, :i + 1] = key_weights[:i + 1]
        attention[i, 0] = sink_weight

        if i > 0:
            if pos[i] == "PROPN":
                attention[i, i] *= 0.32
            elif pos[i] == "NOUN":
                attention[i, i] *= 0.85

            # An opening determiner dominates its following nominal token.
            if i == 1 and pos[0] == "DET":
                if pos[i] in ("NOUN", "PROPN"):
                    attention[i, i] *= 0.25
                elif pos[i] == "ADJ":
                    attention[i, i] *= 0.65

            # Dialogue distributes sink mass toward the causal background,
            # especially prior utterance endings; retain raw self weights.
            if i >= quote_start:
                attention[i, 0] *= 0.70
                for j in range(1, i):
                    if utterance_end[j]:
                        attention[i, j] *= 1.65

    return "first_token_sink_dialogue_boundaries", make_row_stochastic(attention)


def prog_L0H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink and self ridge, with a secondary early grammatical anchor.
    An early determiner or auxiliary can attract persistent causal attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_sink_early_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    pos = []
    for indices in alignment:
        candidates = [doc[k] for k in indices if not doc[k].is_space]
        pos.append(candidates[-1].pos_ if candidates else "")

    # A narrowly gated secondary sink: unlike an initial determiner,
    # an opening content word may leave anchoring to an early function word.
    anchor = None
    if pos[0] != "DET":
        if n > 1 and pos[1] in ("DET", "AUX"):
            anchor = 1
        elif n > 2 and pos[1] == "VERB" and pos[2] == "DET":
            anchor = 2

    attention[0, 0] = 1.0
    for i in range(1, n):
        # Broad background, mildly favoring recent positions.
        for j in range(1, i):
            attention[i, j] = 0.42 / np.sqrt(i - j)

        # The initial token dominates early, regardless of its grammatical role.
        sink = 2.0 * np.exp(-(i - 1) / 6.5)
        sink += 0.15 + 0.16 / (1.0 + i / 12.0)

        self_weight = 1.10
        if pos[i] in ("NOUN", "PROPN", "VERB", "ADJ", "PRON"):
            self_weight += 0.10
        elif pos[i] in ("PUNCT", "SPACE"):
            self_weight -= 0.20
        elif pos[i] in ("CCONJ", "SCONJ"):
            self_weight -= 0.15
            sink *= 1.20

        attention[i, 0] = sink
        attention[i, i] = self_weight

        # Only the detected early anchor receives additional raw weight.
        if anchor is not None and i > anchor:
            attention[i, anchor] += (
                0.85 * np.exp(-(i - anchor - 1) / 14.0) + 0.15
            )

        # A sharp similarity gate makes repeated lexical material competitive
        # without turning the head into a general semantic retrieval mechanism.
        if pos[i] not in ("PUNCT", "SPACE") and tokens[i].strip():
            for j in range(i):
                if pos[j] in ("PUNCT", "SPACE") or not tokens[j].strip():
                    continue
                similarity = embedding_similarity(tokens, i, j, tokenizer)
                strength = max(0.0, (similarity - 0.55) / 0.45)
                attention[i, j] += 1.10 * strength ** 4

    return "first_sink_early_anchor", make_row_stochastic(attention)


def prog_L0H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with diffuse context; quoted dialogue adds persistent
    attention anchors at interrogatives and salient punctuation boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos = []
    for indices in alignment:
        if indices:
            pos.append(doc[indices[0]].pos_)
        else:
            pos.append("")

    key_strength = np.ones(n, dtype=np.float64)
    for j in range(1, n):
        if pos[j] == "CCONJ":
            key_strength[j] = 2.35
        elif pos[j] == "AUX":
            key_strength[j] = 1.15
        elif pos[j] == "PUNCT":
            key_strength[j] = 1.15
        elif pos[j] == "VERB":
            key_strength[j] = 1.05

    # GPT-2's byte-encoded punctuation can include mojibake fragments.
    # Activate only for quoted dialogue, leaving ordinary prose unchanged.
    dialogue = any(
        any(c in token for c in ('"', "“", "”"))
        or token.endswith("Ĥ¬")
        for token in tokens
    )
    anchor_strength = np.ones(n, dtype=np.float64)
    if dialogue:
        for j in range(1, n):
            token = tokens[j]
            if token.endswith("Ĥ¬"):
                anchor_strength[j] = 4.5
            elif any(c in token for c in ("?", "!")):
                anchor_strength[j] = 1.9
            elif any(c in token for c in ('"', "“", "”")):
                anchor_strength[j] = 1.35
            elif "," in token and pos[j] == "PUNCT":
                anchor_strength[j] = 1.35
            elif any(doc[k].tag_ in ("WDT", "WP", "WP$", "WRB")
                     for k in alignment[j]):
                anchor_strength[j] = 2.4

    attention[0, 0] = 1.0

    for i in range(1, n):
        distances = i - np.arange(i + 1)
        weights = key_strength[:i + 1] * np.exp(-distances / 55.0)

        # The background is broad rather than a previous-token pointer.
        weights[i] *= 1.40
        if i > 1:
            weights[i - 1] *= 1.10

        sink = 3.35
        if pos[0] == "PRON":
            sink *= 1.0 + 0.40 * np.exp(-(i - 1) / 2.5)

        if pos[i] in ("ADJ", "ADV"):
            sink *= 1.24
            weights[i] *= 0.90
        elif pos[i] == "AUX":
            sink *= 1.18
        elif pos[i] == "PROPN":
            sink *= 0.85
        elif pos[i] == "PUNCT":
            sink *= 0.92

        weights[0] = sink

        # Boost only earlier dialogue anchors: retain the original sink,
        # decay, and unnormalized self-attention weight exactly.
        if dialogue:
            weights[1:i] *= anchor_strength[1:i]

        attention[i, :i + 1] = weights / weights.sum()

    return "first_token_sink_with_dialogue_anchors", attention


def prog_L1H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Initial-token sink and local phrase links, with predicate attention
    redirected to preceding auxiliaries or the start of a nominal subject."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "initial_sink_predicate_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    representatives = []
    for sids in alignment:
        lexical = [sid for sid in sids if not doc[sid].is_space]
        representatives.append(doc[lexical[-1]] if lexical else None)

    quote_stack = []
    quote_pairs = {'"': '"', "'": "'", "“": "”", "‘": "’"}
    word_start = 0

    for i in range(n):
        raw = tokens[i]
        clean = raw.lstrip("ĠĊ")
        current = representatives[i]
        previous = representatives[i - 1] if i else None

        closing_quote = None
        quote_chars = [c for c in clean if c in "\"'“”‘’"]
        is_quote = bool(quote_chars) and (
            current is None or current.is_punct
        )
        if is_quote:
            for char in quote_chars:
                if quote_stack and char == quote_stack[-1][0]:
                    closing_quote = quote_stack.pop()[1]
                elif char in quote_pairs:
                    quote_stack.append((quote_pairs[char], i))

        if i == 0:
            attention[0, 0] = 1.0
            continue

        distances = i - np.arange(i + 1)
        background = np.exp(-distances / 4.0)
        background /= background.sum()

        local = 0.30 * background
        local[i] += 0.22
        local[i - 1] += 0.48

        target = i - 1
        strength = 0.0
        same_word = (
            bool(alignment[i])
            and bool(alignment[i - 1])
            and bool(set(alignment[i]).intersection(alignment[i - 1]))
        )
        continuation = (
            same_word
            and not raw.startswith(("Ġ", "Ċ"))
            and current is not None
            and not current.is_punct
        )

        if not continuation:
            word_start = i

        if current is not None and previous is not None:
            cp, pp = current.pos_, previous.pos_

            if cp in ("NOUN", "PROPN", "ADJ") and pp == "DET":
                strength = 0.48 if cp != "ADJ" else 0.56
            if cp in ("NOUN", "PROPN") and previous.dep_ == "poss":
                strength = 0.77
            if cp in ("NOUN", "PROPN") and pp == "ADJ":
                strength = 0.50
            if cp == "ADJ" and pp in ("AUX", "VERB"):
                strength = 0.52
            if cp in ("ADP", "PART") and pp in ("VERB", "ADJ"):
                strength = 0.69
            if cp == "VERB" and previous.tag_ == "TO":
                strength = 0.59
            if cp == "VERB" and pp in ("AUX", "VERB"):
                strength = max(strength, 0.48)
            if cp in ("DET", "PRON") and pp == "ADP":
                strength = max(strength, 0.40)
            if cp in ("AUX", "VERB") and pp == "PRON":
                strength = max(strength, 0.43)
            if cp in ("ADJ", "ADV") and pp == "ADV":
                strength = max(strength, 0.60)
            if current.dep_ == "prt":
                strength = max(strength, 0.84)
            if current.is_punct and pp == "VERB":
                strength = max(strength, 0.36)

            # Past subjects and auxiliaries can form a short phrase anchor.
            if cp in ("AUX", "VERB", "PRON"):
                for j in range(i - 1, max(-1, i - 4), -1):
                    candidate = representatives[j]
                    if candidate is None:
                        continue
                    if (
                        candidate.dep_ in ("nsubj", "nsubjpass")
                        and candidate.head.i == current.i
                    ):
                        target = j
                        strength = max(strength, 0.40)
                        break

        if continuation:
            target = min(word_start, i - 1)
            strength = 0.88
        if closing_quote is not None:
            target = closing_quote
            strength = 0.40
        if not clean.strip():
            target = i
            strength = 0.34

        local *= 1.0 - strength
        local[target] += strength

        sink = 0.99 * np.exp(-0.29 * (i - 1))
        if strength >= 0.5 and target != 0:
            sink *= 0.42
        if continuation and target == 0:
            sink = max(sink, 0.92)

        attention[i, :i + 1] = (1.0 - sink) * local
        attention[i, 0] += sink

        # Narrow predicate exception: move only existing backward-link mass.
        # Self-attention, initial-sink mass, and all other rows stay unchanged.
        if (
            current is not None
            and current.pos_ in ("VERB", "AUX")
            and not continuation
            and closing_quote is None
        ):
            anchor = None
            for j in range(i - 1, max(-1, i - 5), -1):
                candidate = representatives[j]
                if (
                    candidate is not None
                    and candidate.pos_ == "AUX"
                    and candidate.dep_ in ("aux", "auxpass")
                    and candidate.head.i == current.i
                ):
                    anchor = j
                    break

            if (
                anchor is None
                and previous is not None
                and previous.pos_ in ("NOUN", "PROPN")
                and previous.dep_ in ("nsubj", "nsubjpass")
                and previous.head.i == current.i
            ):
                for j in range(max(1, i - 4), i - 1):
                    candidate = representatives[j]
                    if (
                        candidate is not None
                        and candidate.dep_ in ("det", "poss")
                        and candidate.head.i == previous.i
                    ):
                        anchor = j
                        break

            if anchor is not None and anchor > 0:
                for source in {target, i - 1}:
                    if 0 < source < i and source != anchor:
                        moved = 0.85 * attention[i, source]
                        attention[i, source] -= moved
                        attention[i, anchor] += moved

    return "initial_sink_predicate_anchors", make_row_stochastic(attention)


def prog_L1H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Initial-token sink with boundary resets; dialogue resets share mass with
    nearby context and preceding boundaries instead of monopolizing attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "initial_sink_with_dialogue_boundary_sharing", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    pos = []
    dep = []
    clean = []
    for i, token in enumerate(tokens):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        pos.append(word.pos_ if word is not None else "")
        dep.append(word.dep_ if word is not None else "")
        clean.append(token.lstrip("ĠĊ").strip())

    # Include mojibake quotation punctuation in the dialogue detector.
    dialogue = any(mark in sentence for mark in ('"', "“", "”", "«", "»", "â€"))

    # Boundary strength and persistence are properties of the key token.
    boundary_strength = np.zeros(n)
    boundary_decay = np.zeros(n)
    punctuation_self = np.zeros(n)
    quote_open = False

    for i, text in enumerate(clean):
        terminal = any(mark in text for mark in (".", "!", "?", "。", "！", "？"))
        comma = any(mark in text for mark in (",", ";", ":", "，", "；", "："))
        quoted = any(mark in text for mark in ('"', "“", "”", "«", "»"))

        if terminal:
            boundary_strength[i] = 0.64
            boundary_decay[i] = 0.085
            punctuation_self[i] = 0.31
        elif comma:
            boundary_strength[i] = 0.55
            boundary_decay[i] = 0.14
            punctuation_self[i] = 0.24

        if quoted:
            opening = not quote_open
            if "“" in text or "«" in text:
                opening = True
            if "”" in text or "»" in text or terminal:
                opening = False
            quote_open = opening
            if opening and not terminal:
                boundary_strength[i] = 0.60
                boundary_decay[i] = 0.18

    attention[0, 0] = 1.0
    for i in range(1, n):
        # The first-token preference is strongest at the start and is not a
        # semantic subject/coreference relation.
        sink = 0.96 / (1.0 + 0.32 * (i - 1))
        sink *= np.exp(-0.018 * max(i - 5, 0))
        if i >= 2 and pos[i] == "AUX":
            sink += 0.11 * np.exp(-0.18 * (i - 2))
        if i >= 2 and pos[i] == "VERB" and dep[i] == "ROOT":
            sink += 0.12 * np.exp(-0.35 * (i - 3))
        sink = min(0.98, max(0.0, sink))

        keys = np.arange(1, i + 1)
        distances = i - keys
        weights = 0.35 + 0.65 * np.exp(-0.20 * distances)
        weights[-1] *= 0.65
        if i > 1:
            weights[-2] += 0.60

        for k, j in enumerate(keys):
            if pos[j] in ("ADP", "CCONJ", "SCONJ"):
                weights[k] += 1.8 * np.exp(-0.30 * (i - j))
            elif pos[j] == "DET":
                weights[k] += 0.95 * np.exp(-0.55 * (i - j))
            elif pos[j] == "AUX":
                weights[k] += 0.45 * np.exp(-0.40 * (i - j))

        weights /= weights.sum()
        row = np.zeros(i + 1)
        row[0] = sink
        row[1:] = (1.0 - sink) * weights

        # Only the most recent explicit boundary resets the local segment.
        anchor = -1
        for j in range(i - 1, 0, -1):
            if boundary_strength[j] > 0:
                anchor = j
                break
        if anchor >= 0:
            distance = i - anchor
            share = boundary_strength[anchor] * np.exp(
                -boundary_decay[anchor] * (distance - 1)
            )
            # Preserve the unusually strong early initial-token sink.
            share *= 1.0 - 0.70 * sink
            row *= 1.0 - share
            row[anchor] += share

            # Dialogue has competing boundaries, not a complete reset.
            # Transfer only reset-added mass, leaving the sink and diagonal
            # unchanged and retaining all original boundary decay rates.
            if dialogue:
                recipients = np.arange(1, i)
                redistribution = np.exp(-0.35 * (i - recipients))
                redistribution[recipients == anchor] = 0.0

                previous = -1
                for j in range(anchor - 1, 0, -1):
                    if boundary_strength[j] > 0:
                        previous = j
                        break
                if previous >= 0:
                    redistribution[previous - 1] += (
                        1.2 * np.exp(
                            -boundary_decay[previous] * (i - previous - 1)
                        )
                    )

                total = redistribution.sum()
                if total > 0:
                    transfer = 0.48 * share
                    row[anchor] -= transfer
                    row[recipients] += transfer * redistribution / total

        if punctuation_self[i] > 0:
            share = punctuation_self[i] * (1.0 - sink)
            row *= 1.0 - share
            row[i] += share

        attention[i, :i + 1] = row

    return "initial_sink_with_dialogue_boundary_sharing", make_row_stochastic(attention)


def prog_L1H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Initial sink with boundary-weighted recency; quoted dialogue shifts
    off-diagonal boundary mass toward content and whitespace anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "initial_sink_with_dialogue_recency", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    strengths = np.ones(n, dtype=np.float64)

    # Restrict the correction to quoted dialogue, leaving ordinary prose intact.
    dialogue = sum(c in '"“”' for c in sentence) >= 2
    dialogue_factors = np.ones(n, dtype=np.float64)

    for j, token in enumerate(tokens):
        clean = token.replace("Ġ", " ").replace("Ċ", "\n").strip()
        aligned = [doc[k] for k in alignment[j] if k < len(doc)]
        words = [w for w in aligned if not w.is_space]
        word = words[-1] if words else None

        if clean and all(c in ",;:!?." for c in clean):
            strengths[j] = 2.55
        elif clean and all(c in "\"'“”‘’«»!?." for c in clean):
            strengths[j] = 2.0
        elif not clean:
            strengths[j] = 0.65
        elif word is not None:
            if word.pos_ == "CCONJ":
                strengths[j] = 2.8
            elif word.pos_ in ("ADP", "SCONJ"):
                strengths[j] = 1.95
            elif word.pos_ == "AUX":
                strengths[j] = 1.35
            elif word.pos_ in ("DET", "PRON"):
                strengths[j] = 1.05
            elif word.pos_ in ("ADJ", "ADV"):
                strengths[j] = 0.72
            elif word.pos_ in ("NOUN", "PROPN"):
                strengths[j] = 0.85
            elif word.pos_ == "PUNCT":
                strengths[j] = 1.8
            else:
                strengths[j] = 0.95

            # Avoid treating every subword as a separate linguistic boundary.
            if j > 0 and alignment[j] and alignment[j - 1]:
                if any(k in alignment[j - 1] for k in alignment[j]):
                    strengths[j] *= 0.75

        if dialogue:
            if not clean:
                dialogue_factors[j] = 1.9
            elif all(c in ",;:!?.\"'“”‘’«»" for c in clean):
                dialogue_factors[j] = 0.70
            elif word is not None:
                if word.pos_ == "CCONJ":
                    dialogue_factors[j] = 0.55
                elif word.pos_ in ("DET", "PRON"):
                    dialogue_factors[j] = 1.35
                elif word.pos_ in ("NOUN", "PROPN", "VERB", "ADJ", "ADV"):
                    dialogue_factors[j] = 1.30

    if dialogue:
        dialogue_factors[0] = 0.85
        if n > 1:
            dialogue_factors[1] *= 4.0

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(i + 1)
        age = i - positions
        row = strengths[:i + 1] * np.exp(-age / 11.0)

        # The second absolute position is strongly suppressed, even when
        # its lexical category would ordinarily attract attention.
        row[1] *= 0.065
        row[0] = 4.1 * np.exp(-0.115 * max(i - 2, 0))

        attention[i, :i + 1] = row / row.sum()

        if dialogue and i > 1:
            # Redistribute only past-token mass: preserve the original
            # normalized self-attention and the original recency decay.
            past_mass = attention[i, :i].sum()
            corrected = attention[i, :i] * dialogue_factors[:i]
            attention[i, :i] = corrected * (past_mass / corrected.sum())

    return "initial_sink_with_dialogue_recency", attention


def prog_L1H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with secondary sinks at completed sentence boundaries.
    Boundary boosts draw only from the first token, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_boundary_sinks", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Include sentence-ending punctuation fused with closing quotation marks.
    boundaries = []
    for j, token in enumerate(tokens):
        clean = token.lstrip("\u0120").strip()
        if (
            j > 0
            and any(c in ".!?" for c in clean)
            and all(c in ".!?\"'“”‘’»)]}" for c in clean)
        ):
            boundaries.append(j)

    for i in range(1, n):
        late_growth = 0.22 * (1.0 - np.exp(-max(i - 7, 0) / 22.0))
        early_bump = 0.09 * np.exp(-((i - 1.7) / 2.2) ** 2)
        sink_mass = 0.50 + late_growth + early_bump

        aligned = alignment[i]
        if aligned:
            source = doc[aligned[-1]]
            if source.pos_ == "PUNCT":
                sink_mass += 0.008
            elif source.pos_ in ("NOUN", "PROPN") and i <= 3:
                sink_mass += 0.015

        sink_mass = np.clip(sink_mass, 0.45, 0.75)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        recent = np.exp(-distances / 5.0)
        recent /= recent.sum()
        background = 0.70 / i + 0.30 * recent
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

        # Only completed boundaries receive extra mass; never alter the diagonal
        # or redistribute any of the original diffuse background.
        preceding = [j for j in boundaries if j < i]
        if preceding:
            boosts = 0.05 * np.exp(
                -(i - np.asarray(preceding) - 1) / 10.0
            )
            total = boosts.sum()
            budget = min(0.08, attention[i, 0])
            if total > budget:
                boosts *= budget / total
            attention[i, preceding] += boosts
            attention[i, 0] -= boosts.sum()

    return "first_token_sink_with_boundary_sinks", make_row_stochastic(attention)


def prog_L1H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with a long-context recency correction.
    Preserve sink decay and self-attention; redistribute only older off-diagonal mass.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[0, 0] = 1.0
            continue

        sink_mass = 0.12 + 0.88 * np.exp(-0.125 * i)
        attention[i, 0] = sink_mass

        positions = np.arange(i, dtype=np.float64)
        early_prior = np.exp(-0.16 * positions)
        early_prior /= early_prior.sum()

        residual_prior = 0.8 * early_prior + 0.2 / i
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual_prior

        # Longer prefixes need recency rather than a persistent early-token bias.
        # Leave both the first-token sink and the diagonal exactly unchanged.
        if i > 16:
            off_diagonal_mass = attention[i, 1:i].sum()
            distances = i - np.arange(1, i, dtype=np.float64)
            recent_prior = np.exp(-distances / 5.0)
            recent_prior /= recent_prior.sum()
            corrected_prior = 0.65 * recent_prior + 0.35 / (i - 1)

            strength = 1.0 - np.exp(-(i - 16) / 6.0)
            attention[i, 1:i] = (
                (1.0 - strength) * attention[i, 1:i]
                + strength * off_diagonal_mass * corrected_prior
            )

    return "first_token_sink_with_long_context_recency", attention


def prog_L1H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with position-decaying strength, plus self-attention
    on relation markers and punctuation and weaker grammatical-type matching.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "decaying_sink_marker_self", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [
        doc[indices[0]] if indices else None
        for indices in alignment
    ]
    pos = [w.pos_ if w is not None else "" for w in words]
    dep = [w.dep_ if w is not None else "" for w in words]
    clean = [t.lstrip("Ġ").lstrip("Ċ").strip() for t in tokens]
    comma = ["," in t for t in clean]
    quote = [any(c in t for c in "\"'“”‘’") for t in clean]
    terminal = [any(c in t for c in ".!?;:") for t in clean]

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink = 0.95 * np.exp(-i / 8.0) + 0.10 * np.exp(-i / 65.0)
        self_mass = 0.075 + 0.105 * (1.0 - np.exp(-i / 15.0))

        if pos[i] in ("ADJ", "ADV"):
            sink *= 0.88
        elif pos[i] == "VERB":
            sink *= 0.94

        marker = (
            pos[i] in ("ADP", "SCONJ")
            or (pos[i] == "PART" and dep[i] in ("aux", "mark"))
        )
        if marker:
            sink *= 0.28
            self_mass = 0.76 / (1.0 + i / 42.0)
        elif comma[i]:
            if i <= 2:
                self_mass = 0.25
            else:
                sink *= 0.65
                self_mass = 0.60 / (1.0 + i / 35.0)
        elif pos[i] == "CCONJ":
            self_mass = 0.37 / (1.0 + i / 35.0)
        elif terminal[i]:
            sink *= 0.65
            self_mass = 0.34 / (1.0 + i / 40.0)
        elif quote[i] or not clean[i]:
            self_mass = 0.24 / (1.0 + i / 65.0)
        elif dep[i] in ("poss", "nsubj", "nsubjpass"):
            self_mass += 0.05

        sink = min(float(sink), 0.98)
        self_mass = min(float(self_mass), 1.0 - sink)
        attention[i, 0] = sink
        attention[i, i] = self_mass
        remaining = 1.0 - sink - self_mass

        if i == 1:
            attention[i, i] += remaining
            continue

        weights = np.zeros(i - 1, dtype=np.float64)
        for j in range(1, i):
            distance = i - j
            weight = 0.15 + 0.08 * np.exp(-distance / 14.0)

            # Boundary tokens form persistent secondary attention anchors.
            if comma[j]:
                weight += 0.85
                if comma[i]:
                    weight += 2.0
            elif terminal[j]:
                weight += 0.32
                if quote[i] or terminal[i]:
                    weight += 0.90
            elif quote[j] and quote[i]:
                weight += 0.50

            if pos[i] and pos[i] == pos[j]:
                weight += 0.18
                if pos[i] in ("NOUN", "PROPN", "VERB", "ADJ", "ADV"):
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    weight += 0.45 * np.exp(
                        np.clip(6.0 * (similarity - 0.35), -4.0, 2.5)
                    )
                elif marker:
                    weight += 0.18

            if (
                words[i] is not None
                and words[j] is not None
                and words[i].i != words[j].i
                and words[i].dep_ == words[j].dep_
                and pos[i] in ("NOUN", "PROPN", "VERB")
            ):
                weight += 0.20

            weights[j - 1] = weight

        attention[i, 1:i] = remaining * weights / weights.sum()

    return "decaying_sink_marker_self", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L1H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink fading with distance, with secondary attention
    to salient content anchors, related words, and quotation/subword boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_content_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [doc[a[0]] if a else None for a in alignment]
    clean = [t.lstrip("Ġ").lstrip("▁") for t in tokens]

    # Identify model-token pieces belonging to the same linguistic word.
    word_start = list(range(n))
    for i in range(1, n):
        if alignment[i] and alignment[i - 1]:
            if alignment[i][0] == alignment[i - 1][0]:
                word_start[i] = word_start[i - 1]

    # Quote boundaries are tracked separately from ordinary punctuation.
    quote_for = [None] * n
    active_quote = None
    previous_close = None
    last_close = [None] * n
    for i in range(n):
        last_close[i] = previous_close
        text = clean[i]
        has_quote = any(c in text for c in ('"', '“', '”', '«', '»'))
        if has_quote:
            closing = active_quote is not None and (
                any(c in text for c in ('”', '»'))
                or any(c in text for c in ('?', '!', '.'))
                or text.strip() == '"'
            )
            if closing:
                quote_for[i] = active_quote
                previous_close = i
                active_quote = None
            else:
                active_quote = i
        elif active_quote is not None:
            quote_for[i] = active_quote

    attention[0, 0] = 1.0
    for i in range(1, n):
        wi = words[i]
        pos = wi.pos_ if wi is not None else ""
        dep = wi.dep_ if wi is not None else ""

        sink = 1.0 / (1.0 + (i / 7.0) ** 1.6)
        if i > 1 and pos == "NOUN":
            sink *= 0.79
        elif i > 3 and pos == "PROPN":
            sink *= 0.90

        scores = np.zeros(i + 1, dtype=np.float64)
        for j in range(1, i + 1):
            wj = words[j]
            distance = i - j
            score = 0.18 + 0.25 * np.exp(-distance / 7.0)

            if wj is not None:
                if wj.pos_ in ("NOUN", "PROPN", "PRON"):
                    score += 0.60
                    if wj.dep_ in ("nsubj", "nsubjpass", "csubj"):
                        score += 1.05
                    if wj.pos_ == "PROPN":
                        score += 0.35
                if wj.pos_ == "VERB":
                    score += 0.35
                    if any(c.dep_ in ("ccomp", "parataxis") for c in wj.children):
                        score += 1.0

                if wi is not None and j < i:
                    if wi.head.i == wj.i and wi.i != wj.i:
                        score += 0.65
                    if pos in ("PRON", "DET") and dep in (
                        "poss", "nsubj", "nsubjpass", "dobj", "pobj"
                    ):
                        if wj.pos_ in ("NOUN", "PROPN"):
                            score += 0.65 * np.exp(-distance / 24.0)

                    if (
                        pos in ("NOUN", "PROPN", "VERB")
                        and wj.pos_ == pos
                        and word_start[j] == j
                        and distance <= 48
                    ):
                        similarity = embedding_similarity(tokens, i, j, tokenizer)
                        score += 6.0 * max(0.0, similarity - 0.25)

            if j == i:
                score += 0.25
                if pos in ("NOUN", "PROPN"):
                    score += 1.4
            scores[j] = score

        # Continuations can resolve back to the beginning of their word.
        start = word_start[i]
        if start < i and start > 0:
            scores[start] += 7.0
            sink *= 0.75

        if quote_for[i] is not None and quote_for[i] < i:
            q = quote_for[i]
            if any(c in clean[i] for c in ('"', '”', '»')):
                scores[q] += 9.0
                sink *= 0.70

        if not clean[i].strip():
            scores[i] += 5.0
            for j in range(1, i):
                if not clean[j].strip():
                    scores[j] += 3.0

        if (
            last_close[i] is not None
            and wi is not None
            and wi.is_punct
            and any(c in clean[i] for c in (".", "!", "?"))
        ):
            scores[last_close[i]] += 5.0

        attention[i, 0] = sink
        total = scores[1:].sum()
        attention[i, 1:i + 1] = (1.0 - sink) * scores[1:] / total

    return "first_token_sink_with_content_anchors", make_row_stochastic(attention)


def prog_L1H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with position-dependent dilution.
    In quoted dialogue, punctuation anchors attract extra off-diagonal residual attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    salience = np.ones(n, dtype=np.float64)
    content = np.zeros(n, dtype=bool)
    for j, indices in enumerate(alignment):
        if not indices:
            continue
        word = doc[indices[0]]
        if word.pos_ in ("NOUN", "PROPN"):
            salience[j] = 1.8
            content[j] = True
        elif word.pos_ in ("ADJ", "ADV"):
            salience[j] = 1.25
            content[j] = True
        elif word.pos_ == "VERB":
            salience[j] = 1.1
            content[j] = True
        elif word.pos_ in ("PUNCT", "SPACE"):
            salience[j] = 0.8

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 1.0 / (1.0 + 0.065 * i ** 1.45)
        if i == 1:
            sink_mass = 0.955

        positions = np.arange(1, i + 1)
        distances = i - positions
        residual = salience[1:i + 1] * (
            0.3 + np.exp(-distances / 14.0)
        )

        # A small content-to-content preference captures secondary edges
        # without treating this primarily positional head as a syntax head.
        if content[i]:
            residual *= np.where(content[1:i + 1], 1.15, 1.0)

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    # Dialogue boundaries are stronger keys than ordinary punctuation.
    # Redistribute only non-sink, off-diagonal mass: the original sink,
    # diagonal weights, and positional decay remain untouched.
    if any(c in sentence for c in ('"', '“', '”')):
        boundary = np.zeros(n, dtype=bool)
        for j, indices in enumerate(alignment):
            boundary[j] = (
                any(doc[k].pos_ == "PUNCT" for k in indices)
                and any(c in tokens[j] for c in ',;:!?."“”')
            )

        for i in range(2, n):
            if not np.any(boundary[1:i]):
                continue
            original_mass = attention[i, 1:i].sum()
            adjusted = attention[i, 1:i] * np.where(
                boundary[1:i], 2.2, 1.0
            )
            if original_mass > 0.0:
                attention[i, 1:i] = (
                    original_mass * adjusted / adjusted.sum()
                )

    return "first_token_sink_with_dialogue_anchors", attention


def prog_L1H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with diffuse residual attention.
    Quoted discourse and prepositional openings add persistent determiner anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_determiner_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    pos = [""] * n
    punctuation = np.zeros(n, dtype=bool)
    whitespace = np.zeros(n, dtype=bool)

    for i, indices in enumerate(alignment):
        if indices:
            word = doc[indices[0]]
            pos[i] = word.pos_
            punctuation[i] = word.is_punct
            whitespace[i] = word.is_space
        else:
            clean = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")
            whitespace[i] = bool(clean) and clean.isspace()
            stripped = clean.strip()
            punctuation[i] = bool(stripped) and all(
                not c.isalnum() for c in stripped
            )

    key_weights = np.ones(n, dtype=np.float64)
    for j in range(n):
        if punctuation[j]:
            key_weights[j] = 1.65
        elif pos[j] in ("CCONJ", "SCONJ"):
            key_weights[j] = 1.45
        elif pos[j] in ("DET", "ADP"):
            key_weights[j] = 1.08
        elif pos[j] in ("VERB", "AUX"):
            key_weights[j] = 0.92
        if whitespace[j]:
            key_weights[j] = 0.70

    initial_factor = 0.88
    if pos[0] == "DET":
        initial_factor = 1.15
    elif pos[0] == "PRON":
        initial_factor = 0.84
    elif pos[0] in ("ADP", "ADV", "SCONJ"):
        initial_factor = 0.76

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(1, i + 1)
        residual = key_weights[1:i + 1].copy()
        residual *= 1.0 + 0.12 * np.exp(-(i - positions) / 4.0)

        sink = initial_factor * (6.7 + 23.0 * np.exp(-i / 2.5))
        if punctuation[i]:
            sink *= 0.83
            residual[-1] *= 1.25
        elif pos[i] in ("NOUN", "PROPN"):
            sink *= 0.92
        elif pos[i] in ("VERB", "AUX", "ADV"):
            sink *= 1.06
        if whitespace[i]:
            sink *= 1.08

        attention[i, 0] = sink
        attention[i, 1:i + 1] = residual

    attention = make_row_stochastic(attention)

    # Transfer probability only on selected off-diagonal edges, preserving
    # every self-attention weight and leaving ordinary sentences unchanged.
    quoted = any(c in sentence for c in ('"', "“", "”"))
    prepositional_opening = pos[0] == "ADP"
    if quoted or prepositional_opening:
        anchors = [
            j for j in range(1, n)
            if pos[j] == "DET"
            and alignment[j]
            and doc[alignment[j][0]].dep_ == "det"
        ]
        for i in range(1, n):
            preceding = [j for j in anchors if j < i]
            if not preceding:
                continue
            anchor_mass = attention[i, preceding].sum()
            if anchor_mass <= 0.0:
                continue
            proportions = attention[i, preceding] / anchor_mass

            if prepositional_opening:
                content = [
                    j for j in range(1, i)
                    if pos[j] in ("NOUN", "PROPN", "ADJ")
                ]
                removed = 0.45 * attention[i, content]
                attention[i, content] -= removed
                released = removed.sum()
                attention[i, 0] += 0.55 * released
                attention[i, preceding] += 0.45 * released * proportions
            else:
                transferred = min(
                    0.90 * anchor_mass, 0.32 * attention[i, 0]
                )
                attention[i, 0] -= transferred
                attention[i, preceding] += transferred * proportions

    return "first_token_sink_with_determiner_anchors", attention


def prog_L1H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with gradually increasing causal background.
    Linguistic features weakly modulate the sink's strength."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    first_pos = ""
    if alignment[0]:
        first_pos = doc[alignment[0][0]].pos_

    sink_strength = 7.5
    ramp_scale = 6.0
    if first_pos == "DET":
        sink_strength = 9.0
    elif first_pos in ("ADP", "ADV", "SCONJ"):
        sink_strength = 5.5
        ramp_scale = 4.0
    elif first_pos == "PRON":
        sink_strength = 7.0

    attention[0, 0] = 1.0
    for i in range(1, n):
        # Additional keys become competitive gradually, rather than immediately
        # diluting the first token as in ordinary uniform causal attention.
        activation = 1.0 - np.exp(-i / ramp_scale)
        distances = i - np.arange(1, i + 1)
        background = 0.9 + 0.1 * np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = activation * background

        query_factor = 1.0
        if alignment[i]:
            word = doc[alignment[i][-1]]
            if word.pos_ in ("NOUN", "PROPN"):
                query_factor = 1.08
            elif word.pos_ == "PUNCT":
                query_factor = 0.93
            elif word.pos_ == "DET":
                query_factor = 0.95
        elif tokens[i].isspace() or not tokens[i].strip("\u0120"):
            query_factor = 0.85

        attention[i, 0] = sink_strength * query_factor

    return "first_token_sink_with_dilution", make_row_stochastic(attention)


def prog_L1H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Broad causal averaging, with reduced cross-boundary attention after
    quoted sentence endings while preserving the original self-attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "quoted_boundary_redistribution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    key_scores = np.zeros(n, dtype=np.float64)
    positions = np.arange(n, dtype=np.float64)
    pos_tags = []
    quoted_endings = []

    for j, token in enumerate(tokens):
        aligned = alignment[j]
        word = doc[aligned[-1]] if aligned else None
        pos = word.pos_ if word is not None else ""
        pos_tags.append(pos)

        if pos in ("VERB", "NOUN", "PROPN"):
            key_scores[j] += 0.12
        elif pos in ("DET", "ADP", "PART"):
            key_scores[j] -= 0.16
        elif pos in ("PRON", "ADV", "CCONJ", "SCONJ"):
            key_scores[j] -= 0.05

        surface = token.lstrip("ĠĊ")
        if any(mark in surface for mark in (".", "!", "?")):
            key_scores[j] += 1.15
            # GPT-2 may merge the terminator and closing quote, or split them.
            has_closing_quote = any(mark in surface for mark in ('"', "”", "»"))
            if not has_closing_quote and j + 1 < n:
                following = tokens[j + 1].lstrip("ĠĊ")
                has_closing_quote = (
                    bool(following)
                    and all(mark in ('"', "”", "»") for mark in following)
                )
            if has_closing_quote:
                quoted_endings.append(j)
        elif surface and all(mark in ",;:" for mark in surface):
            key_scores[j] += 0.05
        elif not surface or surface.isspace():
            key_scores[j] -= 0.35

    if n > 1:
        key_scores[1] += 0.20

    attention[0, 0] = 1.0
    latest_quoted_end = -1
    for i in range(1, n):
        logits = key_scores[:i + 1].copy()
        logits -= 0.018 * (i - positions[:i + 1])
        logits[i] += 0.12

        # Noun completion can favor the current token over its modifier.
        if pos_tags[i] in ("NOUN", "PROPN") and pos_tags[i - 1] == "ADJ":
            logits[i] += 0.20

        # The first position is effectively absent after its own query.
        logits[0] = -12.0
        logits -= np.max(logits)
        weights = np.exp(logits)
        attention[i, :i + 1] = weights / weights.sum()

        if i - 1 in quoted_endings:
            latest_quoted_end = i - 1

        # Only dialogue continuations use this path. Redistribute historical
        # mass toward the new segment without changing the diagonal weight.
        if latest_quoted_end >= 0 and i > latest_quoted_end + 1:
            history = attention[i, :i].copy()
            original_mass = history.sum()
            history[:latest_quoted_end + 1] *= 0.60
            for boundary in quoted_endings:
                if boundary >= i:
                    break
                history[boundary] *= np.exp(-0.75)
            history *= original_mass / history.sum()
            attention[i, :i] = history

    return "quoted_boundary_redistribution", attention


def prog_L1H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Self-dominant attention with selective lexical recurrence.
    Punctuation instead retrieves structural boundaries and matching quotes.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "self_with_recurrence", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    # Metadata used only by the special-case handlers below.
    texts = [t.replace("Ġ", " ").replace("Ċ", "\n") for t in tokens]
    positions = [{doc[k].pos_ for k in a} for a in alignment]
    quote_marks = {'"', "“", "”"}
    open_quotes = []

    for i in range(1, n):
        aligned = alignment[i]
        pos = {doc[k].pos_ for k in aligned}
        text = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")

        if text.isspace():
            self_weight = 0.85
        elif pos and pos <= {"PUNCT", "SPACE"}:
            self_weight = 0.60
        elif pos & {"VERB", "ADJ", "ADV"}:
            self_weight = 0.89
        elif pos & {"NOUN", "PROPN", "NUM"}:
            self_weight = 0.86
        elif pos & {"AUX", "PART"}:
            self_weight = 0.83
        elif pos & {"DET", "PRON", "ADP", "CCONJ", "SCONJ"}:
            self_weight = 0.79
        else:
            self_weight = 0.84

        distances = i - np.arange(i, dtype=np.float64)
        residual = np.exp(-distances / 4.0)
        residual /= residual.sum()
        residual *= 0.55
        residual[0] += 0.45

        attention[i, :i] = (1.0 - self_weight) * residual
        attention[i, i] = self_weight

        # Only punctuation and high-confidence recurrence override the default.
        punctuation = bool(pos) and pos <= {"PUNCT", "SPACE"}
        has_quote = any(c in quote_marks for c in text)
        bare_quote = has_quote and all(
            c.isspace() or c in quote_marks for c in text
        )

        if has_quote:
            if bare_quote:
                attention[i] = 0.0
                attention[i, :i] = 0.15 * residual
                attention[i, i] = 0.85
                if open_quotes:
                    attention[i, i] -= 0.20
                    attention[i, open_quotes[-1]] += 0.20
                open_quotes.append(i)
            elif open_quotes:
                attention[i] = 0.0
                attention[i, :i] = 0.20 * residual
                attention[i, i] = 0.40
                attention[i, open_quotes[-1]] += 0.40

        elif punctuation and not text.isspace():
            # Boundary tokens pool broadly, rather than copying themselves.
            structural = np.full(i, 0.15, dtype=np.float64)
            for j in range(i):
                if positions[j] & {"DET", "ADP", "AUX", "PART", "SCONJ", "CCONJ"}:
                    structural[j] += 0.85
                if positions[j] and positions[j] <= {"PUNCT", "SPACE"}:
                    structural[j] += 1.35
            structural[0] += 1.50
            structural /= structural.sum()
            boundary_self = 0.12 + 0.12 * np.exp(-i / 10.0)
            attention[i, :i] = (1.0 - boundary_self) * structural
            attention[i, i] = boundary_self

        elif not has_quote and not punctuation:
            matches = []
            for j in range(1, i):
                compatible = bool(pos & positions[j]) or (
                    bool(pos & {"VERB", "AUX"})
                    and bool(positions[j] & {"VERB", "AUX"})
                )
                if compatible or (text.isspace() and texts[j].isspace()):
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    if similarity >= 0.80:
                        matches.append((j, similarity))

            if matches:
                weights = np.array(
                    [(s - 0.79) ** 2 for _, s in matches], dtype=np.float64
                )
                weights /= weights.sum()
                fraction = 0.50 if pos & {"PROPN", "PRON", "DET"} else 0.32
                if text.isspace():
                    fraction = 0.45
                transfer = fraction * attention[i, i]
                attention[i, i] -= transfer
                for (j, _), weight in zip(matches, weights):
                    attention[i, j] += transfer * weight

    return "self_with_recurrence", attention


def prog_L2H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink and phrase onsets, with persistent subject anchors.
    Predicate spans sometimes retain their subject rather than the previous token.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_sink_with_subject_anchors", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    owners = []
    first_piece = {}
    for i, indices in enumerate(alignment):
        # Prefer actual lexical overlap over whitespace-only alignment.
        candidates = [k for k in indices if not doc[k].is_space]
        owner = candidates[0] if candidates else None
        owners.append(owner)
        if owner is not None and owner not in first_piece:
            first_piece[owner] = i

    strength = np.zeros(n, dtype=np.float64)
    for i, owner in enumerate(owners):
        if owner is None or first_piece[owner] != i:
            continue
        word = doc[owner]
        if word.pos_ == "ADP":
            strength[i] = 2.6
        elif word.tag_ in ("TO", "MD"):
            strength[i] = 3.0
        elif word.pos_ == "CCONJ":
            strength[i] = 1.4
        elif word.pos_ == "SCONJ":
            strength[i] = 1.1
        elif word.pos_ == "AUX":
            strength[i] = 0.55
        elif word.pos_ == "VERB":
            strength[i] = 0.75
        elif word.pos_ == "ADV":
            strength[i] = 0.7
        elif word.pos_ == "ADJ":
            strength[i] = 0.4

    # Definite nominal subjects and punctuation-delimited pronominal subjects
    # can remain anchors throughout their own predicate span.
    subject_anchors = []
    for owner, piece in first_piece.items():
        word = doc[owner]
        if piece == 0 or word.dep_ not in ("nsubj", "nsubjpass"):
            continue
        nominal = (
            word.pos_ in ("NOUN", "PROPN")
            and any(child.dep_ == "det" for child in word.children)
        )
        quoted_pronoun = (
            word.pos_ == "PRON"
            and owner > 0
            and doc[owner - 1].is_punct
        )
        if nominal or quoted_pronoun:
            subject_anchors.append((piece, word.head.i))
    subject_anchors.sort()

    matrix[0, 0] = 1.0
    for i in range(1, n):
        owner = owners[i]
        word = doc[owner] if owner is not None else None
        ancestors = set()
        if word is not None:
            ancestors = {ancestor.i for ancestor in word.ancestors}

        distances = i - np.arange(i + 1)
        local = 0.10 * np.exp(-distances / 4.0)
        local[0] = 0.0
        local[i] += 0.24
        if i > 1:
            local[i - 1] += 0.65

        nearby_anchor = 0.0
        for j in range(max(1, i - 14), i + 1):
            if strength[j] == 0.0:
                continue
            distance = i - j
            if distance == 0:
                local[j] += 0.27 * strength[j]
                continue

            source = owners[j]
            related = (
                owner is not None
                and source is not None
                and (
                    source in ancestors
                    or doc[source].head.i == owner
                    or doc[source].head.i in ancestors
                )
            )
            contribution = strength[j] * np.exp(-(distance - 1) / 3.3)
            contribution *= 1.15 if related else 0.72

            # Punctuation limits propagation of an earlier phrase anchor.
            for k in range(j + 1, i):
                mid = owners[k]
                if mid is not None and mid != source and doc[mid].is_punct:
                    contribution *= 0.65

            local[j] += contribution
            nearby_anchor = max(nearby_anchor, contribution)

        # Split words retain the surrounding phrase's anchor rather than
        # forcing all attention onto the immediately preceding subtoken.
        if owner is not None and first_piece[owner] < i:
            local[first_piece[owner]] += 0.30

        sink = 0.12 + 0.84 * np.exp(-(i - 1) / 3.7)
        if i > 3:
            sink /= 1.0 + 0.35 * nearby_anchor
        if word is not None and word.is_punct and i > 6:
            sink = min(0.32, sink + 0.07)

        matrix[i, :i + 1] = (1.0 - sink) * local / local.sum()
        matrix[i, 0] = sink

        # Move mass only between two existing causal positions; preserve
        # self-attention and leave strong phrase-onset edges untouched.
        if word is not None and first_piece[owner] == i:
            for anchor, predicate in reversed(subject_anchors):
                if not (anchor < i and i - anchor <= 8):
                    continue
                if predicate != owner and predicate not in ancestors:
                    continue
                if anchor < i - 1 and strength[i - 1] <= 1.0:
                    moved = 0.50 * matrix[i, i - 1]
                    matrix[i, i - 1] -= moved
                    matrix[i, anchor] += moved
                elif anchor == i - 1 and predicate == owner:
                    moved = 0.23 * matrix[i, 0]
                    matrix[i, 0] -= moved
                    matrix[i, anchor] += moved
                break

    return "first_sink_with_subject_anchors", make_row_stochastic(matrix)


def prog_L2H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with gradual positional dilution.
    Linguistic features modulate sink strength; residual attention favors recency.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    positions = np.arange(n, dtype=np.float64)

    first_pos = ""
    if alignment[0]:
        first_pos = doc[alignment[0][0]].pos_

    initial_strength = 1.0
    if first_pos in ("PRON", "PROPN"):
        initial_strength = 1.15
    elif first_pos == "DET":
        initial_strength = 0.90

    attention[0, 0] = 1.0

    for i in range(1, n):
        strength = initial_strength
        mapped = alignment[i]

        if mapped:
            word = doc[mapped[0]]
            pos = word.pos_

            if pos in ("ADP", "AUX", "PRON", "SCONJ", "PART"):
                strength *= 1.20
            elif pos in ("NOUN", "PROPN"):
                strength *= 0.80
            elif pos in ("VERB", "ADJ"):
                strength *= 0.90
            elif pos == "SPACE":
                strength *= 0.65

            # Continuation pieces often preserve stronger sink attention.
            if i > 1 and alignment[i - 1]:
                if mapped[0] == alignment[i - 1][0]:
                    strength *= 1.30
        elif tokens[i].isspace() or tokens[i] == "\u0120":
            strength *= 0.65

        dilution = 0.018 * (i ** 1.35)
        sink_mass = strength / (strength + dilution)

        distances = i - positions[1:i + 1]
        residual = 0.65 + np.exp(-distances / 5.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_dilution", attention


def prog_L2H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local phrase-onset attention; infinitival complements retain their
    adjacent marker rather than being redirected to the governing verb."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_phrase_onset", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if 0 <= wi < len(doc):
                word_tokens[wi].append(ti)

    attention[0, 0] = 1.0
    for i in range(1, n):
        # Residual attention is mostly local, with a weak first-token sink.
        background = np.zeros(i + 1, dtype=np.float64)
        background[0] += 0.12
        background[i] += 0.28
        for j in range(max(0, i - 6), i):
            background[j] += 0.60 * np.exp(-0.75 * (i - 1 - j))
        background /= background.sum()

        target = i - 1
        confidence = 0.65
        word_ids = alignment[i]
        wi = word_ids[-1] if word_ids else None

        if wi is not None:
            word = doc[wi]
            pieces = word_tokens[wi]
            earlier_pieces = [p for p in pieces if p < i]

            if earlier_pieces and not word.is_punct and not word.is_space:
                target = pieces[0]
                confidence = 0.92
            elif word.is_space:
                confidence = 0.80
            elif word.is_punct:
                if any(c in ".!?" for c in word.text):
                    target = i
                    confidence = 0.58
                elif any(c in "\"'“”‘’" for c in word.text):
                    confidence = 0.62
                else:
                    confidence = 0.55
            else:
                previous_ids = alignment[i - 1]
                previous = doc[previous_ids[-1]] if previous_ids else None

                if word.pos_ in ("DET", "PRON"):
                    confidence = 0.81
                elif word.pos_ in ("ADP", "PART", "AUX"):
                    confidence = 0.77
                elif word.pos_ in ("CCONJ", "SCONJ"):
                    confidence = 0.73

                if previous is not None:
                    if previous.pos_ in ("ADP", "AUX", "PART"):
                        confidence = 0.87
                    elif previous.is_punct:
                        confidence = 0.76
                    elif (
                        previous.pos_ == "VERB"
                        and word.pos_ in ("DET", "PRON")
                    ):
                        confidence = 0.85

                # Nominal material inside a short PP shares its preposition
                # anchor, rather than always choosing the adjacent determiner.
                node = word
                for _ in range(4):
                    if node.head.i == node.i:
                        break
                    parent = node.head
                    if parent.pos_ == "ADP":
                        candidates = word_tokens[parent.i]
                        if candidates:
                            anchor = candidates[0]
                            if 0 <= anchor < i and i - anchor <= 5:
                                target = anchor
                                confidence = 0.86 if i - anchor <= 2 else 0.79
                        break
                    if node.dep_ not in (
                        "det", "amod", "advmod", "compound", "nummod",
                        "poss", "quantmod", "pobj", "obl"
                    ):
                        break
                    node = parent

                # Finite auxiliaries can remain the anchor across a subject
                # or adverb; infinitival markers anchor their lexical verb.
                if word.pos_ in ("VERB", "ADJ", "ADV"):
                    anchors = []
                    for child in word.children:
                        if child.dep_ in ("aux", "auxpass", "cop", "mark"):
                            positions = word_tokens[child.i]
                            if positions and 0 < i - positions[0] <= 4:
                                anchors.append(positions[0])
                    if anchors:
                        target = max(anchors)
                        confidence = 0.86

                # Contracted verbal constructions may retain the earlier verb.
                if word.dep_ in ("xcomp", "ccomp"):
                    positions = word_tokens[word.head.i]
                    if positions and 1 < i - positions[0] <= 3:
                        between = doc[word.head.i + 1:word.i]
                        if any(w.pos_ == "PART" for w in between):
                            target = positions[0]
                            confidence = 0.80

                # An adjacent infinitival marker takes precedence over the
                # governing-verb fallback. Redirect only the concentrated mass:
                # confidence, background, and self-attention remain unchanged.
                if (
                    word.pos_ == "VERB"
                    and word.dep_ in ("xcomp", "ccomp")
                    and previous is not None
                    and previous.pos_ == "PART"
                    and previous.dep_ in ("aux", "mark")
                    and previous.head.i == word.i
                ):
                    target = i - 1

        if i == 1:
            target = 0
            confidence = 0.995

        attention[i, :i + 1] = (1.0 - confidence) * background
        attention[i, target] += confidence

    return "local_phrase_onset", make_row_stochastic(attention)


def prog_L2H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attend to local phrase onsets; explicit possessive markers open a new
    phrase, while the marker itself retains the possessor's nominal onset.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "possessive_phrase_onset", attention

    doc = spacy_parse(sentence)
    forward = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    starts = {}
    for word in doc:
        if inverse[word.i]:
            starts[word.i] = inverse[word.i][0]

    # A nominal's onset is its determiner/possessor, or its first modifier.
    nominal_onsets = {}
    for word in doc:
        if word.pos_ not in ("NOUN", "PROPN", "PRON"):
            continue
        determiners = [
            child for child in word.children
            if child.i < word.i and child.dep_ in ("det", "poss", "nmod:poss")
        ]
        modifiers = [
            child for child in word.children
            if child.i < word.i and child.dep_ in ("amod", "nummod", "compound")
        ]
        candidates = determiners if determiners else modifiers
        onset = min(candidates, key=lambda child: child.i) if candidates else word
        nominal_onsets[word.i] = onset.i

    anchor_strength = {}
    for word in doc:
        if word.i not in starts:
            continue
        strength = 0.0
        if word.dep_ in ("det", "poss", "nmod:poss") or word.pos_ == "DET":
            strength = 1.9
            if "Ind" in word.morph.get("Definite"):
                strength = 1.25
        elif word.tag_ in ("WDT", "WP", "WP$", "WRB"):
            strength = 2.1
        elif word.pos_ == "SCONJ" or word.dep_ == "mark":
            strength = 1.7
        elif word.pos_ == "PRON" and word.dep_ in (
            "nsubj", "nsubjpass", "csubj", "csubjpass"
        ):
            strength = 1.45
        elif word.pos_ == "ADV" and (
            word.i == 0 or doc[word.i - 1].is_punct
        ):
            strength = 1.05
        elif word.pos_ == "ADP":
            strength = 0.75
        elif word.pos_ in ("VERB", "ADJ"):
            strength = 0.45
        if strength:
            anchor_strength[starts[word.i]] = strength

    # Explicit genitives differ from possessive pronouns: the case marker,
    # not the possessor's head noun, anchors the following possessed phrase.
    for possessor in doc:
        if (
            possessor.dep_ not in ("poss", "nmod:poss")
            or possessor.pos_ not in ("NOUN", "PROPN")
        ):
            continue
        markers = [
            child for child in possessor.children
            if child.tag_ == "POS"
            and child.dep_ == "case"
            and possessor.i < child.i < possessor.head.i
            and child.i in starts
        ]
        if not markers:
            continue
        marker = min(markers, key=lambda child: child.i)
        nominal_onsets[marker.i] = nominal_onsets.get(
            possessor.i, possessor.i
        )
        nominal_onsets[possessor.head.i] = marker.i
        if possessor.i in starts:
            anchor_strength.pop(starts[possessor.i], None)
        anchor_strength[starts[marker.i]] = 1.9

    for i in range(n):
        if i == 0:
            attention[0, 0] = 1.0
            continue

        distances = i - np.arange(i + 1)
        attention[i, :i + 1] = 0.055 * np.exp(-distances / 4.0)
        attention[i, 0] += 0.15
        attention[i, i] += 0.10
        attention[i, i - 1] += 0.24

        scores = {}

        # Recently opened phrases retain their onset across nearby words.
        for j, strength in anchor_strength.items():
            distance = i - j
            if 1 <= distance <= 7:
                scores[j] = strength * np.exp(-0.20 * (distance - 1))

        word = doc[forward[i][-1]] if forward[i] else None
        if word is not None:
            onset = None
            if word.i in nominal_onsets:
                onset = nominal_onsets[word.i]
            elif word.dep_ in ("amod", "compound", "nummod", "case"):
                onset = nominal_onsets.get(word.head.i)
            elif word.pos_ in ("VERB", "AUX", "ADJ"):
                subjects = [
                    child for child in word.children
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj", "csubjpass")
                    and child.i < word.i
                ]
                if not subjects and word.pos_ == "AUX":
                    subjects = [
                        child for child in word.head.children
                        if child.dep_ in ("nsubj", "nsubjpass")
                        and child.i < word.i
                    ]
                if subjects:
                    subject = min(subjects, key=lambda child: child.i)
                    onset = nominal_onsets.get(subject.i, subject.i)

            if onset in starts:
                j = starts[onset]
                distance = i - j
                if 1 <= distance <= 7:
                    strength = anchor_strength.get(j, 1.15)
                    score = strength * np.exp(-0.13 * (distance - 1))
                    scores[j] = max(scores.get(j, 0.0), score)

            # Subword continuations generally retain their word's onset.
            j = starts.get(word.i)
            if j is not None and j < i:
                scores[j] = max(scores.get(j, 0.0), 0.85)

        if scores:
            best = max(scores, key=scores.get)
            punctuation_scale = 0.78 if word is not None and word.is_punct else 1.0
            attention[i, best] += punctuation_scale * scores[best]
            for j, score in scores.items():
                if j != best:
                    attention[i, j] += 0.12 * score

        # Early queries strongly prefer the initial token, unless a new
        # determiner or clause onset has already established a local phrase.
        initial_strength = 18.0 * np.exp(-0.95 * (i - 1))
        competing = any(j > 0 and score > 0.8 for j, score in scores.items())
        if competing:
            initial_strength *= 0.12
        attention[i, 0] += initial_strength

        # Standalone whitespace and opening punctuation can form local onsets.
        if tokens[i].strip("ĠĊĉ \t\r\n") == "":
            attention[i, i] += 0.65
        if i > 0 and forward[i - 1]:
            previous = doc[forward[i - 1][-1]]
            if previous.is_quote or previous.is_bracket:
                attention[i, i - 1] += 0.9

    return "possessive_phrase_onset", make_row_stochastic(apply_causal_mask(attention))


def prog_L2H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with local phrase anchors; verbal complements also
    attend to preceding auxiliaries and governing predicates across markers."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_and_left_phrase_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    representatives = []
    for i, sids in enumerate(alignment):
        usable = [s for s in sids if s < len(doc) and not doc[s].is_space]
        representatives.append(usable[-1] if usable else None)
        for s in usable:
            inverse[s].append(i)

    for i in range(n):
        if i == 0:
            attention[0, 0] = 1.0
            continue
        if i == 1:
            attention[i, 0] = 0.98
            attention[i, i] = 0.02
            continue

        row = attention[i]
        distances = np.arange(i + 1, dtype=np.float64)
        row[:i + 1] = 0.12 * np.exp(-(i - distances) / 4.0)
        row[0] += 1.05 + 4.5 * np.exp(-(i - 1) / 1.8)
        row[i - 1] += 0.16
        row[i] += 0.08

        sid = representatives[i]
        previous_sid = representatives[i - 1]
        if sid is None:
            row[i - 1] += 0.9
            continue

        word = doc[sid]
        previous = doc[previous_sid] if previous_sid is not None else None
        targets = {}

        # Pieces within one spaCy word prefer the beginning of that word.
        earlier_pieces = [j for j in inverse[sid] if j < i]
        if earlier_pieces:
            targets[earlier_pieces[0]] = 8.0

        # Prepositions select an available governor rather than their object.
        if word.pos_ == "ADP":
            head = word.head
            if head.i < sid and inverse[head.i]:
                target = inverse[head.i][-1]
                if target < i:
                    targets[target] = max(targets.get(target, 0.0), 5.5)

        # Infinitival markers look back through the upcoming verb to its
        # governing predicate, which can be separated by an object.
        if word.dep_ in ("aux", "mark") and word.tag_ == "TO":
            ancestor = word.head
            visited = set()
            while ancestor.i not in visited:
                visited.add(ancestor.i)
                if ancestor.i < sid and inverse[ancestor.i]:
                    target = inverse[ancestor.i][-1]
                    if target < i:
                        targets[target] = max(targets.get(target, 0.0), 8.0)
                        break
                if ancestor.head.i == ancestor.i:
                    break
                ancestor = ancestor.head

        if previous is not None and previous_sid != sid:
            strength = 0.0

            # Prenominal modifiers and quantifiers provide local anchors.
            if word.pos_ in ("NOUN", "PROPN"):
                if previous.dep_ in ("amod", "nummod", "compound"):
                    strength = 6.5
                elif previous.pos_ in ("DET", "PRON") and previous.head.i == sid:
                    strength = 2.2
            if word.pos_ == "DET" and previous.pos_ in ("DET", "NUM", "PRON"):
                strength = max(strength, 5.0)

            # Negation and adverbial modifiers are salient left contexts.
            if word.pos_ in ("VERB", "AUX", "ADJ", "ADV"):
                if previous.dep_ == "neg":
                    strength = max(strength, 8.0)
                elif previous.dep_ == "advmod" and previous.head.i == sid:
                    strength = max(strength, 6.0)
            if word.pos_ == "ADP" and previous.pos_ == "ADV":
                strength = max(strength, 7.0)

            # Coordination and subordinate-clause boundaries.
            if previous.pos_ == "CCONJ":
                strength = max(strength, 2.3)
            if previous.pos_ == "SCONJ" and word.pos_ in ("PRON", "DET"):
                strength = max(strength, 2.0)
            if word.pos_ == "SCONJ" and previous.pos_ == "ADV":
                strength = max(strength, 4.5)

            # Subjects immediately following an auxiliary in questions.
            if word.pos_ == "PRON" and previous.pos_ == "AUX":
                strength = max(strength, 2.8)

            # Verb particles and bare verbal complements.
            if word.dep_ == "prt" and previous.pos_ == "VERB":
                strength = max(strength, 7.5)
            if word.pos_ == "VERB" and previous.pos_ == "VERB":
                if word.dep_ in ("xcomp", "ccomp"):
                    strength = max(strength, 5.5)

            # Commas often serve as local clause-start anchors.
            if previous.is_punct and "," in previous.text:
                if word.pos_ in ("CCONJ", "SCONJ", "ADV", "ADJ", "PRON", "NOUN"):
                    strength = max(strength, 2.0)

            if strength:
                targets[i - 1] = max(targets.get(i - 1, 0.0), strength)

        # Opening quotation marks can look through a comma to the speech verb.
        if word.is_punct and any(c in word.text for c in ('"', "“", "‘")):
            for j in range(i - 1, max(-1, i - 7), -1):
                jsid = representatives[j]
                if jsid is not None and doc[jsid].pos_ == "VERB":
                    targets[j] = max(targets.get(j, 0.0), 2.4)
                    break

        # Missing verbal scaffolding: only the first piece of a new word.
        if previous is not None and previous_sid != sid and not earlier_pieces:
            if word.pos_ in ("VERB", "AUX", "ADJ"):
                if (
                    previous.pos_ == "AUX"
                    and previous.dep_ in ("aux", "auxpass", "cop")
                    and previous.head.i == sid
                ):
                    targets[i - 1] = max(targets.get(i - 1, 0.0), 3.0)

                # An infinitival complement retains its governing predicate,
                # rather than treating its intervening marker as the anchor.
                if (
                    word.dep_ == "xcomp"
                    and previous.tag_ == "TO"
                    and previous.head.i == sid
                    and word.head.i < sid
                    and word.head.pos_ in ("VERB", "AUX", "ADJ")
                ):
                    available = [j for j in inverse[word.head.i] if j < i]
                    if available:
                        target = available[-1]
                        targets[target] = max(targets.get(target, 0.0), 4.0)

            # A complementizer immediately following its matrix predicate.
            if (
                word.dep_ == "mark"
                and word.tag_ != "TO"
                and previous.pos_ in ("VERB", "AUX")
                and word.head.head.i == previous_sid
            ):
                targets[i - 1] = max(targets.get(i - 1, 0.0), 8.0)

        for target, strength in targets.items():
            if target <= i:
                row[target] += strength

    attention = make_row_stochastic(apply_causal_mask(attention))
    return "first_token_and_left_phrase_anchors", attention


def prog_L2H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict attention to recent phrase boundaries, with a strong initial-token sink.
    Punctuation and clause introducers outrank weaker prepositional and verbal anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "recent_phrase_boundary", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    strengths = np.zeros(n, dtype=np.float64)
    decays = np.full(n, 0.25, dtype=np.float64)
    punctuation = np.zeros(n, dtype=bool)
    terminal = np.zeros(n, dtype=bool)

    for j, token in enumerate(tokens):
        clean = token.replace("Ġ", " ").replace("Ċ", "\n").strip()
        words = [doc[k] for k in alignment[j] if k < len(doc)]
        content = [w for w in words if not w.is_space and not w.is_punct]

        punctuation[j] = (
            bool(clean) and all(c in ".,;:!?\"'“”‘’()[]{}—–-" for c in clean)
        ) or (bool(words) and all(w.is_punct or w.is_space for w in words))

        terminal[j] = any(c in ".!?" for c in clean)

        if any(c in ",;:" for c in clean):
            strengths[j], decays[j] = 0.70, 0.23
        elif terminal[j]:
            strengths[j], decays[j] = 0.69, 0.25
        elif content:
            # Only the first model piece of a linguistic token introduces a boundary.
            w = content[0]
            continuation = j > 0 and w.i in alignment[j - 1]
            if continuation:
                continue

            if w.pos_ == "CCONJ":
                strengths[j], decays[j] = 0.69, 0.24
            elif w.pos_ == "SCONJ" or w.dep_ in ("mark", "relcl"):
                strengths[j], decays[j] = 0.60, 0.25
            elif w.pos_ == "ADP":
                strengths[j], decays[j] = 0.55, 0.22
            elif w.pos_ == "AUX" or w.dep_ == "cop":
                strengths[j], decays[j] = 0.44, 0.20
            elif w.pos_ == "PRON" and w.tag_ in ("WDT", "WP", "WP$"):
                strengths[j], decays[j] = 0.59, 0.24
            elif w.pos_ == "ADV" and w.tag_ == "WRB":
                strengths[j], decays[j] = 0.59, 0.24
            elif w.pos_ == "VERB":
                strengths[j], decays[j] = 0.33, 0.30

    attention[0, 0] = 1.0

    for i in range(1, n):
        # Unstructured residual attention remains local, but is not purely previous-token.
        distances = i - np.arange(i + 1)
        residual = np.exp(-0.60 * distances)
        residual[i] = 0.40
        residual[i - 1] += 0.45
        residual[0] += 0.10 * np.exp(-i / 10.0)

        if i == 1:
            anchor, mass = 0, 0.97
        else:
            anchor = 0
            mass = 0.63 * np.exp(-0.32 * (i - 2))

            for j in range(1, i):
                if strengths[j] <= 0:
                    continue
                candidate = strengths[j] * np.exp(
                    -decays[j] * (i - j - 1)
                )

                # A coordinator immediately after punctuation often leaves the
                # punctuation as the effective start of the new phrase.
                if strengths[j] >= 0.60 and not punctuation[j]:
                    if punctuation[j - 1] and strengths[j - 1] > 0:
                        candidate *= 0.72

                if candidate > mass:
                    anchor, mass = j, float(candidate)

        residual[anchor] = 0.0
        total = residual.sum()
        if total > 0:
            attention[i, :i + 1] = (1.0 - mass) * residual / total
        attention[i, anchor] = mass

        # Punctuation frequently closes a phrase by attending substantially to itself.
        if punctuation[i]:
            self_mass = 0.46 if terminal[i] else 0.40
            nonself = attention[i, :i].sum()
            if nonself > 0:
                attention[i, :i] *= (1.0 - self_mass) / nonself
                attention[i, i] = self_mass

    return "recent_phrase_boundary", make_row_stochastic(attention)


def prog_L2H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with sentence-ending punctuation acting as
    renewed local sinks and weaker attention to subsequent sentence starts.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_and_sentence_boundary_sinks", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    cleaned = [
        t.replace("\u0120", " ").replace("\u010a", "\n").strip()
        for t in tokens
    ]
    punctuation_chars = ".,!?;:…\"'“”‘’«»()[]{}—–-"
    terminal_chars = ".!?…"

    boundaries = []
    sentence_starts = []
    is_punctuation = np.zeros(n, dtype=bool)

    for j, text in enumerate(cleaned):
        mapped = alignment[j]
        is_punctuation[j] = (
            bool(text) and all(c in punctuation_chars for c in text)
        ) or (
            bool(mapped) and all(doc[k].pos_ == "PUNCT" for k in mapped)
        )

        if (
            text
            and is_punctuation[j]
            and any(c in terminal_chars for c in text)
        ):
            # Consecutive punctuation pieces form one boundary sink.
            if boundaries and boundaries[-1] == j - 1:
                boundaries[-1] = j
            else:
                boundaries.append(j)

        if mapped:
            k = mapped[0]
            if (
                doc[k].is_sent_start
                and doc[k].pos_ not in ("PUNCT", "SPACE")
                and (j == 0 or k not in alignment[j - 1])
            ):
                sentence_starts.append(j)

    # Include the first lexical token after a boundary even when spaCy treats
    # quoted dialogue and its continuation as a single sentence.
    for b in boundaries:
        for j in range(b + 1, n):
            if cleaned[j] and not is_punctuation[j]:
                if j not in sentence_starts:
                    sentence_starts.append(j)
                break

    for i in range(n):
        positions = np.arange(i + 1)
        distances = i - positions

        # Growing diffuse competition explains the early decline of the
        # otherwise dominant initial-token sink.
        diffuse = 3.0 * (1.0 - np.exp(-i / 3.0))
        attention[i, :i + 1] = diffuse * (
            0.85 + 0.15 * np.exp(-distances / 6.0)
        )
        attention[i, 0] += 40.0 / (1.0 + 0.01 * i)

        if is_punctuation[i]:
            attention[i, i] += 7.0

        past_boundaries = [b for b in boundaries if b <= i]
        for rank, b in enumerate(reversed(past_boundaries)):
            distance = i - b
            strength = 43.0 if distance == 0 else 64.0
            attention[i, b] += (
                strength * (0.24 ** rank) / (1.0 + 0.04 * distance)
            )

        for start in sentence_starts:
            if 0 < start <= i:
                distance = i - start
                newer_boundary = any(start < b <= i for b in past_boundaries)
                strength = 14.0 if distance == 0 else 29.0
                attention[i, start] += (
                    strength
                    * np.exp(-distance / 9.0)
                    * (0.2 if newer_boundary else 1.0)
                )

    return (
        "first_token_and_sentence_boundary_sinks",
        make_row_stochastic(attention),
    )


def prog_L2H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with local salience; dialogue adds a broader causal tail
    anchored on reporting predicates, subjects, and quotation boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_dialogue_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    strength = np.ones(n, dtype=np.float64)
    self_strength = np.ones(n, dtype=np.float64)
    word_ids = [None] * n
    quote = np.zeros(n, dtype=bool)

    for i, indices in enumerate(alignment):
        if not indices:
            self_strength[i] = 0.65
            strength[i] = 0.7
            continue

        # Prefer lexical material over whitespace included in token offsets.
        candidates = [k for k in indices if not doc[k].is_space]
        if not candidates:
            self_strength[i] = 0.6
            strength[i] = 0.65
            continue

        k = candidates[-1]
        word = doc[k]
        word_ids[i] = k
        pos = word.pos_

        if pos in ("VERB", "AUX"):
            self_strength[i] = 1.15
            strength[i] = 1.15
        elif pos in ("NOUN", "PROPN"):
            self_strength[i] = 1.2
            strength[i] = 1.1
        elif pos == "PRON":
            self_strength[i] = 1.2
            strength[i] = 1.05
        elif pos == "ADJ":
            self_strength[i] = 0.8
            strength[i] = 0.9
        elif pos == "ADV":
            self_strength[i] = 0.65
            strength[i] = 0.8
        elif pos in ("DET", "ADP", "PART", "CCONJ", "SCONJ"):
            self_strength[i] = 0.85
            strength[i] = 0.8

        if word.dep_ == "ROOT":
            self_strength[i] *= 1.08

        if word.is_punct:
            self_strength[i] = 1.0
            strength[i] = 0.85
            quote[i] = any(c in "\"'“”‘’«»" for c in word.text)
            if quote[i]:
                self_strength[i] = 1.65
                strength[i] = 1.2

        # Subword continuations retain a connection to the word's first piece.
        if i > 0 and word_ids[i - 1] == k:
            self_strength[i] *= 0.85

    # Added path: double-quoted dialogue, including damaged quote encodings.
    # Apostrophes alone do not trigger it.
    dialogue_marks = np.zeros(n, dtype=bool)
    anchors = np.zeros(n, dtype=np.float64)
    for j, indices in enumerate(alignment):
        dialogue_marks[j] = any(
            any(c in "\"“”«»€" for c in doc[k].text)
            for k in indices
        )
        k = word_ids[j]
        if k is None or (j > 0 and word_ids[j - 1] == k):
            continue
        word = doc[k]
        if word.pos_ == "VERB":
            anchors[j] = 0.65
        elif word.dep_ in ("nsubj", "nsubjpass", "csubj"):
            anchors[j] = 0.55
        elif word.tag_.startswith("W"):
            anchors[j] = 0.75
        elif word.is_sent_start:
            anchors[j] = 0.35
        if dialogue_marks[j] and (j == 0 or not dialogue_marks[j - 1]):
            anchors[j] = max(anchors[j], 0.45)
        elif j > 0 and dialogue_marks[j - 1] and not word.is_punct:
            anchors[j] = max(anchors[j], 0.65)

    attention[0, 0] = 1.0
    dialogue_active = bool(dialogue_marks[0])
    for i in range(1, n):
        distances = i - np.arange(i + 1)
        scale = 1.9 + 0.032 * i
        local = 0.92 * np.exp(-distances / scale)
        background = 0.025 / np.sqrt(1.0 + distances / 8.0)
        row = (local + background) * strength[:i + 1]
        row[i] = self_strength[i]

        # A strong initial sink fades quickly, then persists at long range.
        row[0] += 3.5 * np.exp(-i / 2.3) + 0.25 + 0.022 * i

        if word_ids[i] is not None:
            k = word_ids[i]
            if word_ids[i - 1] == k:
                row[i - 1] *= 1.25
            if doc[k].is_punct and not quote[i]:
                row[i - 1] *= 1.15

        # Opening quotation marks remain a modest local anchor.
        for j in range(max(1, i - 6), i):
            if quote[j]:
                row[j] *= 1.2

        # Leave the original raw self/sink/local weights intact; add only
        # historical mass once a dialogue boundary has actually been seen.
        dialogue_active = dialogue_active or bool(dialogue_marks[i])
        if dialogue_active and i > 1:
            d = distances[1:i]
            row[1:i] += (
                0.20 / np.sqrt(1.0 + d / 20.0)
                + anchors[1:i] * np.exp(-d / 16.0)
            )

        attention[i, :i + 1] = row / row.sum()

    return "first_token_sink_with_dialogue_anchors", attention


def prog_L2H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Predict backward phrase governors, sharing infinitival-verb attention
    between the infinitival marker and its leftward governing verb.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "leftward_phrase_governor", attention

    doc = spacy_parse(sentence)
    forward = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    nominal = {"NOUN", "PROPN", "PRON"}
    predicates = {"VERB", "AUX", "ADP"}
    subject_deps = {"nsubj", "nsubjpass", "csubj", "csubjpass", "expl"}
    modifier_deps = {"det", "predet", "poss", "amod", "compound", "nummod"}
    object_deps = {"dobj", "obj", "iobj", "dative", "attr", "oprd", "pobj"}

    for i in range(n):
        attention[i, 0] = 0.22
        attention[i, i] += 0.07
        if i:
            attention[i, i - 1] += 0.12
            distances = np.arange(i + 1)
            attention[i, :i + 1] += 0.035 * np.exp((distances - i) / 4.0)
        else:
            attention[0, 0] = 1.0
            continue

        if i == 1:
            attention[i, 0] += 5.0
            continue

        if not forward[i]:
            # Extra whitespace usually belongs to the preceding boundary.
            attention[i, i - 1] += 0.65
            continue

        word = doc[forward[i][-1]]
        target = None
        strength = 0.0

        # Within a split word, favor its immediately preceding model piece.
        earlier_pieces = [p for p in inverse[word.i] if p < i]
        if earlier_pieces:
            target = earlier_pieces[-1]
            strength = 1.05

        # Find the nominal phrase containing a determiner or adjective.
        phrase = word
        seen = set()
        while (
            phrase.dep_ in modifier_deps
            and phrase.head.i != phrase.i
            and phrase.i not in seen
        ):
            seen.add(phrase.i)
            phrase = phrase.head

        # Subjects lack a leftward lexical governor in ordinary word order.
        # In inversion, however, a preceding auxiliary is a strong anchor.
        if target is None and phrase.dep_ in subject_deps:
            governor = phrase.head
            auxiliaries = [
                c for c in governor.children
                if c.dep_ in {"aux", "auxpass", "cop"}
                and c.i < word.i
                and inverse[c.i]
                and inverse[c.i][-1] < i
            ]
            if auxiliaries:
                auxiliary = max(auxiliaries, key=lambda c: c.i)
                target = inverse[auxiliary.i][-1]
                strength = 1.35
            else:
                preceding = [
                    c for c in phrase.subtree
                    if c.i < word.i
                    and inverse[c.i]
                    and inverse[c.i][-1] < i
                ]
                if preceding:
                    anchor = min(preceding, key=lambda c: c.i)
                    target = inverse[anchor.i][-1]
                    strength = 0.40

        # Climb through nominal structure to a causal phrase governor.
        if target is None and phrase.dep_ not in subject_deps:
            current = word
            seen = set()
            while current.i not in seen:
                seen.add(current.i)
                head = current.head
                if head.i == current.i:
                    break
                pieces = [p for p in inverse[head.i] if p < i]
                if pieces and head.pos_ in predicates:
                    target = pieces[-1]
                    strength = 1.15
                    if word.pos_ == "ADP" or word.dep_ in {"prt", "mark"}:
                        strength = 1.65
                    elif phrase.dep_ in object_deps:
                        strength = 1.35
                    elif word.pos_ in {"ADJ", "ADV"}:
                        strength = 0.85
                    elif word.pos_ in {"VERB", "AUX"}:
                        strength = 0.65
                    break
                current = head

        # A left auxiliary may govern a lexical verb in this head's pattern,
        # even though spaCy represents the auxiliary as its dependent.
        if word.pos_ == "VERB" and not earlier_pieces:
            auxiliaries = [
                c for c in word.children
                if c.dep_ in {"aux", "auxpass"}
                and inverse[c.i]
                and inverse[c.i][-1] < i
            ]
            if auxiliaries:
                auxiliary = max(auxiliaries, key=lambda c: c.i)
                target = inverse[auxiliary.i][-1]
                strength = 1.05

                # An infinitival marker does not replace the lexical governor:
                # split the existing weight, leaving all baseline weights intact.
                if (
                    auxiliary.pos_ == "PART"
                    and auxiliary.dep_ == "aux"
                    and word.dep_ == "xcomp"
                    and word.head.pos_ == "VERB"
                    and word.head.i < word.i
                    and inverse[word.head.i]
                    and inverse[word.head.i][-1] < i
                ):
                    attention[i, inverse[word.head.i][-1]] += 0.60
                    strength -= 0.60

        if word.is_punct:
            if any(c in word.text for c in ".!?"):
                attention[i, 0] += 0.55
                attention[i, i] += 0.45
                strength *= 0.40
            elif target is not None:
                strength = 1.25
            else:
                attention[i, i - 1] += 0.65

        if target is not None:
            attention[i, target] += strength
        elif not word.is_punct:
            # Sentence starts and unresolvable forward dependencies fall back
            # to a local boundary or the global first-token attention sink.
            boundaries = [
                j for j in range(max(0, i - 8), i)
                if any(c in tokens[j] for c in ".!?")
            ]
            if boundaries:
                attention[i, boundaries[-1]] += 0.45
            else:
                attention[i, 0] += 0.30

    return "leftward_phrase_governor", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L2H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attend to the latest local content anchor, skipping grammatical glue.
    Subject–predicate links and phrase boundaries refine a strong recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_content_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            if wi < len(doc):
                inverse[wi].append(ti)

    content_pos = {"NOUN", "PROPN", "PRON", "VERB", "ADJ", "NUM", "INTJ"}
    subject_deps = {"nsubj", "nsubjpass", "csubj", "csubjpass"}
    boundary_marks = {".", "!", "?"}

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        current_ids = alignment[i]
        current = doc[current_ids[0]] if current_ids else None

        # A small diffuse causal component prevents artificially sharp rows.
        distances = i - np.arange(i + 1)
        prior = np.exp(-distances / 3.0)
        prior /= prior.sum()
        attention[i, :i + 1] = 0.12 * prior
        attention[i, 0] += 0.17
        attention[i, i] += 0.04
        attention[i, i - 1] += 0.07

        anchor = 0
        strength = 0.60

        # Locate the latest lexical anchor. Sentence-ending punctuation is
        # itself an anchor, unlike commas and quotation marks.
        for j in range(i - 1, -1, -1):
            clean = tokens[j].lstrip("Ġ").strip()
            if clean and any(mark in clean for mark in boundary_marks):
                if all(ch in ".!?\"'”’" for ch in clean):
                    anchor = j
                    break

            word_ids = alignment[j]
            if any(doc[wi].pos_ in content_pos for wi in word_ids):
                anchor = j
                break

        if current is not None:
            # Continuing BPE pieces commonly point back into their own word.
            earlier_pieces = [
                j for j in inverse[current.i] if j < i
            ]
            if earlier_pieces:
                anchor = earlier_pieces[0]
                strength = 0.58
            else:
                pos = current.pos_

                # A finite predicate often preserves its preceding subject,
                # including across an auxiliary or degree modifier.
                if pos in {"VERB", "AUX", "ADJ"}:
                    subjects = [
                        child for child in current.children
                        if child.dep_ in subject_deps and child.i < current.i
                    ]
                    if not subjects and current.dep_ in {
                        "acomp", "attr", "xcomp"
                    }:
                        subjects = [
                            child for child in current.head.children
                            if child.dep_ in subject_deps
                            and child.i < current.i
                        ]

                    candidates = []
                    for subject in subjects:
                        candidates.extend(
                            j for j in inverse[subject.i] if j < i
                        )
                    if candidates:
                        subject_token = max(candidates)
                        gap = i - subject_token
                        if gap <= 6:
                            anchor = subject_token
                            strength = 0.66 if gap <= 2 else 0.51

                # Nominals frequently look to the immediately preceding
                # adjective or possessive rather than to a distant governor.
                if pos in {"NOUN", "PROPN"}:
                    for j in range(i - 1, max(-1, i - 4), -1):
                        ids = alignment[j]
                        if not ids:
                            continue
                        previous = doc[ids[-1]]
                        if previous.pos_ in {"ADJ", "NUM"} or previous.dep_ == "poss":
                            anchor = j
                            strength = 0.60
                            break
                        if previous.pos_ not in {"DET", "SPACE"}:
                            break

                if pos in {"ADP", "CCONJ", "SCONJ", "PUNCT", "PART"}:
                    strength = 0.67
                elif pos in {"DET", "ADV"}:
                    strength = 0.53

        elif not tokens[i].lstrip("Ġ").strip():
            anchor = i - 1
            strength = 0.64

        attention[i, anchor] += strength

        # The first position is an especially strong early fallback.
        if i == 1:
            attention[i, :] = 0.0
            attention[i, 0] = 0.98
            attention[i, i] = 0.02

    return "local_content_anchor", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L2H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A decaying first-token sink with local content attention.
    Dialogue boundaries retain a weak sink and favor sentence starts over blank keys.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_dialogue_boundaries", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    strengths = np.ones(n, dtype=np.float64)
    starts = list(range(n))
    first_piece = {}

    pos_strength = {
        "NOUN": 1.20,
        "PROPN": 1.30,
        "VERB": 1.25,
        "ADJ": 1.05,
        "ADV": 0.75,
        "PRON": 0.95,
        "AUX": 0.95,
        "DET": 0.38,
        "ADP": 0.65,
        "CCONJ": 0.65,
        "SCONJ": 0.80,
        "PART": 0.65,
        "NUM": 0.85,
        "PUNCT": 0.65,
        "SPACE": 0.15,
    }

    for j, indices in enumerate(alignment):
        if not indices:
            continue
        sid = indices[0]
        word = doc[sid]
        strengths[j] = pos_strength.get(word.pos_, 0.90)

        if sid not in first_piece:
            first_piece[sid] = j
        starts[j] = first_piece[sid]

        if starts[j] != j:
            strengths[j] *= 0.35

    attention[0, 0] = 1.0

    for i in range(1, n):
        # Local keys remain useful after the initial positional sink fades.
        for j in range(1, i + 1):
            distance = i - j
            attention[i, j] = strengths[j] * np.exp(-distance / 5.5)

        # Within a split word, prefer the first piece over its suffixes.
        start = starts[i]
        if 0 < start < i:
            attention[i, start] += 0.70 * np.exp(-(i - start) / 5.5)

        # The first position behaves as a sink, not a semantic antecedent.
        attention[i, 0] = 6.0 * np.exp(-0.21 * (i - 1))

    # Special case: dialogue boundaries and standalone whitespace can make
    # alignment treat a blank token as a strong lexical key.
    blank_keys = [
        j for j, token in enumerate(tokens)
        if token and not token.replace("Ġ", " ").replace("Ċ", "\n").strip()
    ]
    dialogue = (
        bool(blank_keys)
        or any(c in sentence for c in '"“”«»')
        or any(word.is_punct and not word.text.isascii() for word in doc)
    )
    if dialogue:
        for j in blank_keys:
            if j > 0:
                attention[j + 1:, j] *= 0.30

        # A sentence-initial determiner is a local boundary anchor rather
        # than an ordinary low-strength determiner. Only incoming edges change.
        for j, indices in enumerate(alignment):
            if j == 0 or not indices:
                continue
            word = doc[indices[0]]
            if (
                word.is_sent_start
                and word.pos_ == "DET"
                and starts[j] == j
                and j not in blank_keys
            ):
                attention[j + 1:, j] *= 2.0

        # Keep a small positional sink across dialogue turns.
        # Raw diagonal weights and all original decay rates remain unchanged.
        for i in range(1, n):
            attention[i, 0] = max(attention[i, 0], 0.30)

    return (
        "first_token_sink_with_dialogue_boundaries",
        make_row_stochastic(attention),
    )


def prog_L2H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with positional decay toward a persistent floor.
    Residual attention is diffuse over the causal prefix, with mild recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink_with_decay", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.52 + 0.48 * np.exp(-i / 6.3)

        positions = np.arange(1, i + 1, dtype=np.float64)
        recency = np.exp(-(i - positions) / 12.0)
        recency /= recency.sum()
        residual = 0.8 / i + 0.2 * recency

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_decay", attention


def prog_L3H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with weak recency and content-word repetition
    occasionally diverting attention to earlier semantically matching tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_repetition", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    content_pos = {"NOUN", "PROPN"}
    function_pos = {"ADP", "AUX", "CCONJ", "SCONJ", "DET", "PART"}
    representatives = []

    for indices in alignment:
        representative = None
        for k in indices:
            if not doc[k].is_space:
                if representative is None or doc[k].pos_ in content_pos:
                    representative = doc[k]
        representatives.append(representative)

    attention[0, 0] = 1.0

    for i in range(1, n):
        query = representatives[i]
        pos = query.pos_ if query is not None else ""

        if pos in function_pos:
            background_scale = 0.65
        elif pos in content_pos:
            background_scale = 1.65
        else:
            background_scale = 1.0

        # A strong fixed sink naturally becomes less dominant in long contexts.
        attention[i, 0] = 100.0
        for j in range(1, i + 1):
            distance = i - j
            attention[i, j] = background_scale * (
                0.22 + 0.35 * np.exp(-distance / 5.0)
            )

        # Repeated content words can overcome the sink. Only compare distinct
        # spaCy words, avoiding false matches within a split model tokenization.
        if query is not None and pos in content_pos:
            for j in range(1, i):
                key = representatives[j]
                if key is None or key.pos_ not in content_pos:
                    continue
                if key.i == query.i:
                    continue

                # Use the first model piece as the destination for each word.
                if j > 0 and representatives[j - 1] is not None:
                    if representatives[j - 1].i == key.i:
                        continue

                similarity = embedding_similarity(tokens, i, j, tokenizer)
                strength = max(0.0, min(1.0, (similarity - 0.60) / 0.40))
                attention[i, j] += 330.0 * strength ** 6

    return (
        "first_token_sink_with_repetition",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L3H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with clause anchors and persistent punctuation boundaries.
    After a boundary, redistribute only non-sink, non-self mass toward it.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_boundary_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_to_model = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            word_to_model[wi].append(ti)

    opening_quotes = {}
    active_quote = None
    quote_marks = ('"', '“', '”', '«', '»')
    boundary_at = [None] * n
    last_boundary = None
    for i, token in enumerate(tokens):
        opening_quotes[i] = active_quote
        clean = token.lstrip("Ġ").lstrip("Ċ").strip()
        closes_quote = False
        if any(mark in clean for mark in quote_marks):
            if active_quote is None:
                active_quote = i
            else:
                opening_quotes[i] = active_quote
                active_quote = None
                closes_quote = True

        # Commas, closed quotations, and standalone spacing can act as
        # persistent anchors rather than merely recent context.
        boundary_at[i] = last_boundary
        if (
            any(mark in clean for mark in (",", ";", ":"))
            or closes_quote
            or not clean
        ):
            last_boundary = i

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(i + 1)
        distance = i - positions
        scores = 0.10 * np.exp(-distance / 12.0)
        scores += 0.60 * np.exp(-distance / 2.8)
        scores[0] = 0.0
        anchor_strength = 0.0

        word_ids = alignment[i]
        word = doc[word_ids[-1]] if word_ids else None

        if word is not None:
            # Find the local predicate without crossing an embedded clause.
            predicate = word
            for _ in range(5):
                if predicate.pos_ in ("VERB", "AUX"):
                    break
                if predicate.head.i == predicate.i:
                    break
                predicate = predicate.head

            if predicate.pos_ in ("VERB", "AUX"):
                for child in predicate.children:
                    candidates = word_to_model[child.i]
                    if not candidates:
                        continue
                    j = candidates[0]
                    if j <= 0 or j >= i:
                        continue

                    if (
                        child.dep_ in ("nsubj", "nsubjpass", "csubj")
                        and child.pos_ == "PRON"
                        and i - j <= 10
                    ):
                        strength = 2.5 * np.exp(-(i - j - 1) / 15.0)
                        scores[j] += strength
                        anchor_strength = max(anchor_strength, strength)

                    # Clause-initial discourse modifiers often replace the sink.
                    if (
                        child.dep_ in ("advmod", "cc", "mark", "discourse")
                        and child.pos_ in ("ADV", "CCONJ", "SCONJ")
                        and j < i
                        and i - j <= 12
                    ):
                        preceding_boundary = (
                            child.i == 0
                            or doc[child.i - 1].is_punct
                            or doc[child.i - 1].is_space
                        )
                        if preceding_boundary:
                            strength = 4.5 * np.exp(-(i - j - 1) / 12.0)
                            scores[j] += strength
                            anchor_strength = max(anchor_strength, strength)

            # Noun phrases retain a weaker link to their initial determiner.
            if word.pos_ in ("NOUN", "PROPN"):
                for child in word.children:
                    if child.dep_ == "det" and word_to_model[child.i]:
                        j = word_to_model[child.i][0]
                        if 0 < j < i:
                            scores[j] += 1.5 * np.exp(-(i - j - 1) / 5.0)
                            anchor_strength = max(anchor_strength, 1.2)

            if word_to_model[word.head.i]:
                j = word_to_model[word.head.i][0]
                if 0 < j < i:
                    scores[j] += 0.25

        quote = opening_quotes[i]
        if quote is not None and quote > 0:
            strength = 1.3 * np.exp(-(i - quote - 1) / 15.0)
            if i - quote == 1:
                strength += 2.5
            if word is not None and word.is_punct:
                strength += 1.5
            scores[quote] += strength
            anchor_strength = max(anchor_strength, strength)

        # Explicit sink mass avoids diluting it simply as the sequence grows.
        sink = 0.30 + 0.70 * np.exp(-((i / 7.0) ** 1.5))
        sink *= 1.0 - 0.42 * (
            anchor_strength / (anchor_strength + 2.0)
        )

        clean = tokens[i].lstrip("Ġ").lstrip("Ċ")
        if not clean.strip():
            scores[i - 1] += 1.8

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * scores[1:] / scores[1:].sum()
        )

        # Preserve the original sink and self weights exactly. Only rows
        # following a recent boundary redistribute other historical mass.
        boundary = boundary_at[i]
        if boundary is not None and 0 < boundary < i and i - boundary <= 16:
            target = 0.22 * np.exp(-(i - boundary - 1) / 24.0)
            donors = np.arange(1, i)
            donors = donors[donors != boundary]
            available = attention[i, donors].sum()
            transfer = min(
                max(0.0, target - attention[i, boundary]),
                0.60 * available,
            )
            if available > 0.0 and transfer > 0.0:
                attention[i, donors] *= 1.0 - transfer / available
                attention[i, boundary] += transfer

    return "first_token_sink_with_boundary_anchors", make_row_stochastic(attention)


def prog_L3H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local predecessor attention with phrase anchors; nested possessives retain
    their determiner and possessive marker rather than the possessor noun.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_predecessor_possessive_anchor", matrix

    doc = spacy_parse(sentence)
    forward = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    # Find left-edge anchors for nominal and adjectival phrases.
    anchors = {}
    for word in doc:
        root = word
        if word.dep_ in ("amod", "compound", "poss", "det", "nummod"):
            root = word.head
        elif word.dep_ == "case" and word.head.pos_ in ("NOUN", "PROPN"):
            root = word.head

        if root.pos_ in ("NOUN", "PROPN", "PRON"):
            candidates = [
                child for child in root.children
                if child.dep_ in ("det", "poss", "nummod")
                and child.i < root.i
            ]
            if candidates:
                anchor = min(candidates, key=lambda child: child.i)
                anchors[word.i] = anchor.i

        if word.pos_ in ("ADJ", "ADV"):
            degree_root = word
            if word.dep_ == "conj" and word.head.pos_ == word.pos_:
                degree_root = word.head
            modifiers = [
                child for child in degree_root.children
                if child.dep_ == "advmod" and child.i < word.i
            ]
            if modifiers:
                anchors[word.i] = max(modifiers, key=lambda child: child.i).i

    # Special case: an explicitly marked, determiner-led nominal possessor.
    # Keep both phrase boundaries instead of treating the possessor as its
    # own anchor. Ordinary possessive pronouns and other phrases are unchanged.
    possessive_overrides = {}
    for possessor in doc:
        if possessor.dep_ != "poss" or possessor.pos_ not in ("NOUN", "PROPN"):
            continue
        determiners = [
            child for child in possessor.children
            if child.dep_ == "det" and child.i < possessor.i
        ]
        markers = [
            child for child in possessor.children
            if child.dep_ == "case"
            and possessor.i < child.i < possessor.head.i
        ]
        if not determiners or not markers:
            continue

        determiner = min(determiners, key=lambda child: child.i)
        marker = max(markers, key=lambda child: child.i)
        possessed = possessor.head
        possessive_overrides[possessor.i] = [(determiner.i, 8.0)]

        prep = possessed.head
        in_preposition = (
            possessed.dep_ == "pobj"
            and prep.pos_ == "ADP"
            and prep.i < determiner.i
        )
        possessive_overrides[marker.i] = (
            [(prep.i, 7.0), (determiner.i, 4.0)]
            if in_preposition else [(determiner.i, 8.0)]
        )
        possessive_overrides[possessed.i] = (
            [(determiner.i, 5.0), (marker.i, 3.0)]
            if in_preposition else [(marker.i, 8.0), (determiner.i, 3.0)]
        )

        if possessed.dep_ in ("nsubj", "nsubjpass"):
            predicate = possessed.head
            for candidate in [predicate] + list(predicate.children):
                if (
                    candidate.pos_ in ("VERB", "AUX")
                    and candidate.i > possessed.i
                    and (
                        candidate.i == predicate.i
                        or candidate.dep_ in ("aux", "auxpass", "cop")
                    )
                ):
                    possessive_overrides[candidate.i] = [
                        (determiner.i, 5.0), (marker.i, 5.0)
                    ]

    for i in range(n):
        if i == 0:
            matrix[i, i] = 1.0
            continue

        distances = i - np.arange(i + 1)
        matrix[i, :i + 1] = 0.12 * np.exp(-distances / 3.0)
        matrix[i, 0] += 0.55
        matrix[i, i] += 0.55
        matrix[i, i - 1] += 3.6

        if i == 1:
            matrix[i, 0] += 5.0

        sids = forward[i]
        previous_sids = forward[i - 1]
        word = doc[sids[-1]] if sids else None
        previous = doc[previous_sids[-1]] if previous_sids else None

        anchor_sid = None
        strength = 0.0

        if word is not None:
            if word.i in anchors:
                anchor_sid = anchors[word.i]
                strength = 8.0

            # A finite predicate can preserve the subject phrase's left edge.
            if word.pos_ in ("VERB", "AUX"):
                subjects = [
                    child for child in word.children
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj")
                    and child.i < word.i
                ]
                if subjects:
                    subject = max(subjects, key=lambda child: child.i)
                    if previous is not None and subject.i == previous.i:
                        if subject.i in anchors:
                            anchor_sid = anchors[subject.i]
                            strength = 3.6
                        else:
                            matrix[i, i - 1] += 1.5

            # Phrase boundaries often retain a noun phrase's initial marker.
            if previous is not None and previous.i in anchors:
                if word.pos_ in ("PUNCT", "ADP") or word.dep_ == "case":
                    anchor_sid = anchors[previous.i]
                    strength = 5.0

            # Without a phrase marker, split words favor their preceding piece.
            if previous is not None and previous.i == word.i:
                if anchor_sid is None:
                    matrix[i, i - 1] += 1.6

            if word.pos_ == "CCONJ" and previous is not None:
                if previous.head.i < previous.i:
                    head_pieces = inverse[previous.head.i]
                    eligible = [j for j in head_pieces if j < i]
                    if eligible:
                        matrix[i, eligible[-1]] += 1.2

        # Override only the explicitly detected nested-possessive rows.
        if word is not None and word.i in possessive_overrides:
            targets = []
            for sid, weight in possessive_overrides[word.i]:
                eligible = [j for j in inverse[sid] if j < i]
                if eligible:
                    targets.append((sid, eligible[0], weight))
            if targets:
                anchor_sid, _, strength = targets[0]
                for _, target, weight in targets[1:]:
                    matrix[i, target] += weight

        if anchor_sid is not None:
            pieces = inverse[anchor_sid]
            eligible = [j for j in pieces if j < i]
            if eligible:
                target = eligible[0]
                if strength >= 5.0:
                    matrix[i, i - 1] *= 0.4
                matrix[i, target] += strength

        # Standalone whitespace and quotation boundaries are strongly local.
        if tokens[i].isspace() or tokens[i].strip("\u0120") == "":
            matrix[i, i - 1] += 3.0

    return (
        "local_predecessor_possessive_anchor",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L3H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, interrupted by local phrase-head and subword links.
    Function words preferentially retrieve a nearby preceding syntactic anchor.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_local_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, word_ids in enumerate(alignment):
        for word_id in word_ids:
            inverse[word_id].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word_ids = alignment[i]
        word = doc[word_ids[0]] if word_ids else None
        previous_ids = alignment[i - 1]
        previous = doc[previous_ids[-1]] if previous_ids else None

        sink = 0.74
        if word is not None:
            if word.pos_ in ("VERB", "AUX"):
                sink = 0.85
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink = 0.77
            elif word.pos_ in ("DET", "PRON", "ADP", "PART", "SCONJ"):
                sink = 0.57
            elif word.pos_ == "PUNCT":
                sink = 0.72

        # Background mass is mostly recent, without excluding earlier tokens.
        distances = i - np.arange(i + 1)
        background = np.exp(-distances / 2.0)
        background /= background.sum()
        row = (1.0 - sink) * background
        row[0] += sink

        anchor = None
        strength = 0.0

        if word is not None:
            pieces = inverse[word.i]
            earlier_pieces = [j for j in pieces if j < i]

            # Continuations recover the beginning of their lexical item.
            if earlier_pieces:
                anchor = earlier_pieces[0]
                strength = 0.84
            else:
                head = word.head
                head_pieces = [j for j in inverse[head.i] if j < i]
                if head.i != word.i and head_pieces:
                    head_start = head_pieces[0]
                    gap = i - head_pieces[-1]

                    if gap <= 3:
                        if (
                            word.pos_ == "PRON"
                            and word.dep_ in ("dobj", "obj", "iobj", "dative")
                            and head.pos_ == "VERB"
                        ):
                            anchor, strength = head_start, 0.82
                        elif (
                            word.pos_ == "ADP"
                            and head.pos_ in ("NOUN", "PROPN", "ADJ", "ADV", "VERB")
                            and gap == 1
                        ):
                            anchor, strength = head_start, 0.68
                        elif (
                            word.pos_ == "PART"
                            and head.pos_ in ("VERB", "ADJ")
                            and gap == 1
                        ):
                            anchor, strength = head_start, 0.55

                if previous is not None and previous.i != word.i:
                    previous_pieces = inverse[previous.i]
                    previous_start = previous_pieces[0]

                    if (
                        word.pos_ == "PRON"
                        and word.dep_ in ("nsubj", "nsubjpass")
                        and previous.pos_ == "AUX"
                    ):
                        anchor, strength = previous_start, 0.82
                    elif (
                        word.pos_ == "DET"
                        and previous.pos_ in ("VERB", "ADP")
                    ):
                        anchor, strength = previous_start, 0.62

                        # A determiner after a preposition may retain the
                        # preposition's preceding nominal phrase anchor.
                        if previous.pos_ == "ADP":
                            nominal = previous.head
                            nominal_pieces = [
                                j for j in inverse[nominal.i] if j < i
                            ]
                            if (
                                nominal.pos_ in ("NOUN", "PROPN")
                                and nominal_pieces
                                and i - nominal_pieces[-1] <= 3
                            ):
                                anchor = nominal_pieces[0]
                                strength = 0.65
                    elif (
                        word.pos_ in ("NOUN", "PROPN")
                        and previous.pos_ in ("ADJ", "ADV")
                        and previous.head.i == word.i
                    ):
                        anchor, strength = previous_start, 0.55
                    elif (
                        word.pos_ == "ADP"
                        and previous.pos_ in ("ADV", "ADJ")
                    ):
                        anchor, strength = previous_start, 0.82

        if tokens[i].isspace():
            anchor, strength = i - 1, 0.56

        if anchor is not None:
            row *= 1.0 - strength
            row[anchor] += strength

        # The second token almost invariably selects the sequence start.
        if i == 1:
            row[:] = 0.0
            row[0], row[1] = 0.98, 0.02

        attention[i] = row

    return (
        "first_token_sink_with_local_anchors",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L3H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with gradually increasing positional leakage.
    Residual attention is diffuse and mildly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[0, 0] = 1.0
            continue

        sink_mass = 1.0 / (1.0 + 0.0035 * i ** 1.25)
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.75 + 0.25 * np.exp(-(i - positions) / 12.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_positional_leakage", attention


def prog_L3H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with positional decay and query-dependent strength.
    Residual attention favors recent context, predicate parallels, and quotation boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_linguistic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = []
    for indices in alignment:
        candidates = [doc[k] for k in indices if not doc[k].is_space]
        words.append(candidates[-1] if candidates else None)

    quote_openings = []
    active_quote = None
    for i, text in enumerate(tokens):
        if '"' in text or "“" in text or "”" in text:
            if active_quote is None:
                active_quote = i
            else:
                quote_openings.append((active_quote, i))
                active_quote = None

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        clean = tokens[i].lstrip("ĠĊ")

        sink = 0.40 + 0.59 * np.exp(-max(i - 1, 0) / 5.5)
        if pos in ("AUX", "ADP", "PART"):
            sink += 0.065
        elif pos in ("PRON", "CCONJ", "SCONJ"):
            sink += 0.025
        elif pos == "VERB":
            sink -= 0.12
        elif pos in ("NOUN", "PROPN", "ADJ"):
            sink -= 0.025

        if dep in ("conj", "ROOT") and pos == "VERB":
            sink -= 0.055
        if word is not None and word.tag_ in ("WDT", "WP", "WP$", "WRB"):
            sink += 0.10

        continuation = (
            i > 0
            and word is not None
            and words[i - 1] is not None
            and word.i == words[i - 1].i
        )
        if continuation:
            sink += 0.15
        if not clean.strip():
            sink -= 0.065
        if any(c in clean for c in '.!?;"“”'):
            sink -= 0.16
        if i == 1:
            sink = 0.98

        sink = float(np.clip(sink, 0.12, 0.995))
        positions = np.arange(1, i + 1)
        residual = 0.18 + np.exp(-(i - positions) / 4.0)

        if word is not None:
            for j in range(1, i + 1):
                prior = words[j]
                if prior is None:
                    continue
                if prior.i == word.head.i and prior.i != word.i:
                    residual[j - 1] += 0.8
                if j < i and pos == "VERB" and prior.pos_ == "VERB":
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    residual[j - 1] += 1.5 + 5.0 * max(similarity, 0.0)
                if j < i and prior.pos_ in ("VERB", "ADJ"):
                    residual[j - 1] += 0.35

            # Post-quotation inverted reporting clauses can retrieve the quote.
            inverted_subject = any(
                child.dep_ in ("nsubj", "nsubjpass") and child.i > word.i
                for child in word.children
            )
            if pos == "VERB" and inverted_subject:
                for opening, closing in reversed(quote_openings):
                    if closing < i and i - closing <= 4 and opening > 0:
                        sink = min(sink, 0.23)
                        residual[opening - 1] += 12.0 * residual.sum()
                        break

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "first_token_sink_with_linguistic_residual", attention


def prog_L3H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Subject/phrase anchors with a first-token sink.
    Phrase boundaries share their nominal anchor with its modifiers and subject.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "subject_and_phrase_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    word_tokens = [[] for _ in doc]
    token_words = []
    for i, indices in enumerate(alignment):
        valid = [k for k in indices if k < len(doc) and not doc[k].is_space]
        token_words.append(valid[0] if valid else -1)
        for k in valid:
            word_tokens[k].append(i)

    starts = [indices[0] if indices else -1 for indices in word_tokens]
    subjects = [-1] * len(doc)

    # Follow predicate coordination, auxiliaries, and controlled complements.
    for word in doc:
        current = word
        visited = set()
        for _ in range(10):
            if current.i in visited:
                break
            visited.add(current.i)
            candidates = [
                child for child in current.children
                if child.dep_ in (
                    "nsubj", "nsubjpass", "nsubj:pass",
                    "csubj", "csubjpass", "expl"
                )
            ]
            if candidates:
                subjects[word.i] = candidates[0].i
                break
            if current.head.i == current.i:
                break
            if current.dep_ not in (
                "aux", "auxpass", "cop", "conj", "xcomp",
                "advmod", "neg", "prt", "acomp", "attr"
            ):
                break
            current = current.head

    for i in range(n):
        positions = np.arange(i + 1, dtype=np.float64)
        recent = np.exp((positions - i) / 4.0)
        recent /= recent.sum()

        row = 0.16 * recent
        row[0] += 0.40
        row[i] += 0.20
        row[max(0, i - 1)] += 0.24

        if i == 0:
            attention[i, 0] = 1.0
            continue

        target = -1
        strength = 0.0
        wi = token_words[i]

        if wi >= 0:
            word = doc[wi]
            start = starts[wi]
            subject = subjects[wi]
            subject_start = starts[subject] if subject >= 0 else -1

            # Pieces of a split word share its first model-token anchor.
            if 0 <= start < i:
                target, strength = start, 0.62

            elif word.pos_ in ("VERB", "AUX"):
                if 0 <= subject_start < i:
                    distance = i - subject_start
                    pronominal = doc[subject].pos_ == "PRON"
                    strength = 0.73 if pronominal else 0.51
                    if distance > 5:
                        strength *= np.exp(-(distance - 5) / 14.0)
                    if word.dep_ == "xcomp":
                        strength *= 0.83
                    target = subject_start
                elif word.dep_ in ("acl", "relcl"):
                    head_start = starts[word.head.i]
                    if 0 <= head_start < i:
                        target, strength = head_start, 0.48
                elif word.dep_ in ("pcomp",):
                    head_start = starts[word.head.i]
                    if 0 <= head_start < i:
                        target, strength = head_start, 0.58

            elif word.pos_ in ("NOUN", "PROPN"):
                modifiers = []
                for child in word.children:
                    child_start = starts[child.i]
                    if 0 <= child_start < i and child.dep_ in (
                        "amod", "poss", "nmod:poss", "compound",
                        "det", "nummod", "quantmod"
                    ):
                        modifiers.append(child)

                if modifiers:
                    modifier = max(modifiers, key=lambda child: starts[child.i])
                    target = starts[modifier.i]
                    if modifier.dep_ in ("amod", "compound"):
                        strength = 0.69
                    elif modifier.dep_ in ("poss", "nmod:poss"):
                        strength = 0.55
                    elif modifier.pos_ in ("NUM", "ADJ"):
                        strength = 0.64
                    else:
                        strength = 0.31
                else:
                    target = i
                    strength = 0.43 if word.pos_ == "PROPN" else 0.35

            elif word.pos_ in ("ADV", "ADJ", "PART"):
                if 0 <= subject_start < i:
                    target = subject_start
                    strength = 0.61 if word.pos_ == "ADV" else 0.45
                elif word.dep_ in ("case", "poss", "neg"):
                    head_start = starts[word.head.i]
                    if 0 <= head_start < i:
                        target, strength = head_start, 0.55
                elif i > 0 and token_words[i - 1] >= 0:
                    previous = doc[token_words[i - 1]]
                    if previous.pos_ in ("ADV", "ADJ"):
                        target, strength = starts[previous.i], 0.48

            elif word.pos_ in ("ADP", "SCONJ", "CCONJ", "PUNCT"):
                previous_index = i - 1
                while previous_index > 0 and token_words[previous_index] < 0:
                    previous_index -= 1
                previous_word = token_words[previous_index]
                if previous_word >= 0:
                    previous = doc[previous_word]
                    if previous.pos_ in ("NOUN", "PROPN", "PRON", "NUM"):
                        target, strength = starts[previous_word], 0.57
                    elif previous.pos_ in ("ADV", "ADJ"):
                        target, strength = starts[previous_word], 0.46
                    elif previous.pos_ in ("VERB", "AUX"):
                        previous_subject = subjects[previous_word]
                        if previous_subject >= 0:
                            candidate = starts[previous_subject]
                            if 0 <= candidate < i:
                                target, strength = candidate, 0.29

            elif word.pos_ == "DET":
                # A determiner following a predicate often retains its subject.
                governor = word.head.head
                candidate_subject = subjects[governor.i]
                governor_start = starts[governor.i]
                if candidate_subject >= 0 and 0 <= governor_start < i:
                    candidate = starts[candidate_subject]
                    if 0 <= candidate < i and i - governor_start <= 3:
                        target, strength = candidate, 0.34

            elif word.pos_ == "PRON":
                if word.dep_ in ("nsubj", "nsubjpass", "nsubj:pass"):
                    target, strength = i, 0.16
                elif word.dep_ in ("dobj", "obj", "iobj"):
                    governor_subject = subjects[word.head.i]
                    if governor_subject >= 0:
                        candidate = starts[governor_subject]
                        if 0 <= candidate < i:
                            target, strength = candidate, 0.21

        if 0 <= target <= i:
            row *= 1.0 - strength
            row[target] += strength

        # A boundary after a nominal phrase need not select its head alone.
        # Redistribute only added anchor mass; keep self and baseline unchanged.
        if (
            wi >= 0
            and starts[wi] == i
            and doc[wi].pos_ in ("ADP", "SCONJ", "CCONJ", "PUNCT")
            and strength == 0.57
            and 0 <= target < i
            and token_words[target] >= 0
        ):
            anchor = doc[token_words[target]]
            alternatives = {}
            for child in anchor.children:
                candidate = starts[child.i]
                if 0 <= candidate < target and child.dep_ in (
                    "amod", "poss", "nmod:poss", "compound",
                    "det", "nummod", "quantmod"
                ):
                    alternatives[candidate] = 1.0

            current = anchor
            for _ in range(5):
                candidate_subject = subjects[current.i]
                if candidate_subject >= 0:
                    candidate = starts[candidate_subject]
                    if 0 <= candidate < i and candidate != target:
                        alternatives[candidate] = 1.5
                    break
                if current.head.i == current.i:
                    break
                current = current.head

            if alternatives:
                moved = 0.65 * strength
                row[target] -= moved
                total = sum(alternatives.values())
                for candidate, weight in alternatives.items():
                    row[candidate] += moved * weight / total

        # The first position acts as a particularly strong early fallback.
        if i == 1:
            first_weight = 0.975
            if wi >= 0 and doc[wi].pos_ in ("NOUN", "PROPN"):
                first_word = token_words[0]
                first_weight = 0.91
                if first_word >= 0 and doc[first_word].pos_ == "DET":
                    first_weight = (
                        0.955
                        if doc[first_word].dep_ in ("poss", "nmod:poss")
                        else 0.67
                    )
            elif wi >= 0 and doc[wi].pos_ in ("ADJ", "ADV"):
                first_weight = 0.86
            row[:] = 0.0
            row[0] = first_weight
            row[1] = 1.0 - first_weight
        elif i <= 3 and strength < 0.45:
            sink_mix = 0.36 if i == 2 else 0.17
            row *= 1.0 - sink_mix
            row[0] += sink_mix

        attention[i, :i + 1] = row

    return "subject_and_phrase_anchors", make_row_stochastic(attention)


def prog_L3H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local lexical anchors with a first-token sink.
    Opening dialogue quotes additionally attend to the preceding punctuation.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_lexical_anchor_with_quote_boundary", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    content_pos = {"NOUN", "PROPN", "PRON", "VERB", "ADJ", "NUM"}
    subject_deps = {"nsubj", "nsubjpass", "csubj", "csubjpass"}
    boundary_pos = {"ADP", "CCONJ", "SCONJ", "PART"}

    for i in range(n):
        if i == 0:
            matrix[i, 0] = 1.0
            continue
        if i == 1:
            matrix[i, 0] = 0.96
            matrix[i, i] = 0.04
            continue

        current = doc[alignment[i][-1]] if alignment[i] else None
        previous = doc[alignment[i - 1][-1]] if alignment[i - 1] else None

        # A modest, diffuse causal background leaves room for secondary edges.
        distances = np.arange(i, -1, -1, dtype=np.float64)
        background = np.exp(-distances / 5.0)
        background /= background.sum()
        matrix[i, :i + 1] = 0.10 * background
        matrix[i, 0] += 0.36
        matrix[i, i] += 0.04
        matrix[i, i - 1] += 0.12

        anchor = i - 1
        strength = 0.38
        sink = 0.0

        if current is None or current.is_space:
            strength = 0.65
        elif current.is_punct:
            # Closing punctuation generally summarizes the last lexical item.
            for j in range(i - 1, -1, -1):
                if alignment[j]:
                    word = doc[alignment[j][-1]]
                    if not word.is_punct and not word.is_space:
                        anchor = j
                        break
            strength = 0.76
        elif previous is not None and previous.is_punct:
            strength = 0.35
            sink = 0.20
        elif current.pos_ in boundary_pos:
            for j in range(i - 1, -1, -1):
                if alignment[j] and doc[alignment[j][-1]].pos_ in content_pos:
                    anchor = j
                    break
            strength = 0.72
        elif current.pos_ in {"VERB", "AUX"}:
            candidates = []
            for child in current.children:
                if child.dep_ in subject_deps:
                    candidates.extend(j for j in inverse[child.i] if j < i)
            if candidates:
                anchor = max(candidates)
                strength = 0.74 if i - anchor <= 3 else 0.48
            elif current.head.i != current.i:
                candidates = [j for j in inverse[current.head.i] if j < i]
                if candidates and current.head.pos_ in {"ADJ", "NOUN", "PRON"}:
                    anchor = max(candidates)
                    strength = 0.76
            elif previous is not None and previous.pos_ in content_pos:
                strength = 0.66
        elif current.pos_ in {"NOUN", "PROPN"}:
            if previous is not None and previous.pos_ in {"ADJ", "NUM"}:
                strength = 0.78
            elif previous is not None and previous.pos_ in {"VERB", "PROPN", "NOUN"}:
                strength = 0.57
            else:
                strength = 0.19
                sink = 0.25
        elif current.pos_ == "DET":
            for j in range(i - 1, -1, -1):
                if alignment[j] and doc[alignment[j][-1]].pos_ in content_pos:
                    anchor = j
                    break
            strength = 0.44
        elif current.pos_ == "ADJ":
            candidates = [j for j in inverse[current.head.i] if j < i]
            if candidates:
                anchor = max(candidates)
                strength = 0.58
        elif current.pos_ == "PRON":
            strength = 0.48 if previous is not None and previous.pos_ in content_pos else 0.23

        # Normalize the anchor mixture separately so confidence is interpretable.
        matrix[i] *= (1.0 - strength - sink) / matrix[i].sum()
        matrix[i, anchor] += strength
        matrix[i, 0] += sink

        # A quote following a dialogue delimiter retains that boundary instead
        # of skipping it entirely. Transfer only anchor mass; keep self and
        # every other edge unchanged.
        if (
            current is not None
            and current.is_quote
            and previous is not None
            and previous.is_punct
            and previous.text in {",", ":", ";"}
            and anchor != i - 1
            and alignment[anchor]
        ):
            anchor_word = doc[alignment[anchor][-1]]
            fraction = 0.70 if anchor_word.pos_ in {"VERB", "AUX"} else 0.45
            transfer = fraction * strength
            matrix[i, anchor] -= transfer
            matrix[i, i - 1] += transfer

    return (
        "local_lexical_anchor_with_quote_boundary",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L3H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attend to syntactic left boundaries, inheriting a coordination boundary
    across the subject of a coordinated clause even when its attachment is nonlocal.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "syntactic_left_boundary", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, sids in enumerate(alignment):
        for si in sids:
            inverse[si].append(ti)

    first_piece = [pieces[0] if pieces else -1 for pieces in inverse]
    last_piece = [pieces[-1] if pieces else -1 for pieces in inverse]

    nominal_links = {
        "det", "predet", "amod", "compound", "poss",
        "nummod", "quantmod", "case", "flat", "fixed"
    }
    complement_links = {
        "dobj", "obj", "iobj", "dative", "pobj", "pcomp",
        "attr", "acomp", "oprd", "xcomp", "ccomp"
    }
    subject_links = {"nsubj", "nsubjpass", "csubj", "csubjpass"}
    clause_pos = {"VERB", "AUX"}

    for i in range(n):
        if i == 0:
            matrix[i, 0] = 1.0
            continue

        row = matrix[i]
        row[0] = 0.70
        row[i] += 0.16
        row[i - 1] += 0.20
        for j in range(max(1, i - 7), i):
            row[j] += 0.035 * np.exp(-(i - j) / 2.5)

        if i == 1:
            row[:] = 0.0
            row[0] = 0.95
            row[1] = 0.05
            continue

        candidates = {}
        sids = alignment[i]
        word = None
        for si in sids:
            if not doc[si].is_space:
                word = doc[si]
                break

        if word is not None:
            node = word
            for _ in range(8):
                if node.dep_ not in nominal_links or node.head.i == node.i:
                    break
                node = node.head

            # A nominal phrase shares the introducer of its syntactic head.
            if node.dep_ in complement_links:
                anchor = last_piece[node.head.i]
                if 0 <= anchor < i:
                    candidates[anchor] = 2.9

            if node.dep_ in {"prep", "agent", "prt", "advmod", "advcl"}:
                anchor = last_piece[node.head.i]
                if 0 <= anchor < i:
                    candidates[anchor] = max(candidates.get(anchor, 0.0), 1.65)

            # Coordinated phrases begin at their conjunction.
            if node.dep_ == "conj":
                left = min(node.head.i, node.i)
                for k in range(left, node.i):
                    if doc[k].pos_ == "CCONJ":
                        anchor = last_piece[k]
                        if 0 <= anchor < i:
                            candidates[anchor] = max(
                                candidates.get(anchor, 0.0), 3.0
                            )

            # Clause markers and preverbal auxiliaries delimit a local domain.
            clause = node
            for _ in range(8):
                if clause.pos_ in clause_pos or clause.head.i == clause.i:
                    break
                clause = clause.head

            if clause.pos_ in clause_pos:
                for child in clause.children:
                    anchor = last_piece[child.i]
                    if not (0 <= anchor < i):
                        continue
                    if child.dep_ == "mark":
                        strength = 2.8
                    elif child.dep_ in {"aux", "auxpass", "cop"}:
                        strength = 2.5
                    elif child.dep_ == "cc":
                        strength = 2.6
                    elif (
                        child.dep_ == "advmod"
                        and child.i < clause.i
                        and clause.i - child.i <= 2
                        and (node.i == clause.i or node.dep_ in subject_links)
                    ):
                        strength = 2.0
                    elif (
                        child.dep_ in subject_links
                        and child.tag_ in {"WDT", "WP", "WP$"}
                    ):
                        strength = 2.6
                    else:
                        continue
                    candidates[anchor] = max(
                        candidates.get(anchor, 0.0), strength
                    )

            # Initial subjects and unintroduced clauses fall back to token zero.
            if node.dep_ in subject_links and not candidates:
                row[0] += 0.65
            if first_piece[node.i] == 0:
                row[0] += 1.15

            # Recover a clause-initial coordinator attached outside this clause.
            # Restrict this repair to its preverbal subject and predicate, leaving
            # complements and already-recognized coordination boundaries alone.
            if (
                clause.pos_ in clause_pos
                and not word.is_punct
                and (node.i == clause.i or node.dep_ in subject_links)
            ):
                for subject in clause.children:
                    if subject.dep_ not in subject_links or subject.i >= clause.i:
                        continue
                    start = min(t.i for t in subject.subtree)
                    if start == 0:
                        continue
                    coordinator = doc[start - 1]
                    anchor = last_piece[coordinator.i]
                    if (
                        coordinator.pos_ == "CCONJ"
                        and coordinator.dep_ == "cc"
                        and 0 < anchor < i
                        and anchor not in candidates
                    ):
                        external_head = last_piece[clause.head.i]
                        if clause.head.i != clause.i:
                            candidates.pop(external_head, None)
                        if node.dep_ in subject_links and not candidates:
                            row[0] -= 0.65
                        candidates[anchor] = 3.0
                        break

            # Punctuation is itself a boundary rather than a content dependent.
            if word.is_punct:
                candidates = {}
                row[i] += 0.85
                if word.dep_ == "punct":
                    anchor = last_piece[word.head.i]
                    if 0 <= anchor < i:
                        candidates[anchor] = 0.65

            # A comma or sentence boundary also introduces the next short span.
            for j in range(max(0, i - 3), i):
                clean = tokens[j].lstrip("Ġ").strip()
                if clean and any(c in clean for c in ",;:!?"):
                    distance = i - j
                    strength = 2.15 * np.exp(-0.43 * (distance - 1))
                    candidates[j] = max(candidates.get(j, 0.0), strength)

        else:
            # Whitespace and unmatched byte pieces usually inherit the boundary.
            row[i - 1] += 2.3

        for anchor, strength in candidates.items():
            distance = i - anchor
            strength *= np.exp(-0.065 * max(0, distance - 2))
            row[anchor] += strength

        # Split words retain their phrase-level anchor instead of copying
        # their immediately preceding subword.
        if word is not None and first_piece[word.i] < i:
            row[i - 1] *= 0.65

    return "syntactic_left_boundary", make_row_stochastic(apply_causal_mask(matrix))


def prog_L3H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with predicate anchors; transparent prepositions and
    infinitival markers defer to lexical governors, while finite auxiliaries anchor predicates.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_sink_with_predicate_anchors", attention

    doc = spacy_parse(sentence)
    forward = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    for i in range(n):
        if i == 0:
            attention[0, 0] = 1.0
            continue

        # A persistent sink, with a small diffuse causal background.
        attention[i, 0] = 1.0
        positions = np.arange(i + 1)
        background = np.exp(-(i - positions) / 8.0)
        attention[i, :i + 1] += 0.08 * background / background.sum()

        sids = forward[i]
        if not sids:
            continue
        sid = sids[-1]
        word = doc[sid]
        if word.is_space:
            continue

        # Walk through nominal structure to a visible governing predicate.
        anchor = None
        ancestor = word.head
        visited = {word.i}
        depth = 0
        while ancestor.i not in visited and depth < 7:
            visited.add(ancestor.i)
            visible = [j for j in inverse[ancestor.i] if j < i]
            if visible and ancestor.pos_ in ("VERB", "AUX", "ADP", "ADJ", "ADV"):
                anchor = ancestor
                break
            if ancestor.head.i == ancestor.i:
                break
            ancestor = ancestor.head
            depth += 1

        target = None
        if anchor is not None:
            visible = [j for j in inverse[anchor.i] if j < i]
            if visible:
                target = visible[-1]

        # Subjects and lexical predicates can instead retrieve a preceding
        # auxiliary belonging to their clause.
        if word.pos_ in ("VERB", "ADJ", "PRON") or word.dep_ in (
            "nsubj", "nsubjpass", "csubj"
        ):
            clause = word.head if word.dep_ in (
                "nsubj", "nsubjpass", "csubj"
            ) else word
            auxiliary_targets = []
            for child in clause.children:
                if child.dep_ in ("aux", "auxpass", "cop"):
                    auxiliary_targets.extend(
                        j for j in inverse[child.i] if j < i
                    )
            if auxiliary_targets:
                target = max(auxiliary_targets)

        # Special case: a functional intermediary is not always the anchor.
        # Only redirect an ADP when its immediate governor is predicate-like.
        finite_auxiliary_target = False
        if target is not None:
            target_sids = forward[target]
            selected = doc[target_sids[-1]] if target_sids else None
            if selected is not None:
                if (
                    selected.pos_ == "ADP"
                    and selected.head.pos_ in ("VERB", "AUX", "ADJ", "ADV")
                    and selected.head.i != word.i
                ):
                    visible = [
                        j for j in inverse[selected.head.i] if j < i
                    ]
                    if visible:
                        target = visible[-1]
                elif (
                    word.pos_ == "VERB"
                    and word.dep_ == "xcomp"
                    and selected.head.i == word.i
                    and selected.dep_ in ("aux", "mark")
                    and selected.tag_ == "TO"
                    and word.head.pos_ in ("VERB", "AUX", "ADJ")
                ):
                    visible = [j for j in inverse[word.head.i] if j < i]
                    if visible:
                        target = visible[-1]
                elif (
                    word.pos_ in ("VERB", "ADJ")
                    and selected.head.i == word.i
                    and selected.dep_ in ("aux", "auxpass", "cop")
                    and selected.tag_ in ("MD", "VBD", "VBP", "VBZ")
                ):
                    finite_auxiliary_target = True

        strength = 0.0
        if target is not None and target > 0:
            if word.dep_ in ("prt", "compound:prt"):
                strength = 7.0
            elif word.pos_ == "ADP":
                strength = 4.0
            elif word.dep_ in ("aux", "auxpass", "mark"):
                strength = 2.7
            elif word.pos_ == "DET" or word.dep_ == "poss":
                strength = 2.6
            elif word.dep_ in ("xcomp", "acomp", "oprd", "attr"):
                strength = 2.6
            elif word.pos_ == "PRON":
                strength = 1.6
            elif word.pos_ == "VERB" and word.dep_ not in ("ROOT", "conj"):
                strength = 1.8
            elif word.pos_ == "ADV":
                strength = 1.1 if word.dep_ in ("advmod", "npadvmod") else 0.3
            elif word.pos_ in ("NOUN", "PROPN"):
                if word.head.pos_ == "ADP":
                    strength = 1.5
                elif word.dep_ in ("dobj", "obj", "iobj", "dative"):
                    strength = 1.5 if i - target <= 2 else 0.35
                else:
                    strength = 0.15
            elif word.pos_ == "ADJ":
                strength = 0.25
            elif word.is_punct:
                strength = 0.15

            # The original ROOT/conj exclusion otherwise silences a valid
            # preceding finite auxiliary selected by the existing logic.
            if finite_auxiliary_target:
                strength = max(strength, 1.8)

            # Short spans are especially reliable; long-range syntax is weaker.
            distance = i - target
            strength *= 0.65 + 0.35 * np.exp(-max(distance - 2, 0) / 12.0)
            if i <= 2:
                strength *= 0.15
            attention[i, target] += strength

        # Opening quotation punctuation can look back to a reporting predicate.
        if word.is_punct and any(c in tokens[i] for c in ('"', "“", "‘")):
            for k in range(sid - 1, max(-1, sid - 7), -1):
                previous = doc[k]
                visible = [j for j in inverse[k] if j < i]
                if previous.pos_ == "VERB" and visible:
                    attention[i, visible[-1]] += 0.9
                    break

    return (
        "first_sink_with_predicate_anchors",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L3H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with decay; closing dialogue quotes redirect some sink
    mass to the matching opening quote without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_quote_return", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    quote_marks = ('"', "\u201c", "\u201d")
    quote_open = 0 if any(q in tokens[0] for q in quote_marks) else None

    for i in range(1, n):
        sink = 0.54 + 0.445 * np.exp(-0.30 * (i - 1) ** 0.85)

        if i > 1 and alignment[i]:
            word = doc[alignment[i][-1]]
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink += 0.025
            elif word.pos_ in ("PRON", "AUX"):
                sink -= 0.025
            elif word.pos_ == "PUNCT":
                sink -= 0.015

        sink = float(np.clip(sink, 0.45, 0.995))
        attention[i, 0] = sink

        # Preserve the original residual distribution and diagonal exactly.
        positions = np.arange(1, i + 1)
        residual = 1.0 + 1.5 * np.exp(-(i - positions) / 3.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        # Only matched closing-quote rows receive the special-case correction.
        if any(q in tokens[i] for q in quote_marks):
            if quote_open is None:
                quote_open = i
            else:
                if quote_open > 0:
                    transfer = min(
                        attention[i, 0],
                        0.27 if "!" in tokens[i] else 0.22,
                    )
                    attention[i, 0] -= transfer
                    attention[i, quote_open] += transfer
                quote_open = None

    return "first_token_sink_with_quote_return", attention


def prog_L3H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Mix a first-token sink with short-range attention to salient phrase anchors:
    modifiers, predicates, and the content word preceding function words."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "local_phrase_anchor_with_first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            inverse[si].append(ti)

    words = [doc[indices[-1]] if indices else None for indices in alignment]
    anchor_strength = {
        "ADJ": 7.2, "ADV": 7.0, "VERB": 3.2, "AUX": 1.5,
        "NOUN": 0.65, "PROPN": 0.55, "PRON": 0.7,
        "ADP": 1.6, "SCONJ": 2.4, "CCONJ": 0.4,
        "DET": 0.2, "NUM": 2.3, "PART": 0.5,
    }

    for i in range(n):
        row = attention[i]
        if i == 0:
            row[0] = 1.0
            continue

        row[:i + 1] = 0.025
        row[0] += 3.4
        row[i] += 0.20
        if i == 1:
            row[0] += 10.0
        elif i == 2:
            row[0] += 1.7

        current = words[i]
        if current is None or current.is_space:
            row[0] += 2.0
            continue

        pos = current.pos_
        dep = current.dep_
        if pos in ("ADJ", "ADV"):
            row[i] += 1.0

        for j in range(max(1, i - 8), i):
            previous = words[j]
            if previous is None or previous.is_space:
                continue
            if previous.i == current.i:
                row[j] += 4.0 * np.exp(-0.6 * (i - j - 1))
                continue
            # Use one anchor per linguistic word, not one per subword.
            if inverse[previous.i] and j != inverse[previous.i][-1]:
                continue

            distance = i - j
            decay = np.exp(-0.48 * (distance - 1))
            strength = anchor_strength.get(previous.pos_, 0.15)

            if previous.pos_ == "PUNCT":
                strength = 0.08
            elif previous.pos_ in ("NOUN", "PROPN"):
                if pos in ("ADP", "PUNCT"):
                    strength = 7.0
                elif dep == "appos" and current.head.i == previous.i:
                    strength = 6.0
                elif pos == "DET":
                    strength = 1.4
            elif previous.pos_ == "VERB":
                if pos in ("ADP", "PART", "DET", "PRON", "PUNCT"):
                    strength = 6.0
                elif pos in ("NOUN", "PROPN"):
                    strength = 2.7
            elif previous.pos_ == "AUX":
                if pos == "PRON":
                    strength = 5.0
            elif previous.pos_ == "ADP":
                if pos in ("DET", "PRON") or dep == "pcomp":
                    strength = 4.7

            if previous.tag_ in ("WDT", "WP", "WP$", "WRB"):
                strength = max(strength, 6.0)
            if previous.dep_ in ("advmod", "npadvmod", "neg", "quantmod"):
                strength = max(strength, 7.2)
            if previous.pos_ == "ADJ" and pos in (
                "NOUN", "ADJ", "CCONJ", "SCONJ", "ADP", "PRON", "AUX"
            ):
                strength = max(strength, 8.0)

            # Punctuation limits the reach of a local phrase anchor.
            for k in range(j + 1, i):
                middle = words[k]
                if middle is not None and middle.pos_ == "PUNCT":
                    decay *= 0.60

            row[j] += strength * decay

        # Backward dependency links supplement the positional anchor prior.
        if current.head.i < current.i:
            candidates = [j for j in inverse[current.head.i] if j < i]
            if candidates:
                j = candidates[-1]
                gap = i - j
                strength = 0.0
                if dep in ("prep", "agent", "mark", "aux", "auxpass"):
                    strength = 5.0
                elif dep in ("dobj", "obj", "iobj", "dative"):
                    strength = 5.0 if pos == "PRON" else 1.5
                elif dep in ("xcomp", "ccomp"):
                    strength = 4.0
                elif dep in ("poss", "det") and current.head.pos_ == "VERB":
                    strength = 4.0
                row[j] += strength * np.exp(-0.28 * max(0, gap - 1))

        # A preceding modifier can anchor its noun or predicate.
        for child in current.children:
            if child.dep_ not in ("amod", "advmod", "neg", "quantmod"):
                continue
            candidates = [j for j in inverse[child.i] if j < i]
            if candidates:
                j = candidates[-1]
                row[j] += 5.0 * np.exp(-0.40 * (i - j - 1))

    return (
        "local_phrase_anchor_with_first_token_sink",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L4H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with complement-governor attention; nominal phrases
    share some governor mass with their preceding determiner or possessive."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "sink_governor_determiner_sharing", attention

    doc = spacy_parse(sentence)
    forward = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    governors = [None] * len(doc)
    strengths = np.zeros(len(doc), dtype=np.float64)
    phrase_links = {
        "det", "predet", "amod", "compound", "poss",
        "nummod", "quantmod", "flat", "fixed"
    }
    object_links = {"dobj", "obj", "iobj", "dative", "pobj"}

    for word in doc:
        current = word
        visited = set()

        # Inherit an object's governor throughout its nominal phrase.
        while current.i not in visited:
            visited.add(current.i)
            dep = current.dep_
            head = current.head

            if dep in object_links:
                if head.i < word.i and head.pos_ in {"VERB", "AUX", "ADP"}:
                    governors[word.i] = head.i
                    if word.pos_ == "PRON":
                        strengths[word.i] = 0.89
                    elif word.pos_ in {"DET", "ADJ", "NUM"}:
                        strengths[word.i] = 0.83
                    else:
                        strengths[word.i] = 0.79
                break

            if dep in phrase_links or (
                dep == "conj" and current.pos_ in {"NOUN", "PROPN", "PRON"}
            ):
                if head.i == current.i:
                    break
                current = head
                continue
            break

        # Prepositions can introduce a verbal complement; their objects
        # subsequently point back to the preposition itself.
        if word.dep_ == "prep" and word.head.pos_ == "VERB":
            if word.head.i < word.i:
                governors[word.i] = word.head.i
                strengths[word.i] = 0.61

        if word.dep_ == "prt" and word.head.i < word.i:
            governors[word.i] = word.head.i
            strengths[word.i] = 0.86

        # Coordinate markers inside an object inherit that object's anchor.
        if word.dep_ == "cc":
            current = word.head
            visited = set()
            while current.i not in visited:
                visited.add(current.i)
                if current.dep_ in object_links:
                    if current.head.i < word.i:
                        governors[word.i] = current.head.i
                        strengths[word.i] = 0.66
                    break
                if current.dep_ in phrase_links or current.dep_ == "conj":
                    current = current.head
                else:
                    break

        # Wh-degree constructions retain their local introductory anchor.
        if word.pos_ == "ADJ":
            for child in word.children:
                if child.tag_ == "WRB" and child.i < word.i:
                    governors[word.i] = child.i
                    strengths[word.i] = 0.72

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        # Small causal background, with the unused head defaulting to BOS.
        distances = np.arange(i, -1, -1, dtype=np.float64)
        background = np.exp(-distances / 4.0)
        background /= background.sum()
        attention[i, :i + 1] = 0.05 * background
        attention[i, 0] += 0.95

        aligned = forward[i]
        if not aligned:
            continue

        sid = max(aligned, key=lambda k: len(doc[k].text.strip()))
        word = doc[sid]
        governor = governors[sid]
        strength = strengths[sid]

        # Commas may close an object phrase rather than reset immediately.
        if word.is_punct and word.text in {",", ":", ";"} and sid > 0:
            previous = sid - 1
            if governors[previous] is not None:
                governor = governors[previous]
                strength = 0.48

        if governor is None:
            continue

        candidates = [j for j in inverse[governor] if j < i]
        if not candidates:
            continue

        target = max(candidates)
        attention[i] *= 1.0 - strength
        attention[i, target] += strength

        # A determiner introduces a secondary anchor inside an object phrase.
        # Transfer only explicit governor mass: self-attention and the causal
        # background remain exactly as in the original implementation.
        if word.pos_ in {"NOUN", "PROPN", "ADJ", "NUM"}:
            nominal = word
            visited = set()
            while nominal.i not in visited:
                visited.add(nominal.i)
                if nominal.dep_ in object_links:
                    break
                if nominal.dep_ not in phrase_links | {"conj"}:
                    break
                if nominal.head.i == nominal.i:
                    break
                nominal = nominal.head

            if (
                nominal.dep_ in object_links
                and nominal.pos_ in {"NOUN", "PROPN"}
            ):
                determiners = [
                    child for child in nominal.children
                    if child.dep_ in {"det", "poss"} and child.i < word.i
                ]
                if determiners:
                    determiner = min(determiners, key=lambda child: child.i)
                    anchors = [
                        j for j in inverse[determiner.i] if j < i
                    ]
                    if anchors:
                        anchor = max(anchors)
                        if anchor != target:
                            share = 0.28 if word.pos_ in {"NOUN", "PROPN"} else 0.22
                            if target == 0:
                                share = 0.70
                            transfer = min(share, strength)
                            attention[i, target] -= transfer
                            attention[i, anchor] += transfer

    return "sink_governor_determiner_sharing", make_row_stochastic(
        apply_causal_mask(attention)
    )


def prog_L4H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, overridden by nearby leftward phrase and clause anchors.
    Clause introducers and heads of embedded complements provide secondary targets.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_with_phrase_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(aligned):
        for si in indices:
            inverse[si].append(ti)

    for i in range(n):
        if i == 0:
            attention[0, 0] = 1.0
            continue

        distance = i - np.arange(i + 1)
        background = np.exp(-distance / 5.0)
        attention[i, :i + 1] = 0.22 * background / background.sum()
        attention[i, 0] += 1.45 + 10.0 * np.exp(-i / 1.35)
        attention[i, i] += 0.035

        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        indices = aligned[i]
        if not indices or not clean:
            attention[i, 0] += 0.8
            continue

        si = max(indices, key=lambda k: len(doc[k].text))
        word = doc[si]
        if word.is_punct:
            attention[i, 0] += 1.25
            continue

        candidates = {}

        def add_anchor(anchor, strength):
            positions = inverse[anchor.i]
            if not positions:
                return
            j = positions[0]
            if 0 < j < i:
                # Keep a phrase anchor stable across its BPE pieces.
                gap = max(0, i - positions[-1] - 1)
                value = strength * np.exp(-gap / 12.0)
                candidates[j] = max(candidates.get(j, 0.0), value)

        node = word
        visited = set()
        for depth in range(6):
            if node.i in visited:
                break
            visited.add(node.i)
            attenuation = 0.80 ** depth

            # Clause-initial function words often receive attention from
            # the subject, auxiliaries, and predicate that follow them.
            for child in node.children:
                if child.i >= word.i:
                    continue
                if child.dep_ == "mark":
                    add_anchor(child, 5.8 * attenuation)
                elif child.dep_ == "cc":
                    add_anchor(child, 3.4 * attenuation)
                elif child.tag_ in ("WDT", "WP", "WP$", "WRB"):
                    add_anchor(child, 4.0 * attenuation)
                elif child.tag_ == "TO":
                    add_anchor(child, 4.0 * attenuation)

            # Participial clauses can act as their own left boundary.
            if node.dep_ in ("advcl", "acl") and node.tag_ in ("VBG", "VBN"):
                add_anchor(node, 5.0 * attenuation)

            parent = node.head
            if parent.i == node.i:
                break

            if parent.i < word.i:
                if node.dep_ in ("ccomp", "xcomp"):
                    add_anchor(parent, 4.8 * attenuation)
                elif node.dep_ in ("pcomp", "pobj"):
                    strength = 5.4 if node.dep_ == "pcomp" else 1.6
                    add_anchor(parent, strength * attenuation)
                    if parent.head.i < parent.i:
                        add_anchor(parent.head, 2.3 * attenuation)
                elif node.dep_ in ("dobj", "obj", "dative", "attr", "oprd"):
                    add_anchor(parent, 1.25 * attenuation)
                elif node.dep_ == "prep":
                    add_anchor(parent, 2.5 * attenuation)
                elif node.dep_ in ("aux", "auxpass"):
                    add_anchor(parent, 1.8 * attenuation)

            node = parent

        # A comma or whitespace boundary is a weaker fallback when no
        # linguistically stronger phrase introducer is available.
        for j in range(i - 1, max(0, i - 5), -1):
            previous = tokens[j].replace("Ġ", " ").strip()
            if previous == ",":
                candidates[j] = max(
                    candidates.get(j, 0.0),
                    1.7 * np.exp(-(i - j - 1) / 2.5),
                )
                break
            if not previous:
                candidates[j] = max(
                    candidates.get(j, 0.0),
                    1.3 * np.exp(-(i - j - 1) / 2.0),
                )
                break

        # Retain competing interpretations without allowing long ancestor
        # chains to overwhelm the persistent first-token sink.
        ranked = sorted(candidates.items(), key=lambda item: item[1], reverse=True)
        for rank, (j, strength) in enumerate(ranked[:3]):
            attention[i, j] += strength * (0.32 ** rank)

    return (
        "first_token_with_phrase_anchors",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L4H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with length dilution and linguistic modulation.
    Residual attention is diffuse and mildly recency-biased, especially in dialogue.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos_strength = {
        "DET": 1.18,
        "ADP": 1.18,
        "CCONJ": 1.12,
        "SCONJ": 0.95,
        "AUX": 1.10,
        "VERB": 1.00,
        "PRON": 0.94,
        "PROPN": 1.10,
        "NOUN": 0.78,
        "ADJ": 0.73,
        "ADV": 0.88,
        "PART": 0.78,
        "PUNCT": 1.12,
        "SPACE": 1.50,
    }

    in_quote = False
    attention[0, 0] = 1.0

    for i, token in enumerate(tokens):
        clean = token.lstrip("Ġ").lstrip("Ċ")
        quoted = in_quote
        for char in clean:
            if char == '"':
                in_quote = not in_quote
            elif char in ("“", "«"):
                in_quote = True
            elif char in ("”", "»"):
                in_quote = False

        if i == 0:
            continue

        strength = 1.0
        if alignment[i]:
            word = doc[alignment[i][-1]]
            strength = pos_strength.get(word.pos_, 1.0)
            if word.dep_ in ("poss", "nmod:poss"):
                strength *= 1.15

        if not clean or clean.isspace():
            strength = 1.65

        # The first few positions have especially strong sink preference.
        strength *= 1.0 + 0.40 * np.exp(-(i - 1) / 2.0)

        # Dialogue often draws attention away from the sequence-start sink.
        if quoted and in_quote:
            strength *= 0.55

        sink_weight = 30.0 * strength
        distances = i - np.arange(1, i + 1)
        attention[i, 1:i + 1] = 0.75 + 0.50 * np.exp(-distances / 7.0)
        attention[i, 0] = sink_weight

    return "first_token_sink_with_dilution", make_row_stochastic(attention)


def prog_L4H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Subject-anchor attention: predicates track their clause's subject,
    while other tokens mostly use the first-token sink or a nearby nominal anchor.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "subject_anchor_with_first_token_sink", attention

    doc = spacy_parse(sentence)
    word_tokens = align_spacy_to_tokens(sentence, tokens, tokenizer)
    token_words = [[] for _ in range(n)]
    for wi, indices in enumerate(word_tokens):
        for ti in indices:
            if ti < n:
                token_words[ti].append(wi)

    # Resolve subjects through coordination, auxiliaries, and controlled clauses.
    subjects = {}
    for word in doc:
        current = word
        visited = set()
        subject = None
        for _ in range(12):
            if current.i in visited:
                break
            visited.add(current.i)

            candidates = [
                child for child in current.children
                if child.dep_ in ("nsubj", "nsubjpass", "csubj", "csubjpass")
            ]
            if candidates:
                subject = min(candidates, key=lambda child: child.i)
                # Relative subjects point to the antecedent rather than the
                # intervening relative pronoun.
                if (
                    current.dep_ == "relcl"
                    and subject.pos_ == "PRON"
                    and current.head.pos_ in ("NOUN", "PROPN", "PRON")
                ):
                    subject = current.head
                break

            if current.dep_ == "relcl" and current.head.pos_ in (
                "NOUN", "PROPN", "PRON"
            ):
                subject = current.head
                break

            if current.head.i == current.i:
                break
            if current.dep_ in (
                "conj", "xcomp", "advcl", "aux", "auxpass", "acomp",
                "attr", "oprd", "advmod", "neg", "prt", "mark"
            ):
                current = current.head
            else:
                break
        subjects[word.i] = subject.i if subject is not None else None

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        # Broad residual attention, dominated by the first position.
        base = np.zeros(n, dtype=np.float64)
        distances = i - np.arange(i + 1)
        base[:i + 1] = 0.10 * np.exp(-distances / 7.0)
        base[0] += 1.0
        base[i - 1] += 0.10
        base[i] += 0.025
        base /= base.sum()

        target = None
        confidence = 0.0
        mapped = token_words[i]
        if mapped:
            wi = max(
                mapped,
                key=lambda k: (
                    not doc[k].is_space,
                    not doc[k].is_punct,
                    len(doc[k].text),
                ),
            )
            word = doc[wi]
            subject_id = subjects.get(wi)
            anchor_word = None

            if word.pos_ in ("VERB", "AUX"):
                anchor_word = subject_id
                confidence = 0.86 if word.pos_ == "VERB" else 0.88
                if word.dep_ in ("xcomp", "advcl"):
                    confidence = 0.71
            elif word.dep_ in ("acomp", "oprd"):
                anchor_word = subject_id
                confidence = 0.82
            elif word.dep_ == "attr":
                anchor_word = subject_id
                confidence = 0.49
            elif word.dep_ in ("advmod", "neg", "prt"):
                anchor_word = subject_id
                confidence = 0.61
            elif word.dep_ == "mark" and word.head.pos_ in ("VERB", "AUX"):
                anchor_word = subjects.get(word.head.i)
                confidence = 0.57
            elif word.dep_ == "case" and word.head.pos_ in (
                "NOUN", "PROPN", "PRON"
            ):
                anchor_word = word.head.i
                confidence = 0.86
            elif word.pos_ == "ADP" and word.head.pos_ in (
                "NOUN", "PROPN", "PRON"
            ):
                anchor_word = word.head.i
                confidence = 0.60
            elif word.dep_ in ("nsubj", "nsubjpass") and word.pos_ == "PRON":
                if word.head.dep_ == "relcl":
                    anchor_word = word.head.head.i
                    confidence = 0.77

            # Nominal coordination and commas often retain a local noun anchor.
            if word.pos_ == "CCONJ":
                head = word.head
                if head.pos_ in ("NOUN", "PROPN"):
                    if head.dep_ == "conj":
                        head = head.head
                    anchor_word = head.i
                    confidence = 0.53

            if word.is_punct and word.text in (",", ";", ":"):
                previous = wi - 1
                while previous >= 0 and doc[previous].is_space:
                    previous -= 1
                if previous >= 0 and doc[previous].pos_ in (
                    "NOUN", "PROPN", "PRON"
                ):
                    anchor_word = previous
                    confidence = 0.64
                elif subject_id is not None:
                    anchor_word = subject_id
                    confidence = 0.38

            if anchor_word is not None:
                # Use the last subtoken of a lexical anchor, never a future one.
                preceding = [
                    j for j in word_tokens[anchor_word] if j < i
                ]
                if preceding:
                    target = max(preceding)

            # Content inside noun phrases generally falls back to the sink.
            if target is None:
                if word.pos_ in ("DET", "NOUN", "PROPN", "PRON", "ADJ"):
                    target = 0
                    confidence = 0.40
                elif word.is_space or word.is_punct:
                    target = 0
                    confidence = 0.42

        else:
            target = 0
            confidence = 0.50

        if target is not None:
            # Dependencies spanning many intervening tokens are less certain.
            if target != 0:
                confidence *= 0.86 + 0.14 * np.exp(
                    -max(0, i - target - 2) / 20.0
                )
            attention[i] = (1.0 - confidence) * base
            attention[i, target] += confidence
        else:
            attention[i] = base

        if i == 1 and (target is None or target == 0):
            attention[i] *= 0.20
            attention[i, 0] += 0.80

    return (
        "subject_anchor_with_first_token_sink",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L4H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with slowly declining dominance and a
    weak, recency-biased residual modulated by linguistic features.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    pos = []
    for indices in alignment:
        candidates = [doc[k] for k in indices if not doc[k].is_space]
        pos.append(candidates[-1].pos_ if candidates else "")

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink = 0.985 - 0.085 * np.log(float(i))

        if pos[i] in ("NOUN", "PROPN", "ADJ"):
            sink += 0.015
        elif pos[i] in ("VERB", "AUX"):
            sink -= 0.025
        elif pos[i] in ("PRON", "CCONJ", "SCONJ", "PART"):
            sink -= 0.055
        elif pos[i] == "PUNCT":
            sink -= 0.075

        sink = float(np.clip(sink, 0.45, 0.99))
        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 4.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()
        attention[i, 0] = sink

    return "first_token_sink", attention


def prog_L4H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with weak adjectival links and no strong pronominal auxiliary link.
    Correct only those local-link patterns, preserving their residual and self weights.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_gated_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            if k < len(doc):
                inverse[k].append(i)

    sink_by_pos = {
        "PRON": 0.87, "DET": 0.79, "VERB": 0.80, "AUX": 0.82,
        "PROPN": 0.72, "NOUN": 0.61, "ADJ": 0.69, "ADV": 0.73,
        "ADP": 0.66, "PART": 0.65, "CCONJ": 0.71, "SCONJ": 0.75,
        "PUNCT": 0.69, "SPACE": 0.85, "NUM": 0.65,
    }

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = doc[alignment[i][-1]] if alignment[i] else None
        pos = word.pos_ if word is not None else ""
        sink = sink_by_pos.get(pos, 0.73)

        if i == 1:
            sink = 0.955
            if pos in ("DET", "ADP", "ADJ"):
                sink = 0.90
            elif pos in ("VERB", "AUX", "PUNCT"):
                sink = 0.982
        elif i == 2:
            sink = min(0.92, sink + 0.07)

        if tokens[i].isspace() or not tokens[i].lstrip("ĠĊ").strip():
            sink = 0.85

        local_target = None
        local_mass = 0.0

        if word is not None:
            if pos in ("NOUN", "PROPN"):
                for modifier in word.children:
                    if modifier.dep_ == "amod":
                        candidates = [
                            j for j in inverse[modifier.i]
                            if 0 < j < i and i - j <= 5
                        ]
                        if candidates:
                            target = candidates[-1]
                            if local_target is None or target > local_target:
                                local_target = target
                                local_mass = 0.67

                if pos == "PROPN" and word.dep_ in (
                    "appos", "compound", "flat", "nmod"
                ):
                    candidates = [
                        j for j in inverse[word.head.i]
                        if 0 < j < i and i - j <= 3
                    ]
                    if candidates:
                        local_target = candidates[-1]
                        local_mass = 0.82

            if pos == "AUX":
                for subject in word.head.children:
                    if subject.dep_ in ("nsubj", "nsubjpass", "csubj"):
                        candidates = [
                            j for j in inverse[subject.i] if 0 < j < i
                        ]
                        if (
                            candidates
                            and subject.left_edge.i > 0
                            and i - candidates[-1] <= 3
                        ):
                            local_target = candidates[-1]
                            local_mass = 0.80

            if pos == "ADP" and alignment[i - 1]:
                previous = doc[alignment[i - 1][-1]]
                if previous.pos_ == "ADV":
                    local_target = i - 1
                    local_mass = 0.77

        distances = i - np.arange(1, i + 1)
        residual = np.exp(-distances / 4.0)
        residual[-1] *= 0.45
        residual /= residual.sum()

        if local_target is not None:
            sink = min(sink, 1.0 - local_mass - 0.06)
            remaining = 1.0 - sink - local_mass
            attention[i, 1:i + 1] = remaining * residual
            attention[i, local_target] += local_mass
        else:
            attention[i, 1:i + 1] = (1.0 - sink) * residual

        attention[i, 0] = sink

        # Transfer only explicit local-link mass; leave the residual untouched.
        if (
            pos == "AUX"
            and local_mass == 0.80
            and alignment[local_target]
            and doc[alignment[local_target][-1]].pos_ == "PRON"
        ):
            attention[i, local_target] -= 0.68
            attention[i, 0] += 0.68

        elif pos in ("NOUN", "PROPN") and local_mass == 0.67:
            attention[i, local_target] -= 0.49
            attention[i, 0] += 0.49
            determiner_targets = [
                j
                for child in word.children
                if child.dep_ == "det"
                for j in inverse[child.i]
                if 0 < j < local_target and i - j <= 5
            ]
            if determiner_targets:
                attention[i, 0] -= 0.20
                attention[i, max(determiner_targets)] += 0.20

    return "first_token_sink_with_gated_local_syntax", make_row_stochastic(attention)


def prog_L4H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with local residual; sentence-ending punctuation
    redirects some sink mass toward earlier clause anchors, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_boundary_release", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.50 + 0.47 * np.exp(-(i - 1) / 3.2)

        if i >= 2 and alignment[i]:
            # Prefer actual lexical overlap over a whitespace-only overlap.
            words = [doc[k] for k in alignment[i] if not doc[k].is_space]
            if words:
                word = words[-1]
                if word.pos_ in ("PRON", "AUX"):
                    sink += 0.055
                elif word.pos_ == "VERB":
                    sink += 0.025
                elif word.pos_ in ("CCONJ", "SCONJ"):
                    sink -= 0.045
                elif word.pos_ == "PUNCT":
                    sink -= 0.055
                elif word.pos_ == "ADJ":
                    sink -= 0.015

        sink = np.clip(sink, 0.35, 0.985)
        attention[i, 0] = sink

        # Spread the non-sink mass across causal context, favoring recency.
        positions = np.arange(1, i + 1)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 5.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Boundary-only correction: leave all ordinary rows and diagonals intact.
        if i >= 4 and any(
            doc[k].is_punct and any(c in ".!?" for c in doc[k].text)
            for k in alignment[i]
        ):
            weights = np.ones(i - 1, dtype=np.float64)
            for j in range(1, i):
                words = [doc[k] for k in alignment[j] if not doc[k].is_space]
                if words:
                    word = words[-1]
                    if word.is_punct:
                        weights[j - 1] = 0.25
                    elif word.dep_ == "mark":
                        weights[j - 1] = 3.0
                    elif word.pos_ in ("VERB", "AUX"):
                        weights[j - 1] = 2.0

            released = 0.45 * attention[i, 0]
            attention[i, 0] -= released
            attention[i, 1:i] += released * weights / weights.sum()

    return "first_token_sink_with_boundary_release", attention


def prog_L4H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Self-attention with an initial-token sink; locally linked tokens redirect
    some sink mass to the preceding token, especially within split words.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "self_with_local_link_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    has_quotes = any(c in sentence for c in "\"“”")
    first_pos = doc[0].pos_ if len(doc) else ""

    attention[0, 0] = 1.0
    for i in range(1, n):
        aligned = alignment[i]
        word = None
        for k in aligned:
            if k < len(doc):
                candidate = doc[k]
                if word is None or (word.is_space and not candidate.is_space):
                    word = candidate

        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")

        self_mass = 0.48
        if pos in ("NOUN", "PROPN"):
            self_mass = 0.56
        elif pos == "VERB":
            self_mass = 0.59
        elif pos in ("ADJ", "AUX"):
            self_mass = 0.54
        elif pos in ("ADP", "DET", "PART", "PRON"):
            self_mass = 0.43
        elif pos == "PUNCT":
            self_mass = 0.54

        if dep in ("ROOT", "conj", "advcl", "ccomp"):
            self_mass += 0.035
        if has_quotes:
            self_mass += 0.035
        if any(c in clean for c in "\"“”"):
            self_mass += 0.09
        if clean.isspace():
            self_mass = 0.71

        # The first-token preference fades quickly over the opening tokens.
        if i == 1:
            self_mass = 0.14 if first_pos == "DET" else 0.045
        elif i == 2:
            self_mass *= 0.64
            if pos in ("NOUN", "PROPN", "VERB"):
                self_mass += 0.10
        elif i == 3:
            self_mass *= 0.90

        self_mass = float(np.clip(self_mass, 0.02, 0.82))
        attention[i, i] = self_mass

        remainder = 1.0 - self_mass
        if i == 1:
            attention[i, 0] = remainder
        else:
            attention[i, 0] = 0.92 * remainder
            previous = np.arange(1, i)
            weights = np.exp(-(i - previous) / 2.5)
            attention[i, 1:i] = 0.08 * remainder * weights / weights.sum()

        # Preserve the diagonal and original decay; only redirect sink mass
        # when the preceding token forms a local linguistic connection.
        if i >= 3 and word is not None and not word.is_space:
            previous_word = None
            for k in alignment[i - 1]:
                if 0 <= k < len(doc) and not doc[k].is_space:
                    previous_word = doc[k]

            if previous_word is not None:
                same_word = word.i == previous_word.i
                linked = (
                    word.head.i == previous_word.i
                    or previous_word.head.i == word.i
                )
                boundary = (
                    abs(word.i - previous_word.i) == 1
                    and (
                        pos in ("ADP", "DET", "PRON", "SCONJ", "CCONJ", "PUNCT")
                        or previous_word.pos_ in ("ADP", "AUX", "SCONJ", "CCONJ", "PUNCT")
                    )
                )
                if same_word or linked or boundary:
                    transfer = min(
                        0.24 if same_word else 0.20,
                        attention[i, 0] * (0.55 if same_word else 0.48),
                    )
                    attention[i, 0] -= transfer
                    attention[i, i - 1] += transfer

    return "self_with_local_link_sink", make_row_stochastic(attention)


def prog_L4H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with mild positional decay.
    Punctuation, especially closing quotes, diverts attention to local boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_boundaries", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    quote_stack = []
    quote_chars = {'"', "'", "“", "”", "‘", "’", "«", "»"}
    opening_quotes = {"“", "‘", "«"}
    closing_quotes = {"”", "’", "»"}
    boundary_positions = []

    for i, raw in enumerate(tokens):
        text = raw.replace("Ġ", " ").replace("Ċ", "\n").strip()
        words = [doc[k] for k in aligned[i] if k < len(doc)]
        word = words[-1] if words else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        is_punct = bool(text) and (
            all(not c.isalnum() for c in text)
            or (word is not None and word.is_punct)
        )
        # Apostrophes inside contractions are not quotation boundaries.
        is_quote = (
            any(c in quote_chars for c in text)
            and is_punct
            and (word is None or word.pos_ != "PART")
        )
        quote_target = None
        if is_quote:
            explicitly_open = any(c in opening_quotes for c in text)
            explicitly_close = any(c in closing_quotes for c in text)
            if quote_stack and (explicitly_close or not explicitly_open):
                quote_target = quote_stack.pop()
            else:
                quote_stack.append(i)

        if i == 0:
            attention[0, 0] = 1.0
        else:
            sink = 0.94 - 0.0035 * min(i, 70)
            if i == 1:
                sink = 0.982
            elif i == 2:
                sink = 0.935

            if pos in {"ADP", "AUX", "DET", "PRON"}:
                sink += 0.035
            elif pos in {"VERB", "ADV"}:
                sink -= 0.055
            if dep in {"pobj", "dobj", "attr"}:
                sink -= 0.025
            if is_punct:
                sink -= 0.10
            if not text:
                sink -= 0.17
            if quote_target is not None:
                sink = 0.28
            elif any(c in ".!?" for c in text) and is_punct:
                sink -= 0.24

            sink = float(np.clip(sink, 0.30 if quote_target is None else 0.20, 0.995))
            attention[i, 0] = sink

            positions = np.arange(1, i + 1)
            residual = np.exp(-(i - positions) / 5.0)
            residual[-1] *= 0.45
            if boundary_positions:
                boundary = boundary_positions[-1]
                if boundary > 0:
                    residual[boundary - 1] += 0.75
            if quote_target is not None and quote_target > 0:
                residual *= 0.08
                residual[quote_target - 1] += 3.0

            attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        if is_punct and not is_quote:
            boundary_positions.append(i)

    return "first_token_sink_with_boundaries", attention


def prog_L4H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with short-range syntactic competition.
    Local subjects, auxiliaries, and governing predicates can override the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_syntactic_competition", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        indices = aligned[i]
        word = doc[indices[-1]] if indices else None

        # The sink stays substantial even far from the beginning.
        sink = 0.43 + 0.54 * np.exp(-0.35 * (i - 1))
        local = np.exp(-(i - np.arange(i + 1)) / 4.0)
        local[0] = 0.0
        local[i] *= 0.18
        local[i - 1] *= 1.4
        if i >= 2:
            local[i - 2] *= 1.6

        candidates = {}

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            # Early subject phrases and their first predicates favor the sink.
            if i <= 5 and (
                dep in ("nsubj", "nsubjpass", "ROOT")
                or pos in ("PROPN", "AUX")
            ):
                sink += 0.09

            if dep in ("nsubj", "nsubjpass") and i > 5:
                sink += 0.16
            elif pos == "PROPN":
                sink += 0.12

            if pos in ("DET", "SPACE"):
                sink += 0.04
            if word.is_punct:
                sink -= 0.07

            # A preceding syntactic governor is a secondary local anchor.
            head = word.head
            if head.i != word.i:
                preceding = [
                    j for j in inverse[head.i] if 0 < j < i
                ]
                if preceding:
                    j = preceding[-1]
                    distance = i - j
                    if distance <= 10:
                        strength = 1.7
                        if pos in ("ADV", "ADJ", "ADP", "PUNCT"):
                            strength = 2.8
                        if dep in ("xcomp", "ccomp", "prt", "acomp", "attr"):
                            strength = 5.5
                        candidates[j] = max(
                            candidates.get(j, 0.0),
                            strength * np.exp(-max(distance - 3, 0) / 6.0),
                        )

            # Verbal queries often select a recent subject or auxiliary.
            if pos in ("VERB", "AUX"):
                for child in word.children:
                    if child.dep_ not in (
                        "nsubj", "nsubjpass", "aux", "auxpass", "cop"
                    ):
                        continue
                    preceding = [
                        j for j in inverse[child.i] if 0 < j < i
                    ]
                    if preceding:
                        j = preceding[-1]
                        if i - j <= 6:
                            strength = (
                                7.5
                                if child.dep_ in ("nsubj", "nsubjpass")
                                else 5.0
                            )
                            candidates[j] = max(
                                candidates.get(j, 0.0), strength
                            )

            # Punctuation after a content word often closes that local phrase.
            if word.is_punct and i > 1 and aligned[i - 1]:
                previous = doc[aligned[i - 1][-1]]
                if previous.pos_ in ("NOUN", "VERB", "ADJ", "ADV"):
                    candidates[i - 1] = max(
                        candidates.get(i - 1, 0.0), 3.5
                    )

        if candidates:
            strongest = max(candidates.values())
            sink -= min(0.23, 0.025 * strongest)
            for j, strength in candidates.items():
                local[j] += strength

        # Subword continuations retain the global sink rather than merely
        # copying the preceding piece.
        if i > 1 and aligned[i] and aligned[i - 1]:
            if aligned[i][-1] == aligned[i - 1][-1]:
                sink += 0.10
                local[i - 1] *= 0.65

        sink = float(np.clip(sink, 0.18, 0.985))
        attention[i, 0] = sink
        attention[i, :i + 1] += (1.0 - sink) * local / local.sum()

    return (
        "first_token_sink_with_syntactic_competition",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L4H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with gradual positional weakening.
    Punctuation weakens the sink; residual attention is diffuse and mildly local.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.59 + 0.40 * np.exp(-i / 38.0)
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[-1]]
            if word.pos_ == "PUNCT":
                sink_mass -= 0.065
            elif word.pos_ in ("ADJ", "ADV"):
                sink_mass += 0.020
            elif word.pos_ in ("PRON", "AUX"):
                sink_mass += 0.012

        if any(c in tokens[i] for c in ('"', "'", "“", "”", "‘", "’")):
            sink_mass -= 0.045

        sink_mass = float(np.clip(sink_mass, 0.50, 0.997))
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.6 + 0.4 * np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_decay", attention


def prog_L4H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous-token attention: each position copies its immediate predecessor,
    with the first position attending to itself."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention_matrix = np.zeros((n, n), dtype=np.float64)
    if n > 0:
        attention_matrix[0, 0] = 1.0
        for i in range(1, n):
            attention_matrix[i, i - 1] = 1.0
    return "previous_token", attention_matrix


def prog_L5H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with weak, recency-weighted causal leakage.
    Sink strength decreases modestly with distance from the sequence start.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.97 - 0.07 * (1.0 - np.exp(-i / 32.0))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        background = np.exp(-distances / 6.0)
        background /= background.sum()
        background = 0.75 * background + 0.25 / i
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "first_token_sink", attention


def prog_L5H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink: every position attends to the initial token."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n:
        attention[:, 0] = 1.0
    return "first_token_sink", attention


def prog_L5H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with a secondary anchor at an opening noun phrase's
    determiner or adjective; otherwise retain the original local structure."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_opening_phrase_anchor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    # An opening modified nominal or fronted PP can supply a second sink.
    anchor = None
    nominal_opening = False
    if len(doc) >= 3:
        nominal_opening = (
            doc[0].pos_ == "DET"
            and doc[1].pos_ == "ADJ"
            and doc[1].dep_ == "amod"
        )
        fronted_opening = (
            doc[0].pos_ in ("ADP", "ADV")
            and doc[1].pos_ == "DET"
            and doc[1].dep_ == "det"
            and doc[1].head.pos_ in ("NOUN", "PROPN")
        )
        if nominal_opening or fronted_opening:
            keys = [j for j in inverse[1] if j > 0]
            if keys:
                anchor = min(keys)

    attention[0, 0] = 1.0

    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        sink_mass = 0.79
        local = np.zeros(i + 1, dtype=np.float64)

        # A diffuse causal background, with a preference for nearby keys.
        distances = i - np.arange(i + 1)
        local[:] = 0.06 * np.exp(-distances / 7.0)
        local[i] += 0.10
        local[i - 1] += 0.65

        if word is not None:
            if word.pos_ in ("PROPN", "PRON"):
                sink_mass = 0.84
            elif word.pos_ in ("NOUN", "VERB"):
                sink_mass = 0.80
            elif word.pos_ in ("ADJ", "ADV"):
                sink_mass = 0.73
            elif word.pos_ in ("AUX", "CCONJ", "SCONJ"):
                sink_mass = 0.66
            elif word.pos_ == "PUNCT":
                sink_mass = 0.54

            # Some nominal complements attend to their introducing preposition.
            if word.dep_ in ("pobj", "obl", "nmod"):
                head = word.head
                candidates = []
                if head.pos_ == "ADP":
                    candidates.extend(inverse[head.i])
                for child in word.children:
                    if child.dep_ == "case" and child.pos_ == "ADP":
                        candidates.extend(inverse[child.i])
                candidates = [j for j in candidates if 0 < j < i]
                if candidates:
                    sink_mass = 0.46
                    local[max(candidates)] += 3.0

            # Finite auxiliaries occasionally retain the immediately preceding subject.
            if word.pos_ in ("AUX", "VERB"):
                subjects = [
                    child for child in word.children
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj")
                ]
                for subject in subjects:
                    keys = [j for j in inverse[subject.i] if 0 < j < i]
                    if keys and i - max(keys) <= 2:
                        sink_mass = min(sink_mass, 0.52)
                        local[max(keys)] += 2.0

            # Continuation pieces can attend to an earlier piece of the same word.
            earlier_pieces = [j for j in inverse[word.i] if 0 < j < i]
            if earlier_pieces:
                local[max(earlier_pieces)] += 1.2
                if word.pos_ == "ADV":
                    sink_mass = 0.24
                    local[max(earlier_pieces)] += 4.0

        # The second token almost invariably selects the initial token.
        if i == 1:
            sink_mass = 0.94

        local[0] = 0.0
        local /= local.sum()
        attention[i, :i + 1] = (1.0 - sink_mass) * local
        attention[i, 0] = sink_mass

        # Redirect only off-diagonal mass in the opening-phrase special case.
        # All other rows, including their self-attention, remain unchanged.
        if anchor is not None and i > anchor:
            redirected = 0.0
            if word is not None and word.pos_ in ("AUX", "VERB"):
                for subject in word.children:
                    if subject.dep_ not in ("nsubj", "nsubjpass", "csubj"):
                        continue
                    keys = [j for j in inverse[subject.i] if anchor < j < i]
                    if keys and i - max(keys) <= 2:
                        key = max(keys)
                        mass = 0.75 * attention[i, key]
                        attention[i, key] -= mass
                        redirected += mass

            transfer = 0.42 * np.exp(-max(0, i - anchor - 1) / 6.0)
            if nominal_opening and redirected > 0.0:
                transfer *= 0.25
            transfer = min(transfer, max(0.0, attention[i, 0] - 0.15))
            attention[i, 0] -= transfer
            attention[i, anchor] += transfer + redirected

    return "first_token_sink_with_opening_phrase_anchor", attention


def prog_L5H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with clause anchors; infinitival chains retain their
    outer marker and finite-clause subject rather than the nearest predicate.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_infinitive_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_to_tokens = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            word_to_tokens[wi].append(ti)

    representatives = []
    for word_ids in alignment:
        candidates = [doc[wi] for wi in word_ids if not doc[wi].is_space]
        nonpunct = [w for w in candidates if not w.is_punct]
        representatives.append(
            nonpunct[0] if nonpunct else (candidates[0] if candidates else None)
        )

    quote_anchor = None
    quote_marks = {'"', "“", "”", "«", "»"}
    clause_deps = {"ROOT", "ccomp", "xcomp", "advcl", "relcl", "conj"}

    for i in range(n):
        if i == 0:
            attention[0, 0] = 1.0
            continue

        word = representatives[i]
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()

        sink = 0.27 + 0.68 * np.exp(-(i - 1) / 3.8)

        if word is not None:
            first_piece = bool(word_to_tokens[word.i]) and (
                word_to_tokens[word.i][0] == i
            )
            if first_piece and word.is_sent_start:
                sink = max(sink, 0.73)
            elif first_piece and word.pos_ == "PRON":
                sink += 0.10
            elif word.pos_ == "DET":
                sink += 0.04

            if word.dep_ in {"dobj", "obj", "attr", "acomp", "xcomp"}:
                sink -= 0.07

        if not clean:
            sink = max(sink, 0.56)
        if any(mark in clean for mark in {"?", "!"}):
            sink += 0.12

        distances = i - np.arange(i + 1)
        residual = (
            0.025
            + 0.42 * np.exp(-distances / 2.3)
            + 0.10 * np.exp(-distances / 12.0)
        )
        residual[0] = 0.0

        if word is not None:
            ancestor = word
            visited = set()
            while ancestor.i not in visited:
                visited.add(ancestor.i)
                if (
                    ancestor.pos_ in {"VERB", "AUX"}
                    and ancestor.dep_ in clause_deps
                ):
                    positions = word_to_tokens[ancestor.i]
                    earlier = [j for j in positions if 0 < j < i]
                    if earlier:
                        anchor = earlier[0]
                        strength = 0.85
                        if ancestor.dep_ in {"ROOT", "ccomp", "xcomp"}:
                            strength = 1.30
                        residual[anchor] += strength
                        break
                if ancestor.head.i == ancestor.i:
                    break
                ancestor = ancestor.head

        if quote_anchor is not None:
            distance = i - quote_anchor
            if distance > 0:
                strength = 2.2 * np.exp(-(distance - 1) / 4.0)
                residual[quote_anchor] += strength
                sink -= 0.16 * np.exp(-(distance - 1) / 5.0)

        sink = float(np.clip(sink, 0.14, 0.97))
        attention[i, 0] = sink
        residual_sum = residual.sum()
        if residual_sum > 0:
            attention[i, :i + 1] += (1.0 - sink) * residual / residual_sum
        else:
            attention[i, i] += 1.0 - sink

        # Only marked infinitival complements activate this redistribution.
        # Transfer existing off-diagonal mass; leave self-attention untouched.
        if word is not None:
            chain = [word] + list(word.ancestors)
            marked = []
            for predicate in chain:
                if predicate.pos_ == "VERB" and predicate.dep_ == "xcomp":
                    for child in predicate.children:
                        if child.pos_ == "PART" and child.dep_ in {"aux", "mark"}:
                            positions = word_to_tokens[child.i]
                            if positions and 0 < positions[0] < i:
                                marked.append((predicate, positions[0]))

            if marked:
                outer, marker = marked[-1]
                governor = outer.head
                targets = {marker: 0.60}
                positions = word_to_tokens[governor.i]
                if positions and 0 < positions[0] < i:
                    targets[positions[0]] = targets.get(positions[0], 0.0) + 0.40

                for child in governor.children:
                    if child.dep_ in {"nsubj", "nsubjpass", "csubj"}:
                        positions = word_to_tokens[child.i]
                        if positions and 0 < positions[0] < i:
                            targets[positions[0]] = (
                                targets.get(positions[0], 0.0) + 1.20
                            )

                sources = {0}
                for predicate in chain:
                    if predicate.pos_ == "VERB" and predicate.dep_ == "xcomp":
                        sources.update(
                            j for j in word_to_tokens[predicate.i] if 0 < j < i
                        )
                sources.difference_update(targets)

                moved = 0.0
                for j in sources:
                    fraction = 0.45 if j == 0 else 0.70
                    amount = fraction * attention[i, j]
                    attention[i, j] -= amount
                    moved += amount
                total = sum(targets.values())
                for j, weight in targets.items():
                    attention[i, j] += moved * weight / total

        for character in clean:
            if character in quote_marks:
                if character in {"”", "»"}:
                    quote_anchor = None
                elif character in {"“", "«"}:
                    quote_anchor = i
                else:
                    quote_anchor = i if quote_anchor is None else None

    return (
        "first_token_sink_with_infinitive_anchors",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L5H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with argument anchors; terminal punctuation summarizes
    the most recent predicate phrase rather than a distant syntactic root.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_local_phrase_endings", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            inverse[si].append(ti)

    attention[0, 0] = 1.0
    argument_deps = (
        "dobj", "obj", "iobj", "dative", "pobj", "attr", "oprd"
    )
    modifier_deps = (
        "det", "poss", "amod", "compound", "nummod", "quantmod"
    )

    for i in range(1, n):
        indices = alignment[i]
        word = None
        for si in indices:
            if not doc[si].is_space:
                word = doc[si]
                break

        sink = 0.54
        anchors = {}

        if word is not None:
            pos = word.pos_
            dep = word.dep_

            if pos == "AUX":
                sink = 0.86
            elif pos == "VERB":
                sink = 0.65
                if dep in ("xcomp", "ccomp"):
                    sink = 0.81
                elif dep == "conj":
                    sink = 0.57
            elif pos == "PART":
                sink = 0.82
            elif pos == "ADJ":
                sink = 0.61
            elif pos == "PRON":
                sink = 0.64
            elif pos == "ADP":
                sink = 0.55
            elif pos == "PUNCT":
                sink = 0.49

            # Follow modifiers to their argument's introducing governor.
            node = word
            for _ in range(5):
                if node.dep_ in modifier_deps and node.head.i != node.i:
                    node = node.head
                else:
                    break

            if node.dep_ in argument_deps:
                governor = node.head
                if governor.pos_ in ("VERB", "ADP"):
                    candidates = [
                        j for j in inverse[governor.i] if 0 < j < i
                    ]
                    if candidates:
                        anchor = candidates[0]
                        anchors[anchor] = 1.0
                        sink = 0.34 if pos == "PRON" else 0.43

            # Punctuation following an argument often retains its predicate.
            if word.is_punct and word.head.pos_ == "VERB":
                candidates = [
                    j for j in inverse[word.head.i] if 0 < j < i
                ]
                if candidates:
                    anchors[candidates[0]] = 1.0
                    sink = 0.47

        elif tokens[i].strip("\u0120\u010a \t\r\n") == "":
            sink = 0.80

        onset = 0.48 + 0.50 * np.exp(-((i - 1) / 3.0) ** 1.35)
        sink = float(np.clip(max(sink, onset), 0.0, 0.985))

        distances = i - np.arange(1, i + 1)
        background = np.exp(-distances / 4.0)
        background /= background.sum()

        residual = 1.0 - sink
        anchor_fraction = 0.88 if anchors else 0.0
        attention[i, 1:i + 1] = (
            residual * (1.0 - anchor_fraction) * background
        )
        if anchors:
            total = sum(anchors.values())
            for j, weight in anchors.items():
                attention[i, j] += residual * anchor_fraction * weight / total
        attention[i, 0] = sink

        # Only terminal punctuation is patched. Keep its diagonal and the
        # original background intact, moving mass from stale anchors and sink.
        if (
            word is not None
            and word.is_punct
            and word.i == len(doc) - 1
            and i == n - 1
        ):
            predicate = None
            for si in range(word.i - 1, -1, -1):
                if doc[si].pos_ in ("VERB", "AUX"):
                    candidates = [j for j in inverse[si] if 0 < j < i]
                    if candidates:
                        predicate = candidates[0]
                        break

            if predicate is not None:
                tail = [
                    j for j in range(predicate + 1, i)
                    if any(
                        not doc[si].is_punct and not doc[si].is_space
                        for si in alignment[j]
                    )
                ][-3:]

                if tail:
                    moved = min(0.12, attention[i, 0])
                    attention[i, 0] -= moved

                    if anchors:
                        total = sum(anchors.values())
                        for j, weight in anchors.items():
                            if j < predicate:
                                amount = (
                                    residual * anchor_fraction * weight / total
                                )
                                attention[i, j] -= amount
                                moved += amount

                    attention[i, predicate] += 0.40 * moved
                    tail_weights = np.exp(
                        (np.asarray(tail, dtype=np.float64) - tail[-1]) / 3.0
                    )
                    tail_weights /= tail_weights.sum()
                    for j, weight in zip(tail, tail_weights):
                        attention[i, j] += 0.60 * moved * weight

    return (
        "first_token_sink_with_local_phrase_endings",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L5H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with successor induction, strengthened for repeated
    linguistic cues in dialogue while preserving the original self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_dialogue_induction", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    content_pos = {"NOUN", "PROPN", "VERB", "ADJ"}
    representatives = {}
    token_words = [None] * n

    for i, aligned in enumerate(alignment):
        if aligned:
            word = doc[aligned[0]]
            token_words[i] = word
            if word.i not in representatives:
                representatives[word.i] = i

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = max(0.90, 0.995 - 0.0018 * i)
        word = token_words[i]
        if word is not None and word.is_punct:
            sink_mass = max(0.88, sink_mass - 0.025)

        # Small causal background, concentrated toward nearby tokens.
        positions = np.arange(1, i + 1)
        background = np.exp((positions - i) / 5.0)
        background /= background.sum()
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

        if (
            word is None
            or word.pos_ not in content_pos
            or representatives.get(word.i) != i
        ):
            continue

        best_strength = 0.0
        best_target = None

        for j in range(1, i - 1):
            earlier = token_words[j]
            if (
                earlier is None
                or earlier.pos_ != word.pos_
                or representatives.get(earlier.i) != j
            ):
                continue

            # Skip the remaining pieces of the earlier word.
            target = j + 1
            while (
                target < i
                and token_words[target] is not None
                and token_words[target].i == earlier.i
            ):
                target += 1
            if target >= i:
                continue

            similarity = embedding_similarity(tokens, i, j, tokenizer)
            threshold = 0.65 if word.pos_ == "VERB" else 0.80
            if similarity <= threshold:
                continue

            strength = min(
                0.88,
                0.88 * (similarity - threshold) / (1.0 - threshold)
            )
            if strength > best_strength:
                best_strength = strength
                best_target = target

        if best_target is not None:
            attention[i] *= 1.0 - best_strength
            attention[i, best_target] += best_strength

    # Dialogue exposes induction on function words and whitespace as well as
    # content words. Include position zero as a cue, but never as its successor.
    if sum(sentence.count(mark) for mark in ('"', "“", "”")) >= 2:
        cue_pos = content_pos | {"DET", "PRON", "AUX", "ADP", "ADV"}
        for i in range(1, n):
            word = token_words[i]
            whitespace = bool(tokens[i]) and not tokens[i].strip("ĠĊĉ \t\r\n")
            if not whitespace and (
                word is None
                or word.pos_ not in cue_pos
                or representatives.get(word.i) != i
            ):
                continue

            best_strength = 0.0
            best_target = None
            for j in range(i - 1):
                earlier = token_words[j]
                if whitespace:
                    if not tokens[j] or tokens[j].strip("ĠĊĉ \t\r\n"):
                        continue
                    similarity = 1.0
                    threshold, ceiling = 0.95, 0.80
                    target = j + 1
                else:
                    if (
                        earlier is None
                        or earlier.pos_ != word.pos_
                        or representatives.get(earlier.i) != j
                    ):
                        continue
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    threshold = 0.72 if word.pos_ == "VERB" else 0.90
                    ceiling = 0.86 if word.pos_ in content_pos else 0.70
                    if word.pos_ == "DET":
                        ceiling = 0.35
                    target = j + 1
                    while (
                        target < i
                        and token_words[target] is not None
                        and token_words[target].i == earlier.i
                    ):
                        target += 1

                if target >= i or similarity <= threshold:
                    continue
                strength = ceiling * min(
                    1.0, (similarity - threshold) / (1.0 - threshold)
                )
                if strength >= best_strength:
                    best_strength = strength
                    best_target = target

            if best_target is not None:
                # Transfer only sink mass: self-attention and all unrelated
                # edges remain exactly as computed by the original path.
                transfer = min(
                    attention[i, 0],
                    max(0.0, best_strength - attention[i, best_target])
                )
                attention[i, 0] -= transfer
                attention[i, best_target] += transfer

    return "first_token_sink_with_dialogue_induction", make_row_stochastic(attention)


def prog_L5H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with selective attention to locally linked predecessors.
    Syntactic continuations and byte fragments borrow mass only from the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_linked_predecessor", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        positions = {word.pos_ for word in words}

        sink_mass = 0.85
        if positions.intersection({"VERB", "AUX", "PRON", "ADP"}):
            sink_mass += 0.025
        if any(word.dep_ == "ROOT" for word in words):
            sink_mass += 0.02

        clean = tokens[i].replace("\u0120", " ").replace("\u010a", "\n").strip()
        punctuation = (
            bool(words) and all(word.is_punct for word in words)
        ) or (
            bool(clean) and all(character in ".,!?;:—–-()[]{}\"'…" for character in clean)
        )
        if punctuation:
            sink_mass = 0.92
            if any(character in ".!?" for character in clean):
                sink_mass = 0.94

        if i == 1:
            sink_mass = 0.975

        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = np.exp(-distances / 3.0)
        residual[-1] *= 0.65
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual / residual.sum()

        # Transfer sink mass only; preserve self-attention and the local tail.
        if i > 1:
            previous = [doc[k] for k in alignment[i - 1]]
            previous_positions = {word.pos_ for word in previous}
            target, transfer = i - 1, 0.0
            linked = any(
                a.i != b.i and (a.head.i == b.i or b.head.i == a.i)
                for a in words for b in previous
            )

            if clean in {",", ";", ":"} and previous_positions.intersection(
                {"NOUN", "PROPN", "VERB", "ADJ", "INTJ"}
            ):
                transfer = 0.28
            elif linked:
                transfer = 0.10
                if positions.intersection({"VERB", "ADJ"}) and "AUX" in previous_positions:
                    transfer = 0.22
                if "PART" in positions and "VERB" in previous_positions:
                    transfer = 0.32
                if "VERB" in positions and "PART" in previous_positions:
                    transfer = 0.30
                if "DET" in positions and "ADP" in previous_positions:
                    transfer = 0.28
                if "ADP" in positions and previous_positions.intersection({"NOUN", "VERB"}):
                    transfer = 0.22
                if "ADV" in positions and "CCONJ" in previous_positions:
                    transfer = 0.32

            # A short intervening auxiliary/determiner can leave the earlier
            # subject or preposition as the salient continuation target.
            if i > 2:
                earlier = [doc[k] for k in alignment[i - 2]]
                if (
                    "VERB" in positions and "AUX" in previous_positions
                    and any(
                        b.dep_ in {"nsubj", "nsubjpass"} and b.head.i == a.i
                        for a in words for b in earlier
                    )
                ):
                    target, transfer = i - 2, 0.38
                elif (
                    positions.intersection({"NOUN", "PROPN"})
                    and "DET" in previous_positions
                    and any(
                        b.pos_ == "ADP" and a.head.i == b.i
                        for a in words for b in earlier
                    )
                ):
                    target, transfer = i - 2, 0.22

            # Non-initial byte fragments often continue the preceding token.
            if (
                clean and not tokens[i].startswith(("\u0120", "\u010a"))
                and any(ord(character) > 127 for character in clean)
                and not any(character.isascii() and character.isalnum() for character in clean)
                and not punctuation
            ):
                target, transfer = i - 1, 0.70

            if transfer:
                transfer = min(transfer, attention[i, 0])
                attention[i, 0] -= transfer
                attention[i, target] += transfer

    return "first_token_sink_with_linked_predecessor", attention


def prog_L5H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with weaker local syntactic attachment.
    Early tokens favor the sink; nominal attachments can redirect attention locally.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None

        # A persistent sink, particularly strong near the beginning.
        early = np.exp(-(i - 1) / 3.5)
        sink = 0.77 + 0.20 * early
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "VERB", "AUX", "ADJ"):
                sink += 0.055 * (1.0 - early)
            elif word.pos_ in ("ADP", "DET", "PART", "SCONJ"):
                sink -= 0.12 * (1.0 - early)
            elif word.pos_ == "PUNCT":
                sink -= 0.07 * (1.0 - early)

        local = np.zeros(i + 1, dtype=np.float64)
        distances = i - np.arange(1, i + 1)
        local[1:] = np.exp(-distances / 3.0)
        local[i] *= 0.35

        if word is not None:
            head = word.head
            head_positions = [j for j in inverse[head.i] if 0 < j < i]
            if head_positions and head.i != word.i:
                target = head_positions[-1]
                local[target] += 2.0

                # Prepositions often look back to a nominal attachment site.
                if (
                    word.pos_ == "ADP"
                    and head.pos_ in ("NOUN", "PROPN")
                    and i - target <= 5
                ):
                    sink = min(sink, 0.26)
                    local[target] += 18.0

            # A determiner inside a prepositional phrase can inherit its anchor.
            if word.pos_ == "DET" and head.head.pos_ == "ADP":
                prep = head.head
                anchor = prep.head
                candidates = [j for j in inverse[anchor.i] if 0 < j < i]
                if not candidates:
                    candidates = [j for j in inverse[prep.i] if 0 < j < i]
                if candidates:
                    target = candidates[-1]
                    if i - target <= 5:
                        sink = min(sink, 0.42)
                        local[target] += 12.0

            # Continuation pieces retain a little within-word attention.
            previous_pieces = [j for j in inverse[word.i] if 0 < j < i]
            if previous_pieces:
                local[previous_pieces[-1]] += 1.5

        sink = float(np.clip(sink, 0.15, 0.985))
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (
            (1.0 - sink) * local[1:] / local[1:].sum()
        )

    return "first_token_sink_with_local_syntax", make_row_stochastic(attention)


def prog_L5H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with gradual dilution and weaker competing
    attention to later sentence onsets and nearby tokens."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_boundary_competition", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)

    sentence_starts = np.zeros(n, dtype=bool)
    punctuation = np.zeros(n, dtype=bool)
    whitespace = np.zeros(n, dtype=bool)

    for i, indices in enumerate(aligned):
        if indices:
            punctuation[i] = all(doc[k].is_punct for k in indices)
            whitespace[i] = all(doc[k].is_space for k in indices)
            sentence_starts[i] = any(
                doc[k].is_sent_start
                and (i == 0 or k not in aligned[i - 1])
                for k in indices
            )
        else:
            clean = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")
            whitespace[i] = not clean.strip()

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.985 - 0.205 * (1.0 - np.exp(-(i - 1) / 19.0))

        if punctuation[i]:
            sink_mass -= 0.12
        if sentence_starts[i]:
            sink_mass -= 0.17

        prior_starts = np.flatnonzero(sentence_starts[1:i + 1]) + 1
        if whitespace[i] and len(prior_starts):
            sink_mass -= 0.20

        sink_mass = float(np.clip(sink_mass, 0.40, 0.99))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        weights = 0.20 + np.exp(-(i - positions) / 5.0)
        weights += 1.5 * sentence_starts[1:i + 1]

        if len(prior_starts):
            latest_start = prior_starts[-1]
            weights[latest_start - 1] += 2.0
            if whitespace[i]:
                weights[latest_start - 1] += 8.0

        weights *= np.where(punctuation[1:i + 1], 0.65, 1.0)
        attention[i, 1:i + 1] = (1.0 - sink_mass) * weights / weights.sum()

    return "first_token_sink_with_boundary_competition", attention


def prog_L5H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with weak, recency-weighted causal leakage.
    Competing past tokens gradually reduce the sink's dominance in longer contexts.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        positions = np.arange(i + 1)
        attention[i, :i + 1] = np.exp(-(i - positions) / 64.0)
        attention[i, 0] = 110.0

    return "first_token_sink_with_weak_recency", make_row_stochastic(attention)


def prog_L5H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with weaker syntactic and recency attention.
    Sink strength declines with distance and on predicate-bearing tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    representatives = [
        max(indices, key=lambda k: len(doc[k].text)) if indices else None
        for indices in alignment
    ]
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            inverse[si].append(ti)

    first_si = representatives[0]
    initial_pos = doc[first_si].pos_ if first_si is not None else ""
    opening_subject = None
    for i in range(1, min(n, 7)):
        si = representatives[i]
        if si is None:
            continue
        word = doc[si]
        if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
            opening_subject = i
            break
        if word.pos_ in ("VERB", "AUX"):
            break

    attention[0, 0] = 1.0
    for i in range(1, n):
        si = representatives[i]
        word = doc[si] if si is not None else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.79 - 0.0035 * i + 0.16 * np.exp(-i / 5.0)
        if initial_pos in ("ADP", "SCONJ", "ADV"):
            sink += 0.055 * np.exp(-i / 15.0)

        if pos in ("DET", "ADP"):
            sink += 0.075
        elif pos in ("ADJ", "NUM"):
            sink += 0.025
        elif pos in ("VERB", "AUX"):
            sink -= 0.15
        elif pos in ("PRON", "CCONJ", "SCONJ"):
            sink -= 0.055
        elif pos in ("NOUN", "PROPN"):
            sink -= 0.045
        elif pos == "PUNCT":
            sink -= 0.085

        if i == 1:
            sink = 0.95 if pos != "AUX" else 0.68
        elif i <= 3 and initial_pos in ("ADP", "ADV", "NUM"):
            sink += 0.055

        if tokens[i].isspace() or tokens[i].strip("ĠĊ") == "":
            sink += 0.10

        subject_pull = (
            opening_subject is not None
            and opening_subject < i
            and initial_pos == "DET"
            and pos in ("AUX", "VERB", "ADJ")
        )
        if subject_pull:
            sink -= 0.15 * np.exp(-(i - opening_subject) / 8.0)

        sink = float(np.clip(sink, 0.30, 0.985))
        indices = np.arange(1, i + 1)
        remainder = 0.30 + np.exp(-(i - indices) / 8.0)

        if word is not None:
            for target in inverse[word.head.i]:
                if 0 < target <= i and target != i:
                    remainder[target - 1] += 2.0
            if dep in ("ROOT", "conj"):
                for child in word.children:
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj", "aux"):
                        for target in inverse[child.i]:
                            if 0 < target <= i:
                                remainder[target - 1] += 1.5

        if subject_pull:
            remainder[opening_subject - 1] += (
                5.0 * np.exp(-(i - opening_subject) / 10.0)
            )

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * remainder / remainder.sum()

    return "first_token_sink_with_syntax", attention


def prog_L5H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with mild distance decay and POS-dependent strength.
    Residual attention is diffuse and biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        positions = alignment[i]
        pos = ""
        if positions:
            # Ignore whitespace overlaps when selecting the linguistic token.
            candidates = [k for k in positions if not doc[k].is_space]
            if candidates:
                pos = doc[candidates[-1]].pos_

        sink = 0.91 - 0.035 * np.log1p(i)
        sink += 0.075 * np.exp(-i / 4.0)

        if pos in ("ADJ", "VERB", "PROPN"):
            sink += 0.035
        elif pos in ("NOUN", "ADV"):
            sink += 0.015
        elif pos in ("DET", "ADP", "CCONJ", "SCONJ"):
            sink -= 0.055
        elif pos == "PUNCT":
            sink -= 0.15

        sink = float(np.clip(sink, 0.52, 0.98))

        # Keep the sink separate from the small, otherwise nonspecific remainder.
        distances = i - np.arange(1, i + 1)
        residual = 0.65 * np.exp(-distances / 5.0) + 0.35
        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "first_token_sink", attention


def prog_L6H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with causal subject and governing-predicate anchors.
    Local syntactic structure competes with a strong sentence-initial positional prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_with_syntactic_anchors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            if k < len(doc):
                inverse[k].append(i)

    subject_deps = ("nsubj", "nsubjpass", "csubj", "csubjpass")
    predicate_pos = ("VERB", "AUX")
    nominal_pos = ("NOUN", "PROPN", "PRON")

    attention[0, 0] = 1.0
    for i in range(1, n):
        positions = np.arange(i + 1)
        local = np.exp(-(i - positions) / 4.0)
        local /= local.sum()

        sink = 0.47 + 0.49 * np.exp(-(i - 1) / 3.5)
        row = (1.0 - sink) * local
        row[0] += sink

        indices = alignment[i]
        if not indices:
            row *= 0.15
            row[0] += 0.85
            attention[i, :i + 1] = row
            continue

        word = doc[indices[-1]]
        anchors = {}
        strength = 0.0

        # Predicates attend to their overt, already-observed subjects.
        if word.pos_ in predicate_pos:
            predicates = [word]
            if word.dep_ in ("aux", "auxpass", "cop") and word.head != word:
                predicates.append(word.head)

            for predicate in predicates:
                for child in predicate.children:
                    if child.dep_ in subject_deps:
                        candidates = [j for j in inverse[child.i] if j < i]
                        if candidates:
                            j = candidates[-1]
                            anchors[j] = anchors.get(j, 0.0) + 2.5
                            strength = max(strength, 0.53)

            # Coordinated predicates commonly retain the earlier subject.
            if not anchors and word.dep_ == "conj":
                for child in word.head.children:
                    if child.dep_ in subject_deps:
                        candidates = [j for j in inverse[child.i] if j < i]
                        if candidates:
                            j = candidates[-1]
                            anchors[j] = anchors.get(j, 0.0) + 2.0
                            strength = max(strength, 0.48)

        # Objects, complements and modifiers can look back to a governor.
        if word.head != word:
            head = word.head
            candidates = [j for j in inverse[head.i] if j < i]
            if candidates:
                j = candidates[-1]
                if head.pos_ in predicate_pos:
                    weight = 0.38
                elif head.pos_ == "ADP":
                    weight = 0.36
                elif word.pos_ in predicate_pos and head.pos_ in nominal_pos:
                    weight = 0.48
                else:
                    weight = 0.20
                anchors[j] = anchors.get(j, 0.0) + 1.0
                strength = max(strength, weight)

            # A determiner's noun may lie ahead, while its predicate is causal.
            elif word.pos_ in ("DET", "ADJ"):
                governor = head.head
                candidates = [j for j in inverse[governor.i] if j < i]
                if candidates and governor.pos_ in predicate_pos:
                    j = candidates[-1]
                    anchors[j] = anchors.get(j, 0.0) + 0.8
                    strength = max(strength, 0.32)

        # Adjectival predicates also expose subjects through their copula.
        if word.pos_ == "ADJ":
            for child in word.children:
                if child.dep_ in subject_deps:
                    candidates = [j for j in inverse[child.i] if j < i]
                    if candidates:
                        j = candidates[-1]
                        anchors[j] = anchors.get(j, 0.0) + 2.0
                        strength = max(strength, 0.48)

        if anchors:
            total = sum(anchors.values())
            row *= 1.0 - strength
            for j, weight in anchors.items():
                row[j] += strength * weight / total

        # Subjects and discourse-boundary material retain the sink preference.
        if word.dep_ in subject_deps:
            row *= 0.65
            row[0] += 0.35
        elif word.is_space:
            row *= 0.15
            row[0] += 0.85
        elif word.is_punct:
            row *= 0.82
            row[0] += 0.18

        attention[i, :i + 1] = row

    return "first_token_with_syntactic_anchors", make_row_stochastic(attention)


def prog_L6H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with selective retrieval of coordination spans and fronted predicates.
    Special cases move sink mass to earlier anchors without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_coordination_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for index in indices:
            inverse[index].append(i)

    # Collect coordination groups; ordinary, uncoordinated spans are unaffected.
    groups = {}
    for word in doc:
        if word.dep_ == "conj":
            root = word.head
            while root.dep_ == "conj":
                root = root.head
            groups.setdefault(root.i, {root.i}).add(word.i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        sink_mass = 0.95
        if any(w.pos_ in ("AUX", "CCONJ", "SCONJ") for w in words):
            sink_mass = 0.90
        if any(w.is_punct for w in words):
            sink_mass = 0.86
        if not tokens[i].lstrip("ĠĊ").strip():
            sink_mass = 0.96

        sink_mass -= min(0.025, 0.006 * np.log1p(i))

        # Distribute the small non-sink component over causal local context.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual[-1] *= 0.5

        for word in words:
            for j in inverse[word.head.i]:
                if 0 < j < i:
                    residual[j - 1] += 0.4
            if word.is_punct and i > 1:
                residual[i - 2] += 0.8

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

        # Transfer only sink mass: retain every original residual and diagonal.
        anchors = np.zeros(n, dtype=np.float64)
        transfer = 0.0
        for word in words:
            for root_index, members in groups.items():
                start, end = min(members), max(members)
                if word.i <= start:
                    continue
                nominal = doc[root_index].pos_ in ("NOUN", "PROPN")
                connectors = {
                    child.i
                    for member in members
                    for child in doc[member].children
                    if child.dep_ == "cc"
                }
                boundary = (
                    word.i in connectors
                    or (word.text == "," and start < word.i <= end + 1)
                )
                conjunct = word.i in members
                continuation = (
                    nominal
                    and end < word.i <= end + 5
                    and any(ancestor.i in members for ancestor in word.ancestors)
                )
                trailing_connector = (
                    not nominal
                    and end < word.i <= end + 2
                    and word.pos_ in ("ADV", "CCONJ", "SCONJ")
                    and any(doc[k].text == "," for k in range(end + 1, word.i))
                )
                if not (boundary or conjunct or continuation or trailing_connector):
                    continue

                strength = (
                    0.76 if boundary or trailing_connector
                    else 0.46 if continuation
                    else 0.30
                )
                candidate = np.zeros(n, dtype=np.float64)
                for member in members:
                    if member >= word.i:
                        continue
                    for j in inverse[member]:
                        if 0 < j < i:
                            candidate[j] += 1.0
                    for child in doc[member].children:
                        if child.i < word.i and child.dep_ in (
                            "cc", "nsubj", "dobj", "obj", "amod", "advmod", "det"
                        ):
                            for j in inverse[child.i]:
                                if 0 < j < i:
                                    candidate[j] += 0.22
                if candidate.sum() and strength > transfer:
                    anchors = candidate
                    transfer = strength

            # A fronted adjectival predicate remains salient across its subject/copula.
            if word.pos_ in ("PRON", "AUX"):
                for predicate in doc[max(0, word.i - 3):word.i]:
                    if (
                        predicate.pos_ == "ADJ"
                        and predicate.dep_ in ("acomp", "attr", "oprd")
                        and predicate.head.pos_ in ("AUX", "VERB")
                        and predicate.head.i >= word.i
                        and (word.head.i == predicate.head.i or word.i == predicate.head.i)
                        and transfer < 0.76
                    ):
                        candidate = np.zeros(n, dtype=np.float64)
                        for j in inverse[predicate.i]:
                            if 0 < j < i:
                                candidate[j] = 1.0
                        if candidate.sum():
                            anchors = candidate
                            transfer = 0.76

        if transfer > 0.0:
            mass = min(transfer, attention[i, 0])
            attention[i, 0] -= mass
            attention[i] += mass * anchors / anchors.sum()

    return "first_token_sink_with_coordination_retrieval", attention


def prog_L6H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, gradually diluted by the causal context.
    Linguistic features weakly modulate sink strength; residual attention is diffuse.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_context_dilution", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        dilution = 0.018 * (i ** 1.12)
        aligned = alignment[i]
        word = doc[aligned[0]] if aligned else None

        if word is not None:
            if word.pos_ in ("DET", "ADP", "PART"):
                dilution *= 0.88
            elif word.pos_ == "PROPN":
                dilution *= 0.82
            elif word.pos_ == "PRON":
                dilution *= 1.12
            elif word.pos_ in ("VERB", "ADJ"):
                dilution *= 1.08

            if word.is_space:
                dilution *= 0.55
        elif tokens[i].replace("\u0120", "").strip() == "":
            dilution *= 0.55

        sink_mass = 1.0 / (1.0 + dilution)
        attention[i, 0] = sink_mass

        # No consistent secondary target is evident: distribute the remainder
        # broadly, with only a mild preference for recent positions.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.8 + 0.2 * np.exp(-(i - positions) / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "first_token_sink_with_context_dilution", attention


def prog_L6H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with boundary-triggered retrieval of earlier context.
    At sentence endings and quote closures, divert sink mass without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_boundary_retrieval", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    quote_open = None
    last_quote_anchor = None
    last_quote_close = -100

    attention[0, 0] = 1.0
    if tokens[0].lstrip("Ġ").strip() in ('"', "“", "‘", "«"):
        quote_open = 0

    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None

        sink = 0.74 + 0.25 * np.exp(-i / 8.0)
        if word is not None:
            if word.pos_ in ("DET", "ADJ", "ADP", "NUM"):
                sink += 0.025
            elif word.pos_ == "AUX":
                sink += 0.015
            elif word.pos_ == "VERB":
                sink -= 0.065
            if word.dep_ in ("nsubj", "nsubjpass", "csubj") and i > 4:
                sink -= 0.12
            if word.dep_ in ("cc", "mark"):
                sink -= 0.04
            if word.is_punct and word.text in (".", "!", "?", ";"):
                sink -= 0.14

        # Quote boundaries often restore the strong default sink.
        previous = tokens[i - 1].lstrip("Ġ")
        if previous in ('"', "“", "‘", "«"):
            sink += 0.12
        if word is not None and word.pos_ in ("PRON", "AUX", "VERB"):
            if i > 1 and tokens[i - 2].lstrip("Ġ") in ('"', "“", "‘", "«"):
                sink += 0.07

        sink = float(np.clip(sink, 0.40, 0.985))

        # Spread the non-sink mass over recent tokens and causal syntax.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        if word is not None:
            for j in inverse[word.head.i]:
                if 0 < j <= i and word.head.i != word.i:
                    residual[j - 1] += 1.5
            for child in word.children:
                for j in inverse[child.i]:
                    if 0 < j <= i:
                        residual[j - 1] += 0.5

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

        # Special case: boundaries retrieve a broad earlier span, rather
        # than increasing local syntax or changing the diagonal weight.
        text = tokens[i].lstrip("Ġ").strip()
        has_quote = any(c in text for c in ('"', "“", "”", "‘", "’", "«", "»"))
        closes_quote = (
            quote_open is not None
            and has_quote
            and (text == '"' or any(c in text for c in ('"', "”", "’", "»")))
            and (word is None or word.is_punct)
        )
        terminal = (
            bool(text)
            and any(c in text for c in (".", "!", "?"))
            and all(c in '.!?"“”‘’«»' for c in text)
        )
        after_quote = 0 < i - last_quote_close <= 4
        anchor = quote_open if closes_quote else last_quote_anchor

        if i > 2 and (closes_quote or terminal or after_quote):
            past = np.arange(1, i)
            start = 1
            if terminal and not closes_quote and last_quote_close >= 0:
                start = min(last_quote_close + 1, i - 1)
            width = max(2.0, 0.28 * (i - start))
            center = start + 0.35 * (i - start)
            retrieval = np.exp(-0.5 * ((past - center) / width) ** 2)
            retrieval[past < start] = 0.0
            retrieval /= retrieval.sum()

            if (closes_quote or after_quote) and anchor is not None and 0 < anchor < i:
                retrieval *= 0.35 if closes_quote else 0.45
                retrieval[anchor - 1] += 0.65 if closes_quote else 0.55

            if closes_quote:
                target_sink = 0.16
            elif terminal:
                target_sink = 0.20 * np.exp(-max(i - 20, 0) / 30.0)
            else:
                target_sink = 0.40

            transfer = max(0.0, attention[i, 0] - target_sink)
            attention[i, 0] -= transfer
            attention[i, 1:i] += transfer * retrieval

        if closes_quote:
            last_quote_anchor = quote_open
            last_quote_close = i
            quote_open = None
        elif text in ('"', "“", "‘", "«") and quote_open is None:
            quote_open = i

    return "first_token_sink_with_boundary_retrieval", attention


def prog_L6H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, strongest near the opening phrase.
    Residual attention is local, with weaker syntactic and dialogue anchoring.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_to_model = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            word_to_model[k].append(i)

    first_pos = doc[0].pos_ if len(doc) else ""
    in_quote = False
    recent_nominal = None

    for i in range(n):
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        pos = word.pos_ if word is not None else ""
        has_quote = '"' in clean or "“" in clean or "”" in clean

        if i == 0:
            attention[0, 0] = 1.0
        else:
            sink = 0.52 + 0.34 * np.exp(-i / 3.5)

            if first_pos in ("ADP", "ADV", "SCONJ") and i <= 3:
                sink += 0.10
            if pos in ("VERB", "AUX"):
                sink += 0.06
            elif pos in ("NOUN", "PROPN", "ADJ"):
                sink += 0.025
            elif pos == "PRON":
                sink -= 0.08

            if clean.isspace():
                sink += 0.16
            if in_quote:
                sink -= 0.15

            sink = float(np.clip(sink, 0.25, 0.97))
            weights = np.exp(-(i - np.arange(1, i + 1)) / 7.0)
            weights[-1] += 0.65

            if word is not None:
                for j in word_to_model[word.head.i]:
                    if 0 < j <= i:
                        weights[j - 1] += 0.45

            if (in_quote or has_quote) and recent_nominal is not None:
                if 0 < recent_nominal <= i:
                    weights[recent_nominal - 1] += 1.5

            attention[i, 0] = sink
            attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

        if pos in ("NOUN", "PROPN") and not in_quote:
            recent_nominal = i

        quote_count = clean.count('"') + clean.count("“") + clean.count("”")
        if quote_count % 2:
            in_quote = not in_quote

    return "first_token_sink_with_local_residual", attention


def prog_L6H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, strongest near the start and persistent thereafter.
    Residual attention is local, with modest punctuation and syntactic corrections.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i]]
        word = words[-1] if words else None
        clean = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")
        early = np.exp(-(i - 1) / 3.0)
        sink = 0.58 + 0.385 * early

        if not clean.strip():
            sink += 0.16 * (1.0 - early)
        elif word is not None:
            if word.pos_ == "PUNCT":
                if word.text in (",", ";", ":"):
                    sink += 0.06 * early
                elif word.text in (".", "!", "?"):
                    sink -= 0.23 * (1.0 - early)
                else:
                    sink -= 0.09 * (1.0 - early)
            elif word.pos_ in ("DET", "ADJ", "ADP"):
                sink += 0.025 * (1.0 - early)
            elif word.pos_ in ("VERB", "AUX"):
                sink -= 0.025 * (1.0 - early)

        sink = float(np.clip(sink, 0.20, 0.985))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = 0.20 + np.exp(-(i - positions) / 3.0)
        residual[-1] += 0.30

        if word is not None and word.head.i != word.i:
            head_index = word.head.i
            for j in range(1, i + 1):
                if head_index in alignment[j]:
                    residual[j - 1] += 0.20

        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "first_token_sink_with_local_residual", attention


def prog_L6H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with slowly weakening positional dominance.
    Linguistic features modulate a small, locally distributed residual."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        word = None
        for k in aligned:
            if not doc[k].is_space:
                word = doc[k]
                break

        sink_mass = 0.64 + 0.33 * np.exp(-i / 40.0)

        if word is not None:
            if word.is_punct:
                sink_mass -= 0.10
            elif word.pos_ == "PRON":
                sink_mass -= 0.055
            elif word.pos_ in ("DET", "CCONJ", "SCONJ"):
                sink_mass -= 0.035
            elif word.pos_ == "AUX":
                sink_mass -= 0.025
            elif word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink_mass += 0.015

            if word.dep_ in ("nsubj", "nsubjpass") and i > 5:
                sink_mass -= 0.025

        sink_mass = float(np.clip(sink_mass, 0.50, 0.98))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 5.0)

        if word is not None and word.head.i != word.i:
            for j in range(1, i + 1):
                if word.head.i in alignment[j]:
                    residual[j - 1] += 0.20

        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "first_token_sink_with_decay", attention


def prog_L6H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, weakening with distance and competing with
    local syntactic and punctuation-boundary attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_local_structure", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.48 + 0.50 * np.exp(-(i - 1) / 6.0)
        if pos in ("NOUN", "PROPN"):
            sink -= 0.055
        elif pos in ("PRON", "CCONJ", "SCONJ"):
            sink -= 0.10 * (1.0 - np.exp(-i / 4.0))
        elif pos in ("VERB", "ADJ"):
            sink += 0.045
        elif pos == "PUNCT":
            sink -= 0.16 * (1.0 - np.exp(-i / 3.0))

        # Later sentence starts often have stronger non-sink alternatives.
        if word is not None and word.is_sent_start and i > 3:
            sink -= 0.10

        continuation = (
            i > 0
            and bool(indices)
            and bool(set(indices).intersection(alignment[i - 1]))
        )
        if continuation:
            sink -= 0.04

        sink = float(np.clip(sink, 0.22, 0.985))

        # Non-sink mass favors nearby content and accessible syntactic heads.
        positions = np.arange(1, i + 1)
        weights = 0.12 + np.exp(-(i - positions) / 3.5)
        weights[-1] *= 0.35

        for j in range(1, i):
            if alignment[j]:
                prior = doc[alignment[j][-1]]
                if prior.pos_ in ("NOUN", "PROPN", "VERB", "ADJ", "AUX"):
                    weights[j - 1] *= 1.35
                elif prior.pos_ == "PUNCT":
                    weights[j - 1] *= 0.55

        if word is not None:
            for j in inverse[word.head.i]:
                if 0 < j < i:
                    weights[j - 1] += 1.8

            if dep == "conj":
                for j in inverse[word.head.i]:
                    if 0 < j < i:
                        weights[j - 1] += 1.5

        if pos in ("PUNCT", "CCONJ") and i > 1:
            weights[i - 2] += 3.5
        if continuation and i > 1:
            weights[i - 2] += 1.5

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return "first_token_sink_with_local_structure", attention


def prog_L6H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with residual attention to recent syntactic context.
    Local competition is strongest for auxiliaries, conjunctions, and punctuation."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    sink_by_pos = {
        "NOUN": 0.66,
        "PROPN": 0.73,
        "VERB": 0.68,
        "ADJ": 0.71,
        "ADV": 0.63,
        "DET": 0.65,
        "PRON": 0.58,
        "AUX": 0.44,
        "ADP": 0.55,
        "PART": 0.51,
        "CCONJ": 0.47,
        "SCONJ": 0.58,
        "NUM": 0.65,
    }

    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        clean = tokens[i].replace("\u0120", " ").replace("\u010a", "\n").strip()

        sink = sink_by_pos.get(word.pos_, 0.65) if word is not None else 0.69
        if not clean:
            sink = 0.80
        elif all(c in ".,;:!?\"'()[]{}…—–-" for c in clean):
            if any(c in ".!?" for c in clean):
                sink = 0.76
            elif any(c in ",;:" for c in clean):
                sink = 0.43
            else:
                sink = 0.57

        local = np.exp(-(i - np.arange(1, i + 1)) / 2.5)
        local[-1] *= 0.20
        if i > 1:
            local[-2] += 1.6

        if word is not None:
            # Prefer a preceding governor, never an unavailable future governor.
            head_positions = [
                j for j in inverse[word.head.i]
                if 0 < j < i and j not in inverse[word.i]
            ]
            if head_positions:
                j = head_positions[-1]
                local[j - 1] += 2.4

            # A preceding argument can compete when the query is its governor.
            for child in word.children:
                if child.dep_ in ("nsubj", "nsubjpass", "csubj", "obj", "dobj", "pobj"):
                    positions = [j for j in inverse[child.i] if 0 < j < i]
                    if positions:
                        local[positions[-1] - 1] += 0.8

            # Continuations often retain attention on their own word's prefix.
            prefix = [j for j in inverse[word.i] if 0 < j < i]
            if prefix:
                local[prefix[0] - 1] += 2.0
                sink -= 0.08

        # The immediately following token almost invariably selects position zero.
        if i == 1:
            sink = 0.96
        elif i == 2:
            sink = 0.78 * 0.65 + sink * 0.35

        sink = float(np.clip(sink, 0.30, 0.97))
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

    return "first_token_sink_with_local_syntax", make_row_stochastic(attention)


def prog_L6H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with a gated dialogue-induction exception:
    repeated cues can retrieve the token following an earlier occurrence."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        attention[i, :i + 1] = 0.005 / (i + 1)
        attention[i, 0] += 0.995

    clean = [t.lstrip("Ġ").lstrip("Ċ") for t in tokens]
    quoted = any(c in sentence for c in '"“”«»')
    fragmented_unicode = any(
        any(ord(c) > 127 for c in t) and not t.isalpha()
        for t in clean
    )

    if quoted or fragmented_unicode:
        doc = spacy_parse(sentence)
        aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
        pos = [
            doc[ids[-1]].pos_ if ids else ""
            for ids in aligned
        ]

        for i in range(2, n):
            text = clean[i]
            whitespace = not text.strip()
            quote = bool(text) and all(c in '"“”«»' for c in text)
            comma = text == "," and pos[i - 1] in ("VERB", "AUX")
            fragment = (
                bool(text)
                and any(ord(c) > 127 for c in text)
                and not text.isalpha()
            )
            lexical = pos[i] in ("NOUN", "PROPN", "VERB", "ADP", "DET")

            if not (whitespace or quote or comma or fragment or lexical):
                continue

            best_j, best_score = -1, 0.72
            for j in range(i - 1):
                if whitespace:
                    score = 1.0 if not clean[j].strip() else 0.0
                elif quote or comma:
                    score = 1.0 if clean[j] == text else 0.0
                else:
                    if not fragment and pos[j] != pos[i]:
                        continue
                    score = embedding_similarity(tokens, i, j, tokenizer)

                if score >= best_score:
                    best_j, best_score = j, score

            if best_j < 0:
                continue

            if whitespace:
                mass = 0.58
            elif fragment:
                mass = 0.50
            elif quote:
                mass = 0.24
            elif comma:
                mass = 0.18
            elif pos[i] == "DET":
                mass = 0.14
            elif pos[i] == "ADP":
                mass = 0.20
            else:
                mass = 0.40

            # Move only sink mass; retain every baseline self/background weight.
            mass *= min(1.0, max(0.0, (best_score - 0.72) / 0.28))
            target = best_j + 1
            mass = min(mass, attention[i, 0])
            attention[i, 0] -= mass
            attention[i, target] += mass

    return "first_token_sink_with_dialogue_induction", attention


def prog_L6H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, weakening mildly with position.
    Residual attention is distributed causally with a modest recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = np.clip(0.985 - 0.003 * i, 0.80, 0.985)
        positions = np.arange(1, i + 1)
        residual = 0.2 / i + 0.8 * np.exp(-(i - positions) / 6.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink", attention


def prog_L6H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink, with contextual sinks for fronted PPs and marked clauses.
    Redistribute only off-diagonal mass when one of those structures is present.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_contextual_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    representatives = []
    inverse = [[] for _ in doc]

    for i, indices in enumerate(aligned):
        usable = [k for k in indices if not doc[k].is_space]
        representatives.append(doc[usable[0]] if usable else None)
        for k in usable:
            inverse[k].append(i)

    # These structures can supply an alternative to the first-token sink.
    fronted_pp = bool(doc) and (
        doc[0].pos_ == "ADP"
        or (
            doc[0].pos_ == "ADV"
            and any(c.dep_ in ("pobj", "obl") for c in doc[0].children)
        )
    )
    clause_markers = [
        w for w in doc if w.dep_ == "mark" and w.pos_ == "SCONJ"
    ]

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = representatives[i]
        previous = representatives[i - 1]
        surface = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()

        sink = 0.53
        if word is not None:
            pos = word.pos_
            if pos in ("VERB", "AUX"):
                sink = 0.70
            elif pos == "CCONJ":
                sink = 0.67
            elif pos == "SCONJ":
                sink = 0.51
            elif pos == "PROPN":
                sink = 0.64
            elif pos == "NOUN":
                sink = 0.45
            elif pos in ("ADP", "DET"):
                sink = 0.48
            elif pos == "ADJ":
                sink = 0.50
            elif pos == "ADV":
                sink = 0.51
            elif pos == "PRON":
                sink = 0.55

            if word.dep_ == "ROOT":
                sink = max(sink, 0.70)
            if word.is_sent_start:
                sink = max(sink, 0.77)

        if not surface:
            sink = 0.92
        elif all(c in ".!?\"'”’" for c in surface):
            sink = 0.82 if any(c in ".!?" for c in surface) else 0.62
        elif surface in (",", ";", ":"):
            sink = 0.57

        local_anchor = None
        if word is not None and previous is not None:
            different_word = word.i != previous.i
            if different_word:
                if (
                    word.pos_ == "PRON"
                    and previous.pos_ in ("SCONJ", "VERB", "ADV")
                ):
                    sink = 0.28
                    local_anchor = i - 1
                elif word.pos_ == "DET" and previous.pos_ == "ADP":
                    sink = 0.29
                    local_anchor = i - 1
                elif (
                    word.pos_ == "AUX"
                    and previous.pos_ == "PRON"
                    and i >= 2
                ):
                    earlier = representatives[i - 2]
                    if earlier is not None and earlier.pos_ == "VERB":
                        sink = 0.31
                        local_anchor = i - 2

                if surface == "," and previous.pos_ in ("NOUN", "PRON"):
                    if previous.dep_ in ("pobj", "obl", "npadvmod"):
                        sink = 0.28
                        local_anchor = i - 1

        # Very early positions overwhelmingly use the first-token sink.
        if i == 1:
            sink = 0.95
        elif i == 2 and local_anchor is None:
            sink = max(sink, 0.80)
        elif i == 3 and local_anchor is None:
            sink = max(sink, 0.67)

        positions = np.arange(1, i + 1)
        local = np.exp(-(i - positions) / 3.0)
        local[-1] *= 0.22

        # Prefer an available syntactic governor over undifferentiated recency.
        if word is not None and word.head.i != word.i:
            candidates = [j for j in inverse[word.head.i] if 0 < j < i]
            if candidates:
                governor = candidates[-1]
                local[governor - 1] += 2.5 * np.exp(
                    -(i - governor - 1) / 12.0
                )

        if local_anchor is not None and local_anchor > 0:
            local *= 0.20
            local[local_anchor - 1] += 5.0

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

        # Special case: persistent contextual anchors, not a stronger governor.
        # Never touch the diagonal or change the original recency distribution.
        if i >= 2 and word is not None and len(inverse[word.i]) == 1:
            ancestors = {word.i}
            ancestors.update(a.i for a in word.ancestors)
            active = [
                m for m in clause_markers
                if m.i <= word.i
                and m.head.i in ancestors
                and any(0 < j < i for j in inverse[m.i])
            ]
            if fronted_pp or active:
                targets = np.zeros(i, dtype=np.float64)
                if fronted_pp:
                    targets[1] += 1.0
                    for j in range(2, min(i, 4)):
                        anchor = representatives[j]
                        if anchor is not None and (
                            anchor.pos_ in ("ADP", "ADV", "PART")
                            or anchor.dep_ in ("nsubj", "nsubjpass")
                        ):
                            targets[j] += 0.65

                if active:
                    marker = max(active, key=lambda m: m.i)
                    marker_j = max(j for j in inverse[marker.i] if 0 < j < i)
                    targets[marker_j] += 1.5
                    before = representatives[marker_j - 1]
                    if before is not None and before.pos_ in ("VERB", "AUX"):
                        targets[marker_j - 1] += 1.0

                verbal = [
                    j for j in range(1, i)
                    if representatives[j] is not None
                    and representatives[j].pos_ in ("VERB", "AUX")
                ]
                for j in verbal[-2:]:
                    targets[j] += 0.65

                targets[0] = 0.0
                if targets.sum() > 0.0:
                    moved = attention[i, 0] * (0.65 if fronted_pp else 0.55)
                    attention[i, 0] -= moved
                    # Loosen an overly sharp preposition/determiner shortcut.
                    if (
                        local_anchor is not None
                        and 0 < local_anchor < i
                        and word.pos_ == "DET"
                    ):
                        released = 0.50 * attention[i, local_anchor]
                        attention[i, local_anchor] -= released
                        moved += released
                    attention[i, :i] += moved * targets / targets.sum()

    return "first_token_sink_with_contextual_anchors", attention


def prog_L7H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with a local nominal-phrase exception.
    Phrase onsets and complex nominal continuations divert sink mass to earlier phrase anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_nominal_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    representatives = []
    word_to_tokens = [[] for _ in doc]

    for i, indices in enumerate(aligned):
        valid = [k for k in indices if k < len(doc)]
        nonspace = [k for k in valid if not doc[k].is_space]
        representatives.append(doc[nonspace[-1]] if nonspace else None)
        for k in valid:
            word_to_tokens[k].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word = representatives[i]
        clean = tokens[i].lstrip("\u0120").lstrip("\u0122").strip()
        sink = 0.70

        if word is not None:
            if word.pos_ in ("VERB", "AUX"):
                sink = 0.81
            elif word.pos_ == "PRON":
                sink = 0.79
            elif word.pos_ in ("SCONJ", "CCONJ"):
                sink = 0.82
            elif word.pos_ == "ADP":
                sink = 0.72
            elif word.pos_ == "ADV":
                sink = 0.73
            elif word.pos_ == "DET":
                sink = 0.59
            elif word.pos_ in ("NOUN", "PROPN"):
                sink = 0.55
            elif word.pos_ in ("ADJ", "NUM"):
                sink = 0.53

            if word.dep_ in ("ROOT", "ccomp", "advcl", "relcl"):
                sink = max(sink, 0.86)
            if word.dep_ in ("nsubj", "nsubjpass") and word.pos_ == "PRON":
                sink = max(sink, 0.85)

        if any(c in clean for c in ".!?"):
            sink = 0.95
        elif clean and all(c in "\"'“”‘’" for c in clean):
            sink = 0.90
        elif clean and all(c in ",;:" for c in clean):
            sink = 0.82

        previous = representatives[i - 1]
        if word is not None and previous is not None:
            if word.dep_ in ("dobj", "obj", "pobj") and previous.pos_ in ("VERB", "ADP"):
                sink = min(sink, 0.40)
            if word.dep_ == "poss" and previous.pos_ == "VERB":
                sink = min(sink, 0.30)

        if i == 1:
            sink = 0.96
        elif i == 2:
            sink = max(sink, 0.85)

        local = np.zeros(i + 1, dtype=np.float64)
        local[i] = 0.20
        local[i - 1] += 1.0

        if i > 1:
            distances = np.arange(i, 0, -1, dtype=np.float64)
            local[:i] += 0.12 * np.exp(-distances / 3.0)

        if word is not None:
            for j in word_to_tokens[word.head.i]:
                if 0 < j < i:
                    local[j] += 0.65
            for child in word.children:
                if child.dep_ in ("det", "amod", "compound", "poss"):
                    for j in word_to_tokens[child.i]:
                        if 0 < j < i:
                            local[j] += 0.35

        local[0] = 0.0
        local /= local.sum()
        attention[i, :i + 1] = (1.0 - sink) * local
        attention[i, 0] = sink

        # Transfer only sink mass: preserve the original self-attention,
        # decay, and all existing non-sink weights.
        if word is not None and previous is not None:
            nominal = None
            if word.pos_ in ("NOUN", "PROPN"):
                nominal = word
            elif (
                word.pos_ in ("DET", "ADJ", "NUM") or word.dep_ == "poss"
            ) and word.head.pos_ in ("NOUN", "PROPN"):
                nominal = word.head

            if nominal is not None:
                onset = (
                    previous.i != word.i
                    and (
                        word.pos_ == "DET"
                        and previous.pos_ in ("VERB", "ADP")
                        or word.dep_ == "poss" and previous.pos_ == "ADP"
                    )
                )
                modifiers = [
                    child for child in nominal.children
                    if child.dep_ in ("det", "amod", "compound", "poss")
                    and child.i < word.i
                ]
                continuation = (
                    word.pos_ in ("NOUN", "PROPN", "ADJ", "NUM")
                    and (
                        previous.i == word.i
                        or any(c.dep_ in ("amod", "compound") for c in modifiers)
                    )
                )

                if onset or continuation:
                    anchors = np.zeros(i + 1, dtype=np.float64)
                    if onset:
                        anchors[i - 1] += 1.0
                    else:
                        for child in modifiers:
                            indices = [j for j in word_to_tokens[child.i] if 0 < j < i]
                            if indices:
                                anchors[indices[0]] += 1.0
                        indices = [j for j in word_to_tokens[word.i] if 0 < j < i]
                        if indices:
                            anchors[indices[0]] += 0.8
                        if nominal.head.pos_ in ("VERB", "ADP"):
                            for j in word_to_tokens[nominal.head.i]:
                                if 0 < j < i:
                                    anchors[j] += 0.6

                    if anchors.sum() > 0:
                        target_sink = (
                            0.28 if onset and previous.pos_ == "ADP"
                            else 0.46 if onset else 0.32
                        )
                        transfer = max(0.0, attention[i, 0] - target_sink)
                        attention[i, 0] -= transfer
                        attention[i, :i + 1] += transfer * anchors / anchors.sum()

    return "first_token_sink_with_nominal_anchors", make_row_stochastic(attention)


def prog_L7H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, weakening with distance.
    Residual attention favors nearby tokens and accessible syntactic heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_decay", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_indices in enumerate(aligned):
        for wi in word_indices:
            inverse[wi].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.55 + 0.44 * np.exp(-(i - 1) / 55.0)

        word_indices = aligned[i]
        if not word_indices or all(
            doc[wi].is_punct or doc[wi].is_space for wi in word_indices
        ):
            sink_mass += 0.015

        sink_mass = float(np.clip(sink_mass, 0.55, 0.995))

        # Reserve column zero for the sink; normalize the residual separately.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 5.0)
        residual[-1] *= 0.65

        for wi in word_indices:
            word = doc[wi]
            if word.head.i != wi:
                head_tokens = [
                    j for j in inverse[word.head.i] if 0 < j <= i
                ]
                if head_tokens:
                    bonus = 1.0 / len(head_tokens)
                    for j in head_tokens:
                        residual[j - 1] += bonus

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "first_token_sink_with_decay", attention


def prog_L7H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with a tiny diffuse causal residual.
    The examples show positional anchoring rather than a linguistic dependency."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
        else:
            attention[i, 0] = 0.997
            attention[i, 1:i + 1] = 0.003 / i

    return "first_token_sink", attention


def prog_L7H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with an early-position boost and syntactic leakage.
    Closing quoted clauses can redirect attention toward their introducing verb.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_clause_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    representatives = []
    inverse = {}
    for i, indices in enumerate(alignment):
        valid = [k for k in indices if k < len(doc)]
        content = [k for k in valid if not doc[k].is_space]
        k = content[0] if content else (valid[0] if valid else None)
        representatives.append(k)
        for sid in valid:
            if sid not in inverse:
                inverse[sid] = i

    attention[0, 0] = 1.0
    quote_open = False
    quote_anchor = None
    last_outside_verb = None

    for i in range(n):
        sid = representatives[i]
        word = doc[sid] if sid is not None else None
        raw = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        closing_quote = False

        # Apostrophes are deliberately excluded: contractions are not quotations.
        for char in raw:
            if char in ('"', '“', '”', '«', '»'):
                if char in ('”', '»') or (char == '"' and quote_open):
                    closing_quote = quote_open
                    quote_open = False
                else:
                    quote_open = True
                    quote_anchor = last_outside_verb

        if i == 0:
            if word is not None and word.pos_ == "VERB" and not quote_open:
                last_outside_verb = i
            continue

        sink = 0.65 + 0.32 * np.exp(-(i - 1) / 3.8)

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "ADJ"):
                sink += 0.055
            elif word.pos_ in ("ADP", "PART", "SCONJ", "CCONJ"):
                sink -= 0.10
            elif word.pos_ == "VERB" and i > 4:
                sink -= 0.065
            if word.dep_ in ("nsubj", "nsubjpass") and i < 5:
                sink += 0.025
            if word.is_punct and any(c in raw for c in ".!?;"):
                sink -= 0.20

        if not raw.strip():
            sink += 0.12
        sink = float(np.clip(sink, 0.28, 0.985))

        # Spread the non-sink mass over local context and syntactic governors.
        positions = np.arange(1, i + 1)
        residual = 0.12 + np.exp(-(i - positions) / 4.0)
        if word is not None:
            head_index = inverse.get(word.head.i)
            if head_index is not None and 1 <= head_index <= i:
                residual[head_index - 1] += 1.8

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        if closing_quote and quote_anchor is not None and quote_anchor < i:
            # A closing quote summarizes the clause under its introducing verb.
            attention[i] *= 0.39
            attention[i, quote_anchor] += 0.61

        if word is not None and word.pos_ == "VERB" and not quote_open:
            last_outside_verb = i

    return "first_token_sink_with_clause_leakage", make_row_stochastic(attention)


def prog_L7H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink, with selective release to earlier governors when a
    prepositional noun phrase or embedded nominal complement is completed.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    # Locate word starts and ends without changing the original alignment.
    word_tokens = [[] for _ in doc]
    for ti, sids in enumerate(alignment):
        for si in sids:
            word_tokens[si].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.89
        aligned = alignment[i]

        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("DET", "PRON", "AUX", "PART"):
                sink = 0.945
            elif word.pos_ in ("ADP", "SCONJ"):
                sink = 0.915
            elif word.pos_ in ("NOUN", "PROPN"):
                sink = 0.835
            elif word.pos_ == "ADJ":
                sink = 0.89
            elif word.pos_ == "PUNCT":
                sink = 0.80

            if word.dep_ in ("nsubj", "nsubjpass", "poss"):
                sink = max(sink, 0.94)
            if word.is_sent_start:
                sink = max(sink, 0.96)

        # The earliest queries exhibit especially strong sink attention.
        sink = min(0.995, sink + 0.075 * np.exp(-(i - 1) / 2.0))

        # Do not invent a strong secondary syntactic target: spread the
        # residual over accessible non-sink positions with mild recency.
        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 + 0.5 * np.exp(-(i - positions) / 8.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()
        attention[i, 0] = sink

        # Completed PP objects selectively retrieve their governing phrase.
        # Transfer only sink mass: self-attention and all untargeted edges
        # retain exactly the original weights.
        if aligned:
            word = doc[aligned[0]]
            nominal = word.head if word.dep_ == "compound" else word
            pp_object = (
                nominal.dep_ in ("pobj", "obl", "nmod")
                and nominal.head.pos_ == "ADP"
            )
            embedded_complement = (
                nominal.dep_ in ("attr", "oprd", "dobj", "obj")
                and nominal.head.dep_ in ("ccomp", "xcomp")
                and nominal.head.head.pos_ == "VERB"
            )
            if (
                word.pos_ in ("NOUN", "PROPN")
                and word_tokens[word.i]
                and i == word_tokens[word.i][-1]
                and (pp_object or embedded_complement)
            ):
                targets = np.zeros(i, dtype=np.float64)
                governor = nominal.head
                for _ in range(3):
                    if governor.i >= nominal.i:
                        break
                    mapped = word_tokens[governor.i]
                    if mapped and 0 < mapped[0] < i:
                        weight = (
                            1.6 if governor.pos_ in ("VERB", "AUX")
                            else 1.0 if governor.pos_ == "ADP"
                            else 0.5
                        )
                        targets[mapped[0]] += weight
                    if governor.head.i == governor.i:
                        break
                    governor = governor.head

                for child in nominal.children:
                    if child.dep_ in ("det", "poss"):
                        mapped = word_tokens[child.i]
                        if mapped and 0 < mapped[0] < i:
                            targets[mapped[0]] += 0.45

                if targets.sum() > 0:
                    release = 0.48 if pp_object else 0.55
                    if word.dep_ == "compound":
                        release *= 0.75
                    elif any(c.dep_ == "compound" for c in word.children):
                        release += 0.08
                    mass = min(release, attention[i, 0])
                    attention[i, 0] -= mass
                    attention[i, :i] += mass * targets / targets.sum()

    return "first_token_sink", attention


def prog_L7H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with targeted backoff to introductory temporal frames
    and infinitival scope markers.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_frame_backoff", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    representatives = []
    inverse = [[] for _ in doc]

    for i, indices in enumerate(alignment):
        usable = [k for k in indices if not doc[k].is_space]
        representatives.append(usable[-1] if usable else None)
        for k in usable:
            inverse[k].append(i)

    # A short introductory temporal phrase can supply a secondary sink.
    frame = None
    if len(doc) > 1 and doc[0].pos_ in ("ADP", "NUM", "DET", "ADV"):
        w = doc[1]
        if (w.dep_ == "npadvmod"
                or (w.pos_ == "ADV" and doc[0].pos_ == "ADP")):
            if inverse[1]:
                frame = inverse[1][-1]

    attention[0, 0] = 1.0
    content_pos = ("NOUN", "PROPN", "VERB", "ADJ", "ADV", "PRON")
    clause_deps = ("ROOT", "conj", "ccomp", "xcomp", "advcl")

    for i in range(1, n):
        distances = i - np.arange(i + 1)
        background = np.exp(-distances / 5.0)
        background /= background.sum()
        attention[i, :i + 1] = 0.65 * background
        attention[i, :i + 1] += 0.20 / (i + 1)

        sink_strength = 10.5 / (1.0 + 0.035 * i)
        si = representatives[i]
        previous_si = representatives[i - 1]

        attention[i, i - 1] += 0.35
        attention[i, i] += 0.12

        if si is not None:
            word = doc[si]

            # A causal dependency link is a secondary destination, not the
            # main organizing principle of this predominantly sink head.
            head_indices = [j for j in inverse[word.head.i] if j < i]
            if word.head.i != si and head_indices:
                attention[i, head_indices[-1]] += 0.65

            if word.pos_ in ("VERB", "AUX"):
                sink_strength *= 1.12

            if word.is_punct:
                if previous_si is not None:
                    previous = doc[previous_si]
                    if previous.pos_ in content_pos:
                        attention[i, i - 1] += 2.5
                sink_strength *= 0.88

            if word.pos_ in ("CCONJ", "SCONJ"):
                for j in range(i - 1, 0, -1):
                    sj = representatives[j]
                    if sj is not None and doc[sj].pos_ in content_pos:
                        attention[i, j] += 2.4
                        break

            # Preserve a small trace of a recently established predicate
            # when entering a new clause or coordinated phrase.
            if word.dep_ in ("conj", "mark", "cc"):
                for j in range(i - 1, 0, -1):
                    sj = representatives[j]
                    if (sj is not None and doc[sj].pos_ == "VERB"
                            and doc[sj].dep_ in clause_deps):
                        attention[i, j] += 0.9
                        break

            # Subword continuations still mostly point to the sink.
            if previous_si == si:
                sink_strength *= 1.10
        elif tokens[i].strip("ĠĊ \t\r\n") == "":
            sink_strength *= 1.8

        attention[i, 0] += sink_strength

        # Only redistribute sink mass in these two identifiable contexts.
        # This preserves the row total and the original self-attention.
        if si is not None and not doc[si].is_punct:
            targets = {}
            if frame is not None and 0 < frame < i:
                targets[frame] = 0.40 * np.exp(-(i - frame - 1) / 18.0)

            word = doc[si]
            if (word.pos_ == "PART" and word.dep_ in ("aux", "mark")
                    and word.head.pos_ == "VERB"
                    and word.head.dep_ in ("xcomp", "ccomp")):
                prior = [j for j in inverse[word.head.head.i] if 0 < j < i]
                if prior:
                    targets[prior[-1]] = targets.get(prior[-1], 0.0) + 0.25
            else:
                ancestors = {w.i for w in word.ancestors}
                ancestors.add(si)
                for j in range(i - 1, max(0, i - 13), -1):
                    sj = representatives[j]
                    if sj is None:
                        continue
                    marker = doc[sj]
                    if (marker.pos_ == "PART"
                            and marker.dep_ in ("aux", "mark")
                            and marker.head.pos_ == "VERB"
                            and marker.head.i in ancestors):
                        targets[j] = targets.get(j, 0.0) + 0.25
                        break

            total = sum(targets.values())
            if total:
                scale = min(1.0, 0.55 / total)
                for j, fraction in targets.items():
                    mass = sink_strength * fraction * scale
                    attention[i, 0] -= mass
                    attention[i, j] += mass

    return (
        "first_token_sink_with_frame_backoff",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L7H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with decay; sentence-final punctuation releases sink mass
    toward preceding content, without changing self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_terminal_release", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for index in indices:
            inverse[index].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.60 + 0.39 * np.exp(-i / 24.0)
        word = doc[alignment[i][-1]] if alignment[i] else None

        if word is not None:
            if word.pos_ in ("PUNCT", "CCONJ", "SCONJ"):
                sink_mass -= 0.055
            elif word.pos_ in ("ADJ", "NOUN", "PROPN"):
                sink_mass += 0.015
            elif word.pos_ == "SPACE":
                sink_mass -= 0.04

        sink_mass = float(np.clip(sink_mass, 0.55, 0.99))
        positions = np.arange(1, i + 1)
        residual = 0.65 + np.exp(-(i - positions) / 5.0)

        if word is not None:
            for j in inverse[word.head.i]:
                if 0 < j <= i:
                    residual[j - 1] += 0.5

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

        # Only terminal punctuation gets the additional content-summary path.
        # Transfer mass from the sink, leaving the diagonal exactly unchanged.
        if (
            i == n - 1
            and word is not None
            and word.pos_ == "PUNCT"
            and any(mark in tokens[i] for mark in (".", "!", "?"))
        ):
            summary = np.zeros(i - 1, dtype=np.float64)
            for j in range(1, i):
                key = doc[alignment[j][-1]] if alignment[j] else None
                if key is not None and key.pos_ in (
                    "NOUN", "PROPN", "VERB", "AUX", "ADJ", "ADV", "ADP"
                ):
                    # Divide across subword pieces rather than favoring split words.
                    pieces = sum(0 < k < i for k in inverse[key.i])
                    summary[j - 1] = (
                        0.35 + np.exp(-(i - j) / 12.0)
                    ) / max(1, pieces)

            if summary.sum() > 0.0:
                released = min(0.32, 0.09 + 0.004 * i, sink_mass)
                attention[i, 0] -= released
                attention[i, 1:i] += released * summary / summary.sum()

    return "first_token_sink_with_terminal_release", attention


def prog_L7H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink, with competing quote-opening and reporting-clause anchors
    at dialogue boundaries; otherwise retain the original diffuse background.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[0, 0] = 1.0
            continue

        sink_mass = 1.0 / (1.0 + 0.0025 * i)
        distances = i - np.arange(1, i + 1)
        background = 0.75 + 0.25 * np.exp(-distances / 8.0)

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * background / background.sum()
        )

    # Only dialogue activates the correction. Transfer mass from the sink,
    # leaving all original self-attention and unrelated entries untouched.
    quote_counts = [
        sum(t.count(mark) for mark in ('"', '“', '”'))
        for t in tokens
    ]
    if sum(quote_counts) >= 2:
        doc = spacy_parse(sentence)
        alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
        pos = [doc[a[0]].pos_ if a else "" for a in alignment]
        clean = [t.lstrip("Ġ").strip() for t in tokens]
        inside = False
        opening = reporting = closing = -1
        boundary_tokens = 0

        for i in range(n):
            additions = np.zeros(n, dtype=np.float64)

            if quote_counts[i] % 2:
                if not inside:
                    opening = i
                    reporting = next(
                        (j for j in range(i - 1, 0, -1)
                         if pos[j] == "VERB"),
                        -1,
                    )
                    inside = True
                else:
                    inside = False
                    closing = i
                    boundary_tokens = 0
                    if 0 < opening < i:
                        additions[opening] += 0.10
                    if 0 < reporting < i:
                        additions[reporting] += 0.06

            elif not inside and closing >= 0 and opening > 0:
                if clean[i]:
                    boundary_tokens += 1

                # Narrative resumption recalls the preceding reporting clause.
                if boundary_tokens == 1 and pos[i] in (
                    "DET", "PROPN", "NOUN", "PRON"
                ):
                    additions[opening] += 0.07
                    if reporting > 0:
                        additions[reporting] += 0.12
                    if opening > 1 and clean[opening - 1] == ",":
                        additions[opening - 1] += 0.07

                # A verb followed by a comma often introduces another turn.
                if pos[i] == "VERB":
                    introduces_turn = i + 1 < n and clean[i + 1] == ","
                    additions[opening] += 0.46 if introduces_turn else 0.09
                elif clean[i] == "," and i > 0 and pos[i - 1] == "VERB":
                    additions[opening] += 0.30
                elif pos[i] == "ADV" and i > 0 and clean[i - 1] == ",":
                    additions[opening] += 0.09
                    additions[i - 1] += 0.16

            # Strictly earlier, non-sink targets preserve the diagonal exactly.
            additions[0:i if i else 1] *= 1.0
            additions[i:] = 0.0
            additions[0] = 0.0
            mass = additions.sum()
            if mass > 0:
                scale = min(1.0, attention[i, 0] / mass)
                attention[i, 0] -= mass * scale
                attention[i] += additions * scale

    return "first_token_sink_with_dialogue_anchors", attention


def prog_L7H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with selective predicate routing.
    Tight verbal prepositions alone are insufficient evidence for strong routing.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_selective_pp_routing", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, indices in enumerate(alignment):
        for si in indices:
            if si < len(doc):
                inverse[si].append(ti)

    matrix[0, 0] = 1.0
    for i in range(1, n):
        sink = 0.73
        target = None
        route = 0.0
        verbal_pp_route = False

        indices = alignment[i]
        if indices:
            word = doc[indices[-1]]
            if word.pos_ in ("NOUN", "PROPN", "VERB", "ADJ"):
                sink = 0.78
            elif word.pos_ in ("PRON", "DET", "ADP", "AUX", "CCONJ", "SCONJ"):
                sink = 0.59
            elif word.is_punct:
                sink = 0.76
            elif word.is_space:
                sink = 0.82

            # Find an earlier predicate governing this token or its phrase.
            ancestor = word.head
            visited = {word.i}
            while ancestor.i not in visited:
                visited.add(ancestor.i)
                earlier = [j for j in inverse[ancestor.i] if j < i]
                if earlier and ancestor.pos_ in ("VERB", "AUX", "ADJ"):
                    target = max(earlier)
                    break
                if ancestor.head.i == ancestor.i:
                    break
                ancestor = ancestor.head

            if target is not None and target > 0:
                distance = i - target
                if word.pos_ == "PRON" and distance <= 5:
                    route = 0.46
                    if ancestor.pos_ == "ADJ" and distance <= 2:
                        route = 0.94
                elif word.pos_ == "DET" and distance <= 3:
                    route = 0.36

                # Bare plural objects can refer back strongly to their action.
                if (word.pos_ == "NOUN"
                        and word.dep_ in ("dobj", "obj", "attr")
                        and word.tag_ in ("NNS", "NNPS")
                        and distance <= 2
                        and not any(c.dep_ == "det" for c in word.children)):
                    route = max(route, 0.63)

                # Predicate + preposition + short nominal phrase.
                prep = word if word.pos_ == "ADP" else word.head
                if word.pos_ == "DET":
                    prep = word.head.head
                if (prep.pos_ == "ADP"
                        and prep.head.i == ancestor.i
                        and prep.i == ancestor.i + 1
                        and distance <= 5):
                    route = max(route, 0.78)
                    verbal_pp_route = ancestor.pos_ in ("VERB", "AUX")
        elif not tokens[i].lstrip("Ġ").strip():
            sink = 0.82

        # The earliest positions have an especially strong sink prior.
        if i == 1:
            sink = 0.95
            route = 0.0
        elif i == 2:
            sink = max(sink, 0.85)

        if route > 0.0:
            sink = min(sink, 0.96 - route)

        residual = max(0.0, 1.0 - sink - route)
        positions = np.arange(i + 1)
        background = np.exp(-(i - positions) / 4.0)
        background /= background.sum()
        matrix[i, :i + 1] = residual * background
        matrix[i, 0] += sink
        if target is not None:
            matrix[i, target] += route

        # Reassign only the strong verbal-PP route, leaving self-attention
        # and every background weight exactly as in the original.
        if verbal_pp_route and route > 0.12:
            excess = route - 0.12
            matrix[i, target] -= excess
            matrix[i, 0] += excess

    return "first_token_sink_with_selective_pp_routing", make_row_stochastic(matrix)


def prog_L7H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with local anchors; determiner-led object phrases,
    especially compound and split-word interiors, strengthen the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_nominal_interiors", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    representatives = []
    first_piece = {}
    for i, indices in enumerate(alignment):
        useful = [k for k in indices if not doc[k].is_space]
        sid = useful[-1] if useful else None
        representatives.append(sid)
        for k in useful:
            if k not in first_piece:
                first_piece[k] = i

    attention[0, 0] = 1.0
    last_predicate = None
    last_boundary = None
    initial_sid = representatives[0]
    initial_pos = doc[initial_sid].pos_ if initial_sid is not None else ""
    opening_nominal = initial_pos in ("DET", "ADP", "NUM")
    opening_active = True

    for i in range(1, n):
        raw = tokens[i]
        text = raw.replace("Ġ", " ").replace("Ċ", "\n").strip()
        sid = representatives[i]
        word = doc[sid] if sid is not None else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.30 + 0.66 * np.exp(-(i - 1) / 3.1)

        if pos in ("VERB", "AUX"):
            sink += 0.13
        elif pos in ("NOUN", "PROPN", "ADJ"):
            sink += 0.05
        elif pos == "DET":
            sink += 0.07

        if opening_active and opening_nominal:
            if pos in ("DET", "ADJ", "NOUN", "PROPN", "NUM", "ADV", "ADP"):
                sink = max(sink, 0.975 - 0.022 * max(0, i - 1))
            elif pos == "AUX":
                sink = max(sink, 0.93)
                opening_active = False
            else:
                opening_active = False

        if i == 1:
            sink = 0.965 if pos != "PUNCT" else 0.90

        is_punct = bool(text) and all(not c.isalnum() for c in text)
        terminal = any(c in ".!?" for c in text)
        if not text:
            sink = 0.955
        elif terminal and is_punct:
            sink = 0.93 if text.strip(".!?") == "" else 0.83
        elif is_punct:
            sink = 0.67 if any(c in ",;:" for c in text) else 0.40
        elif any(ord(c) > 127 for c in text):
            sink = max(sink, 0.84)

        sink = float(np.clip(sink, 0.12, 0.985))

        positions = np.arange(1, i + 1)
        local = 0.08 + np.exp(-(i - positions) / 3.0)
        local[-1] *= 0.45

        if word is not None:
            head_index = first_piece.get(word.head.i)
            if head_index is not None and 0 < head_index < i:
                local[head_index - 1] += 1.8

            if dep in ("aux", "auxpass", "cop", "nsubj", "nsubjpass", "dobj", "obj"):
                if last_predicate is not None and last_predicate > 0:
                    local[last_predicate - 1] += 1.6

            if sid in first_piece and first_piece[sid] < i:
                previous_piece = i - 1
                if previous_piece > 0:
                    local[previous_piece - 1] += 0.6

        if last_boundary is not None and last_boundary > 0:
            local[last_boundary - 1] += 1.0 * np.exp(
                -(i - last_boundary) / 12.0
            )

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * local / local.sum()

        # Only nominal object interiors override the default distribution.
        # Transfer off-diagonal mass to the sink, leaving self-attention intact.
        if word is not None and pos in ("DET", "PRON", "ADJ", "NOUN", "PROPN", "NUM"):
            nominal = word
            while (
                nominal.dep_ in ("det", "poss", "amod", "compound", "nummod")
                and nominal.head.i != nominal.i
            ):
                nominal = nominal.head

            children = list(nominal.children)
            determined = any(c.dep_ in ("det", "poss") for c in children)
            expanded = any(
                c.dep_ in ("poss", "amod", "compound") for c in children
            )
            object_phrase = nominal.dep_ in ("dobj", "obj") or (
                nominal.dep_ in ("pobj", "obl") and expanded
            )

            if nominal.pos_ in ("NOUN", "PROPN") and determined and object_phrase:
                continuation = first_piece.get(sid, i) < i
                target = (
                    0.94 if continuation else
                    0.80 if dep in ("amod", "compound") else
                    0.66 if dep in ("det", "poss") else
                    0.58
                )
                available = float(attention[i, 1:i].sum())
                if target > attention[i, 0] and available > 0.0:
                    transfer = min(target - attention[i, 0], available)
                    attention[i, 1:i] *= (available - transfer) / available
                    attention[i, 0] += transfer

        if pos in ("VERB", "AUX"):
            last_predicate = i
        if dep in ("mark", "cc") or (is_punct and not terminal):
            last_boundary = i

    return "first_token_sink_with_nominal_interiors", attention


def prog_L7H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with a small diffuse causal background."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
        else:
            attention[i, 0] = 0.99
            attention[i, 1:i + 1] = 0.01 / i

    return "first_token_attention_sink", attention


def prog_L7H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink, with sparse dialogue-boundary and speaker-reentry links.
    Repeated quotations divert sink mass to earlier matching discourse boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.99 - 0.18 * (1.0 - np.exp(-(i - 1) / 45.0))

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 6.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    # Only activate for repeated direct speech; ordinary prose is unchanged.
    clean = [t.lstrip("Ġ").strip() for t in tokens]
    openings, closings = [], []
    in_quote = False
    for i, text in enumerate(clean):
        if any(q in text for q in ('"', '“', '”')):
            if in_quote:
                closings.append(i)
            else:
                openings.append(i)
            in_quote = not in_quote

    if len(openings) >= 2:
        doc = spacy_parse(sentence)
        aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)

        for i in range(1, n):
            targets = []
            prior_openings = [j for j in openings if j < i]
            prior_closings = [j for j in closings if j < i]

            if i in openings[1:]:
                # The next quotation's opening aligns with the first one's content.
                targets.append((openings[0] + 1, 0.27))

            elif clean[i] == "," and prior_openings and prior_closings:
                # A new speech-introducing comma retrieves the earlier opener.
                if i + 1 in openings:
                    targets.append((openings[0], 0.48))
                else:
                    targets.append((openings[0], 0.13))

            elif i in closings[1:]:
                # Closing dialogue retrieves the earlier return-to-narration boundary.
                boundary = closings[0] + 1
                if boundary < i and not clean[boundary]:
                    targets.append((boundary, 0.20))

            elif (
                i + 2 in openings
                and clean[i + 1] == ","
                and prior_openings
                and any(doc[k].pos_ == "VERB" for k in aligned[i])
            ):
                targets.append((openings[0], 0.17))

            elif (
                prior_closings
                and any(doc[k].pos_ == "DET" for k in aligned[i])
                and all(not clean[j] for j in range(prior_closings[-1] + 1, i))
            ):
                # On narrative reentry, retrieve an earlier nominal participant.
                boundary = prior_openings[-1]
                nouns = [
                    j for j in range(1, boundary)
                    if any(doc[k].pos_ == "NOUN" for k in aligned[j])
                ]
                subjects = [
                    j for j in nouns
                    if any(doc[k].dep_ in ("nsubj", "nsubjpass")
                           for k in aligned[j])
                ]
                if nouns:
                    target = subjects[-1] if subjects else nouns[-1]
                    targets.append((target, 0.20))

            # Transfer only from the sink: keep every self-attention weight and
            # all unrelated residual edges exactly as in the original.
            for j, mass in targets:
                if 0 < j < i:
                    delta = min(mass, attention[i, 0])
                    attention[i, 0] -= delta
                    attention[i, j] += delta

        return "first_token_sink_dialogue_boundaries", attention

    return "first_token_sink", attention


def prog_L8H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, strongest early and at phrase boundaries.
    Residual attention is weak, causal, and mildly recency-biased.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_boundary_bias", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = [doc[k] for k in alignment[i]]
        positions = {word.pos_ for word in aligned}

        sink = 0.95 - 0.16 * (1.0 - np.exp(-i / 15.0))

        if any(word.is_punct or word.is_space for word in aligned):
            sink += 0.055
        elif positions & {"NOUN", "PROPN"}:
            sink += 0.025
        elif positions & {"ADJ", "ADV"}:
            sink += 0.005
        elif positions & {"ADP", "DET", "PART", "SCONJ", "CCONJ"}:
            sink -= 0.065
        elif positions & {"VERB", "AUX"}:
            sink -= 0.025
        elif "PRON" in positions:
            sink -= 0.035

        # Standalone tokenizer whitespace also acts as a boundary.
        if not tokens[i].replace("Ġ", "").replace("Ċ", "").strip():
            sink += 0.045

        if i == 1:
            sink = 0.95

        sink = float(np.clip(sink, 0.60, 0.985))
        attention[i, 0] = sink

        distances = i - np.arange(1, i + 1)
        residual = 0.35 + np.exp(-distances / 6.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "first_token_sink_with_boundary_bias", attention


def prog_L8H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink, with sparse continuation retrieval in repeated dialogue.
    Dialogue-related transfers draw only from the sink, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 1.0 / (1.0 + 0.004 + 0.0015 * i + 0.00002 * i * i)

        # Residual attention is broadly distributed, with a mild recency bias.
        distances = i - np.arange(1, i + 1)
        background = 0.7 / i + 0.3 * (
            np.exp(-distances / 8.0)
            / np.exp(-distances / 8.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    # Activate only for multiple quoted turns; ordinary narration is unchanged.
    quotes = [
        i for i, token in enumerate(tokens)
        if any(c in token for c in ('"', '“', '”'))
    ]
    if len(quotes) >= 4:
        doc = spacy_parse(sentence)
        alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
        words = [
            next((doc[k] for k in indices if not doc[k].is_space), None)
            for indices in alignment
        ]

        for i in range(quotes[1] + 1, n):
            word = words[i]
            if word is None or word.is_space:
                continue

            targets = np.zeros(i, dtype=np.float64)
            transfer = 0.0

            # Repeated expressions retrieve the continuation of an earlier use.
            if word.pos_ in ("NOUN", "PROPN", "VERB", "ADJ", "DET", "PRON"):
                best_similarity = 0.80
                best_target = None
                for j in range(1, i - 3):
                    previous = words[j]
                    if previous is None or previous.pos_ != word.pos_:
                        continue
                    if words[j + 1] is None:
                        continue
                    if previous.i == words[j + 1].i:
                        continue
                    similarity = embedding_similarity(tokens, i, j, tokenizer)
                    if similarity > best_similarity:
                        best_similarity = similarity
                        best_target = j + 1

                if best_target is not None:
                    targets[best_target] = 1.0
                    strength = min(1.0, (best_similarity - 0.80) / 0.18)
                    transfer = strength * (
                        0.56 if word.pos_ == "VERB"
                        else 0.38 if word.pos_ in ("NOUN", "PROPN")
                        else 0.22
                    )

            # Turn and clause boundaries weakly retrieve earlier clause structure.
            boundary = (
                word.pos_ == "CCONJ"
                or (word.is_punct and any(c in tokens[i] for c in ',.!?"“”'))
            )
            if boundary and transfer == 0.0:
                for j in range(1, i):
                    previous = words[j]
                    if previous is None:
                        continue
                    if previous.pos_ in ("VERB", "AUX", "ADP", "PRON"):
                        targets[j] = np.exp(-(i - j) / 24.0)
                transfer = 0.18 if word.pos_ == "CCONJ" else 0.12

            if transfer > 0.0 and targets.sum() > 0.0:
                mass = min(transfer, attention[i, 0])
                attention[i, 0] -= mass
                attention[i, :i] += mass * targets / targets.sum()

    return "first_token_sink", attention


def prog_L8H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with gradual positional decay.
    Quotation boundaries and local syntactic context receive secondary attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_quote_backoff", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    latest_open = None
    inside_quote = False

    for i in range(n):
        text = tokens[i].lstrip("Ġ").replace("Ċ", "\n")
        aligned = alignment[i]
        word = doc[aligned[-1]] if aligned else None
        pos = word.pos_ if word is not None else ""
        is_modal = word is not None and word.tag_ == "MD"

        opens_quote = False
        for char in text:
            if char == "“":
                latest_open = i
                inside_quote = True
                opens_quote = True
            elif char == "”":
                inside_quote = False
            elif char == '"':
                if not inside_quote:
                    latest_open = i
                    opens_quote = True
                inside_quote = not inside_quote

        if i == 0:
            attention[0, 0] = 1.0
            continue

        sink = 0.12 + 0.85 * np.exp(-i / 30.0)
        if pos in ("NOUN", "PROPN"):
            sink += 0.055
        elif pos in ("ADJ", "PRON"):
            sink += 0.025
        elif pos in ("VERB", "AUX"):
            sink -= 0.025
        elif pos == "PUNCT":
            sink -= 0.10

        if inside_quote:
            sink -= 0.055
        if opens_quote:
            sink -= 0.055
        if is_modal and latest_open is not None:
            sink -= 0.22

        whitespace = not text.strip()
        if whitespace:
            sink -= 0.12

        sink = float(np.clip(sink, 0.16, 0.985))

        # Spread non-sink attention over causal context, favoring recency.
        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 5.0)

        if word is not None:
            head_index = word.head.i
            for j in range(1, i + 1):
                if head_index in alignment[j]:
                    residual[j - 1] += 0.8

        residual /= residual.sum()

        # Opening quotation marks act as secondary local attention sinks.
        if latest_open is not None and latest_open > 0:
            quote_fraction = 0.18
            if inside_quote:
                quote_fraction = 0.36
            if opens_quote:
                quote_fraction = 0.40
            if is_modal:
                quote_fraction = 0.58
            residual *= 1.0 - quote_fraction
            residual[latest_open - 1] += quote_fraction

        if whitespace:
            residual *= 0.45
            residual[-1] += 0.55

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "first_token_sink_with_quote_backoff", make_row_stochastic(attention)


def prog_L8H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with gradual positional weakening.
    Residual attention favors recent tokens and local syntactic heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        # The initial token acts as a sink regardless of its lexical identity.
        sink_mass = np.clip(0.979 - 0.004 * i, 0.68, 0.975)

        positions = np.arange(1, i + 1)
        residual = 0.35 + np.exp(-(i - positions) / 5.0)

        # A weak linguistic correction distributes non-sink attention.
        for k in alignment[i]:
            head = doc[k].head.i
            if head != k:
                for j in inverse[head]:
                    if 0 < j <= i:
                        residual[j - 1] += 0.75

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "first_token_sink_with_local_residual", attention


def prog_L8H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with object-to-verb attention.
    Within object phrases, nominal cues compete with the governing verb."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_nominal_competition", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    for i in range(n):
        if i == 0:
            attention[i, 0] = 1.0
            continue

        # Preserve the original causal background and self-attention.
        distances = i - np.arange(i + 1)
        background = np.exp(-distances / 4.0)
        background[0] = 0.0
        background /= background.sum()

        sink = 0.78
        target = None
        target_mass = 0.0
        indices = alignment[i]

        if indices:
            k = max(
                indices,
                key=lambda x: (not doc[x].is_space, len(doc[x].text))
            )
            word = doc[k]

            if word.pos_ in ("VERB", "AUX"):
                sink = 0.88
            elif word.pos_ in ("ADP", "SCONJ", "CCONJ"):
                sink = 0.83
            elif word.pos_ in ("NOUN", "PROPN", "PRON"):
                sink = 0.67
            elif word.pos_ in ("DET", "ADJ", "ADV", "NUM"):
                sink = 0.73

            if word.is_punct:
                sink = 0.93 if word.is_sent_end else 0.75
            elif word.is_space:
                sink = 0.86

            obj = word
            modifier = False
            if word.dep_ in ("det", "amod", "poss", "nummod", "compound"):
                obj = word.head
                modifier = True

            if (
                obj.dep_ in ("dobj", "obj", "iobj", "dative", "attr", "oprd")
                and obj.head.pos_ in ("VERB", "AUX")
            ):
                candidates = [
                    j for j in inverse[obj.head.i] if 0 < j < i
                ]
                if candidates:
                    target = candidates[0]
                    distance_factor = np.exp(-max(0, i - target - 4) / 12.0)
                    if modifier:
                        target_mass = 0.32 * distance_factor
                    elif obj.dep_ in ("attr", "oprd"):
                        target_mass = 0.20 * distance_factor
                    else:
                        target_mass = 0.76 * distance_factor
                    sink = min(sink, 0.94 - target_mass)

            if word.is_sent_start:
                sink = max(sink, 0.92)
                target_mass = min(target_mass, 1.0 - sink)

        if i == 1:
            sink = 0.96
            target_mass = 0.0

        residual = max(0.0, 1.0 - sink - target_mass)
        attention[i, :i + 1] = residual * background
        attention[i, 0] += sink
        if target is not None:
            attention[i, target] += target_mass

        # Only revise the explicit direct-object contribution; leave the
        # background, its decay, and the diagonal exactly as before.
        if (
            target is not None
            and target_mass > 0.0
            and obj.dep_ in ("dobj", "obj", "iobj", "dative")
        ):
            retained = 0.45 if modifier else 0.55
            pieces = inverse[word.i]
            if pieces and pieces[0] < i < pieces[-1]:
                retained = 0.02

            released = target_mass * (1.0 - retained)
            attention[i, target] -= released

            # Earlier determiners/adjectives can anchor a developing noun
            # phrase, but never redirect mass onto the current token.
            anchors = [
                j
                for child in obj.children
                if child.dep_ in ("det", "poss", "amod", "nummod")
                and child.i < word.i
                for j in inverse[child.i]
                if 0 < j < i
            ]
            nominal_mass = 0.4 * released if anchors else 0.0
            if anchors:
                attention[i, max(anchors)] += nominal_mass
            attention[i, 0] += released - nominal_mass

    return (
        "first_token_sink_with_nominal_competition",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L8H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with a discourse-onset reset after quotation boundaries.
    Preserve self-attention while redirecting some syntactic residual to the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_quote_reset", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    primary = []

    for i, indices in enumerate(aligned):
        usable = [k for k in indices if not doc[k].is_space]
        primary.append(usable[-1] if usable else None)
        for k in indices:
            inverse[k].append(i)

    # A quotation or a quoted sentence ending can begin a new discourse unit
    # even when the parser does not mark its first word as a sentence start.
    quote_seen = False
    reset_boundary = None

    attention[0, 0] = 1.0
    for i in range(1, n):
        si = primary[i]
        word = doc[si] if si is not None else None
        surface = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()

        sink = 0.22 + 0.74 * np.exp(-(i - 1) / 4.0)

        if word is not None:
            if word.pos_ in ("DET", "CCONJ", "SCONJ"):
                sink += 0.08
            elif word.pos_ in ("ADP", "PART"):
                sink -= 0.05
            elif word.pos_ in ("VERB", "ADV"):
                sink -= 0.03

            if word.is_sent_start:
                sink = max(sink, 0.72)
            if word.ent_type_ and word.pos_ == "PROPN":
                sink += 0.04
            if i > 1 and primary[i - 1] == si:
                sink += 0.12

        if not surface:
            sink = max(sink, 0.75)
        elif all(c in ".,;:!?\"'“”‘’()[]{}—–-" for c in surface):
            if any(c in ".!?" for c in surface):
                sink = max(sink, 0.75)
            elif any(c in "\"“”" for c in surface):
                sink = max(sink, 0.65)
            else:
                sink = max(sink, 0.48)

        if i == 1:
            first_si = primary[0]
            first_pos = doc[first_si].pos_ if first_si is not None else ""
            sink = 0.91 if first_pos == "PROPN" else 0.96

        sink = float(np.clip(sink, 0.08, 0.985))
        indices = np.arange(1, i + 1)
        weights = 0.025 + 0.13 * np.exp(-(i - indices) / 5.0)
        weights[-1] *= 0.65

        if word is not None:
            for j in range(1, i + 1):
                sj = primary[j]
                if sj is None:
                    continue
                candidate = doc[sj]
                distance = i - j

                if candidate.i == word.head.i and candidate.i != word.i:
                    weights[j - 1] += 0.85

                if candidate.head.i == word.i:
                    if candidate.dep_ in ("aux", "auxpass", "cop"):
                        weights[j - 1] += 2.6
                    elif candidate.dep_ in ("nsubj", "nsubjpass", "csubj"):
                        weights[j - 1] += 0.9
                    elif candidate.dep_ in ("amod", "advmod", "poss"):
                        weights[j - 1] += 0.25

                if word.pos_ in ("VERB", "NOUN", "ADJ", "ADP"):
                    if candidate.dep_ in ("nsubj", "nsubjpass"):
                        weights[j - 1] += 0.35 * np.exp(-distance / 14.0)

                if distance == 1 and candidate.pos_ == "AUX":
                    weights[j - 1] += 1.4

                if candidate.is_punct and distance <= 2:
                    weights[j - 1] += 0.12

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

        # Narrow override: discourse subjects, predicates, and vocatives near
        # a quotation boundary, not objects or arbitrary syntactic governors.
        if reset_boundary is not None and word is not None and i > 3:
            boundary_si = primary[reset_boundary]
            near_boundary = (
                0 < si - boundary_si <= 4
                if boundary_si is not None
                else 0 < i - reset_boundary <= 5
            )
            discourse_onset = (
                word.dep_ in ("nsubj", "nsubjpass", "csubj", "vocative")
                or (
                    word.pos_ in ("VERB", "AUX")
                    and word.dep_ in ("ROOT", "conj", "ccomp", "aux", "auxpass")
                )
                or (word.pos_ == "ADV" and word.dep_ == "advmod")
            )
            if near_boundary and discourse_onset and sink < 0.56:
                available = attention[i, 1:i].sum()
                transfer = min(0.60 - sink, 0.75 * available)
                if available > 0.0:
                    attention[i, 1:i] *= 1.0 - transfer / available
                    attention[i, 0] += transfer

        if any(c in "\"“”" for c in surface):
            quote_seen = True
            reset_boundary = i
        elif quote_seen and any(c in ".!?" for c in surface):
            reset_boundary = i

    return "first_token_sink_with_quote_reset", attention


def prog_L8H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with occasional local coordination/list links.
    Most queries attend overwhelmingly to position zero rather than a syntactic head.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_coordination", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_ends = {}
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            word_ends[wi] = ti

    attention[0, 0] = 1.0
    for i in range(1, n):
        # A small residual spread increases gradually in longer contexts.
        residual = 0.035 + min(0.10, 0.0015 * i)
        positions = np.arange(1, i + 1)
        weights = np.exp(-(i - positions) / 5.0)
        attention[i, 1:i + 1] = residual * weights / weights.sum()
        attention[i, 0] = 1.0 - residual

        word_ids = alignment[i]
        if not word_ids:
            continue
        current = doc[word_ids[-1]]
        previous = None
        for wi in range(current.i - 1, -1, -1):
            if not doc[wi].is_space and not doc[wi].is_punct:
                previous = doc[wi]
                break
        if previous is None:
            continue

        target = word_ends.get(previous.i)
        if target is None or target >= i:
            continue

        local_mass = 0.0
        if current.pos_ == "CCONJ":
            if previous.pos_ == "ADJ":
                local_mass = 0.55
            elif previous.pos_ in ("NOUN", "PROPN"):
                local_mass = 0.48
            else:
                local_mass = 0.12
        elif current.is_punct and current.text in (",", ";"):
            in_coordination = (
                previous.dep_ == "conj"
                or any(child.dep_ == "conj" for child in previous.children)
            )
            if in_coordination and previous.pos_ in ("NOUN", "PROPN", "ADJ"):
                local_mass = 0.65

        if local_mass:
            attention[i] *= 1.0 - local_mass
            attention[i, target] += local_mass

    return "first_token_sink_with_coordination", attention


def prog_L8H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with object governors; noun-phrase continuations
    share governor attention with preceding phrase modifiers and subwords."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "sink_governors_with_nominal_continuations", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    object_deps = {"dobj", "obj", "iobj", "pobj", "dative", "attr", "oprd"}
    subject_deps = {"nsubj", "nsubjpass", "csubj", "csubjpass", "expl"}
    nominal_links = {"det", "amod", "compound", "poss", "nummod", "quantmod"}

    attention[0, 0] = 1.0

    for i in range(1, n):
        # Preserve the original local residual and its decay.
        start = max(1, i - 7)
        for j in range(start, i + 1):
            attention[i, j] = np.exp(-0.65 * (i - j))
        attention[i] *= 0.025 / attention[i].sum()

        sink = 0.88
        anchor = None
        anchor_mass = 0.0

        indices = alignment[i]
        word = None
        if indices:
            word = doc[indices[-1]]
            for k in indices:
                if not doc[k].is_space and not doc[k].is_punct:
                    word = doc[k]
                    break

        if word is None or word.is_space:
            sink = 0.90
        elif word.is_punct:
            sink = 0.96 if any(c in tokens[i] for c in ".!?") else 0.83
        else:
            pos, dep = word.pos_, word.dep_
            if pos == "VERB":
                sink = 0.91
            elif pos == "AUX":
                sink = 0.80
            elif pos in {"CCONJ", "SCONJ", "PART"}:
                sink = 0.88
            elif pos == "ADP":
                sink = 0.79
            elif pos == "ADV":
                sink = 0.77
            elif pos in {"NOUN", "PROPN", "PRON", "DET", "ADJ", "NUM"}:
                sink = 0.66

            phrase = word
            visited = set()
            while (
                phrase.dep_ in nominal_links
                and phrase.head.i != phrase.i
                and phrase.i not in visited
            ):
                visited.add(phrase.i)
                phrase = phrase.head

            if phrase.dep_ in subject_deps:
                sink = 0.86 if pos == "PRON" else 0.68
            elif phrase.dep_ in object_deps:
                governor = phrase.head
                candidates = [j for j in inverse[governor.i] if 0 < j < i]
                if candidates and governor.pos_ in {"VERB", "AUX", "ADP"}:
                    anchor = candidates[-1]
                    if governor.pos_ == "ADP":
                        anchor_mass = 0.73
                    elif pos in {"DET", "PRON"} or dep == "poss":
                        anchor_mass = 0.61
                    else:
                        anchor_mass = 0.48
                    sink = 0.975 - anchor_mass

        if i == 1:
            sink = 0.965
            anchor = None
            anchor_mass = 0.0

        attention[i, 0] += sink
        if anchor is not None:
            attention[i, anchor] += anchor_mass

        remaining = max(0.0, 0.975 - sink - anchor_mass)
        attention[i, i - 1] += 0.75 * remaining
        attention[i, i] += 0.25 * remaining

        # Only nominal continuations change: preserve self-attention and
        # residual weights, transferring explicit sink/governor mass.
        if (
            i > 1
            and word is not None
            and word.pos_ in {"NOUN", "PROPN", "ADJ", "NUM"}
            and phrase.pos_ in {"NOUN", "PROPN", "PRON"}
        ):
            members = {phrase.i}
            members.update(
                child.i for child in phrase.children
                if child.dep_ in nominal_links
            )
            previous = sorted({
                j
                for k in members
                for j in inverse[k]
                if 0 < j < i and (anchor is None or j != anchor)
            })
            if previous:
                weights = np.exp(
                    -0.65 * (i - np.asarray(previous, dtype=np.float64))
                )
                weights /= weights.sum()

                moved = 0.0
                if anchor is not None:
                    transfer = 0.50 * anchor_mass
                    attention[i, anchor] -= transfer
                    if phrase.head.pos_ == "ADP":
                        # Some governor mass returns to the sink once the
                        # preposition's determiner has already been seen.
                        returned = min(0.08, transfer)
                        attention[i, 0] += returned
                        moved += transfer - returned
                    else:
                        moved += transfer
                        transfer = 0.25 * sink
                        attention[i, 0] -= transfer
                        moved += transfer
                else:
                    transfer = 0.28 * sink
                    attention[i, 0] -= transfer
                    moved += transfer

                attention[i, previous] += moved * weights

    return (
        "sink_governors_with_nominal_continuations",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L8H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, weakened by function words and discourse boundaries.
    Residual attention favors recent content, punctuation boundaries, and syntax."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_linguistic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    representatives = [
        next((doc[k] for k in indices if not doc[k].is_space), None)
        for indices in alignment
    ]
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    last_boundary = None
    in_quote = False

    for i in range(1, n):
        word = representatives[i]
        clean = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        pos = word.pos_ if word is not None else ""
        early = np.exp(-(i - 1) / 3.5)

        correction = 0.0
        if pos in ("NOUN", "PROPN"):
            correction = 0.17
        elif pos == "ADJ":
            correction = 0.15
        elif pos in ("VERB", "AUX"):
            correction = -0.06
        elif pos in ("DET", "ADP", "PART"):
            correction = -0.13
        elif pos in ("PRON", "CCONJ", "SCONJ"):
            correction = -0.18
        elif pos == "PUNCT":
            correction = -0.07

        sink = 0.61 + 0.34 * early + correction * (1.0 - early)
        if in_quote:
            sink -= 0.10 * (1.0 - early)
        if not clean:
            sink = 0.94
        sink = float(np.clip(sink, 0.30, 0.98))

        candidates = np.arange(1, i + 1)
        residual = np.exp(-(i - candidates) / 7.0)
        for j in candidates:
            target = representatives[j]
            if target is not None and target.pos_ in ("NOUN", "PROPN", "VERB", "ADJ"):
                residual[j - 1] *= 1.6

        residual[-1] *= 0.45
        if i > 1:
            residual[-2] += 0.8
        if last_boundary is not None:
            residual[last_boundary - 1] += 2.0

        if word is not None:
            for j in inverse[word.head.i]:
                if 0 < j < i:
                    residual[j - 1] += 1.8

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        if any(mark in clean for mark in (".", "!", "?")):
            last_boundary = i
        if clean.count('"') % 2:
            in_quote = not in_quote

    return "first_token_sink_with_linguistic_residual", attention


def prog_L8H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, strongest near the start, with weak
    punctuation-sensitive leakage into a recency-weighted causal background.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_leakage", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.62 + 0.36 * np.exp(-(i - 1) / 30.0)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[-1]]
            if word.pos_ == "PUNCT":
                sink_mass -= 0.12
                if word.text in (".", "!", "?", ";"):
                    sink_mass -= 0.13
            elif word.pos_ in ("NOUN", "PROPN", "VERB", "ADJ"):
                sink_mass += 0.025
            elif word.pos_ in ("DET", "CCONJ", "SCONJ"):
                sink_mass -= 0.035

        sink_mass = float(np.clip(sink_mass, 0.30, 0.985))
        attention[i, 0] = sink_mass

        # The examples identify the sink much more clearly than the
        # remaining targets; use a broad, weakly local residual prior.
        positions = np.arange(1, i + 1)
        background = 0.4 / i + 0.6 * np.exp(-(i - positions) / 8.0)
        background /= background.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * background

    return "first_token_sink_with_leakage", make_row_stochastic(attention)


def prog_L8H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Quoted speech strengthens the first-token sink; closing quotes can retrieve
    the preceding speaker, without changing the original self-attention weights.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "quoted_sink_speaker", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    # Track only explicit double-quotation boundaries. Unquoted text retains
    # the original behavior, including all original decay parameters.
    quoted = np.zeros(n, dtype=bool)
    closing_speaker = np.full(n, -1, dtype=int)
    in_quote = False
    speaker = -1
    last_subject = -1
    quote_chars = ('"', "\u201c", "\u201d", "\u00ab", "\u00bb")
    for i in range(n):
        surface = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")
        quote_count = sum(surface.count(c) for c in quote_chars)
        if quote_count % 2:
            if in_quote:
                closing_speaker[i] = speaker
                in_quote = False
            else:
                speaker = last_subject
                in_quote = True
        quoted[i] = in_quote
        if not in_quote and not quote_count:
            for k in alignment[i]:
                w = doc[k]
                if w.dep_ in ("nsubj", "nsubjpass") and w.pos_ in ("NOUN", "PROPN"):
                    if inverse[k]:
                        last_subject = inverse[k][0]

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[0]] if indices else None
        surface = tokens[i].replace("\u0120", " ").replace("\u010a", "\n")
        correction = 0.0

        if surface.isspace():
            correction += 0.22
        elif word is not None:
            if word.pos_ == "PROPN":
                correction += 0.09
            elif word.pos_ in ("VERB", "ADJ"):
                correction += 0.035
            elif word.pos_ in ("CCONJ", "SCONJ"):
                correction -= 0.09
            elif word.pos_ == "PUNCT":
                correction -= 0.045

            if word.ent_type_:
                correction += 0.025
            if inverse[word.i] and inverse[word.i][0] != i:
                correction += 0.12

        sink = 0.46 + 0.54 * np.exp(-i / 8.0)
        sink += correction * (1.0 - np.exp(-i / 3.0))
        sink = float(np.clip(sink, 0.25, 0.97))

        positions = np.arange(1, i + 1)
        residual = 0.45 / i + 0.55 * np.exp(-(i - positions) / 5.0)

        if word is not None:
            for j in inverse[word.head.i]:
                if 1 <= j <= i:
                    residual[j - 1] += 0.35

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

        # Move only off-diagonal mass: the original diagonal is unchanged.
        if quoted[i] and word is not None and word.pos_ != "PUNCT":
            available = float(attention[i, 1:i].sum())
            if available > 0.0:
                transfer = min(0.18, 0.75 * available)
                attention[i, 1:i] *= 1.0 - transfer / available
                attention[i, 0] += transfer
        elif 0 < closing_speaker[i] < i:
            transfer = min(0.24, 0.55 * attention[i, 0])
            attention[i, 0] -= transfer
            attention[i, closing_speaker[i]] += transfer

    return "quoted_sink_speaker", attention


def prog_L8H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, weakening mildly with distance.
    Residual attention is diffuse with a modest recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink_with_decay", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.80 + 0.20 * np.exp(-i / 16.0)
        positions = np.arange(1, i + 1)
        recent = np.exp(-(i - positions) / 4.0)
        residual = 0.5 / i + 0.5 * recent / recent.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_decay", attention


def prog_L9H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with weaker local and syntactic attention.
    Function-word queries and longer contexts slightly weaken the sink."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None

        sink = 0.91 - 0.10 * (1.0 - np.exp(-i / 35.0))
        if i == 1:
            sink = 0.985
        elif i <= 4:
            sink += 0.04

        if word is not None:
            if word.pos_ in ("AUX", "CCONJ", "SCONJ"):
                sink -= 0.13
            elif word.pos_ in ("PRON", "PART"):
                sink -= 0.09
            elif word.pos_ in ("DET", "ADP", "ADV"):
                sink -= 0.035
            elif word.pos_ == "PUNCT":
                sink += 0.035

        surface = tokens[i].replace("Ġ", " ").replace("Ċ", "\n")
        if not surface.strip():
            sink = max(sink, 0.95)
        elif surface.strip() in ('"', "'", '“', '”', '?"', '!"'):
            sink += 0.045

        sink = float(np.clip(sink, 0.60, 0.99))
        attention[i, 0] = sink

        positions = np.arange(1, i + 1)
        residual = 0.35 / i + 0.65 * np.exp(-(i - positions) / 5.0)

        if word is not None:
            for j in inverse[word.head.i]:
                if 0 < j <= i:
                    residual[j - 1] += 0.25

        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "first_token_sink", attention


def prog_L9H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with gradually increasing diffuse leakage
    to recent tokens as the sequence grows.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink_with_diffuse_leakage", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.80 + 0.19 * np.exp(-i / 75.0)
        positions = np.arange(1, i + 1)
        residual = np.exp((positions - i) / 12.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_diffuse_leakage", attention


def prog_L9H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, strongest near the start and on content words.
    Residual attention is weakly local, with a small syntactic-head preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for ti, word_ids in enumerate(alignment):
        for wi in word_ids:
            inverse[wi].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        word_ids = alignment[i]
        word = None
        if word_ids:
            word = doc[word_ids[-1]]
            for wi in word_ids:
                if not doc[wi].is_space:
                    word = doc[wi]
                    break

        # A sink rather than a specific lexical or dependency target.
        sink_logit = 1.85 + 2.0 * np.exp(-(i - 1) / 3.0)
        sink_logit -= 0.25 * (1.0 - np.exp(-i / 35.0))

        if word is not None:
            if word.pos_ in ("NOUN", "PROPN"):
                sink_logit += 0.55
            elif word.pos_ == "ADJ":
                sink_logit += 0.85
            elif word.pos_ in ("PRON", "AUX", "CCONJ", "SCONJ"):
                sink_logit -= 0.45
            elif word.pos_ == "PUNCT":
                sink_logit -= 0.10

            if word.ent_type_:
                sink_logit += 0.15
            if word.is_space:
                sink_logit += 0.65
        elif not tokens[i].lstrip("ĠĊ").strip():
            sink_logit += 0.65

        sink_mass = 1.0 / (1.0 + np.exp(-sink_logit))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 5.0)
        if word is not None:
            for target in inverse[word.head.i]:
                if 1 <= target <= i:
                    residual[target - 1] += 0.35

        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "first_token_sink", attention


def prog_L9H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with secondary quote and local phrase anchors.
    Clause boundaries favor the sink; phrase interiors favor their left boundary.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    matrix = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_and_phrase_anchors", matrix

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = [doc[ids[0]] if ids else None for ids in alignment]

    active_quote = None
    quote_marks = {'"', '“', '”', '«', '»'}
    opening_marks = {'“', '«'}
    closing_marks = {'”', '»'}

    for i, token in enumerate(tokens):
        text = token.lstrip("Ġ").lstrip("▁")
        word = words[i]
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        previous = words[i - 1] if i else None

        marks = [char for char in text if char in quote_marks]
        terminal = any(char in ".!?" for char in text)
        punctuation = bool(text) and all(
            not char.isalnum() and not char.isspace() for char in text
        )
        whitespace = not text.strip()

        closing_quote = bool(marks) and (
            active_quote is not None or any(c in closing_marks for c in marks)
        )

        if i == 0:
            matrix[0, 0] = 1.0
        else:
            sink = 0.49
            if i == 1:
                sink = 0.93
            elif i < 4:
                sink = 0.74 - 0.07 * (i - 2)

            if pos in ("VERB", "AUX"):
                sink = max(sink, 0.64)
            if pos == "CCONJ":
                sink = max(sink, 0.58)
            if dep in ("ROOT", "conj") and pos in ("VERB", "AUX"):
                sink = max(sink, 0.69)
            if punctuation:
                sink = max(sink, 0.63)
            if whitespace:
                sink = max(sink, 0.63)
            if terminal or closing_quote:
                sink = max(sink, 0.83)

            anchor = None
            anchor_mass = 0.0

            if previous is not None:
                previous_pos = previous.pos_
                if previous_pos in ("VERB", "AUX", "ADP") and pos in (
                    "DET", "PRON", "ADJ", "NOUN", "PROPN"
                ):
                    anchor = i - 1
                    anchor_mass = 0.43
                elif previous_pos == "DET" and pos in ("ADJ", "NOUN", "PROPN"):
                    anchor = i - 1
                    anchor_mass = 0.36
                elif previous.dep_ == "poss" and pos in ("NOUN", "PROPN"):
                    anchor = i - 1
                    anchor_mass = 0.38
                elif punctuation and not terminal and previous_pos in (
                    "NOUN", "PROPN"
                ):
                    anchor = i - 1
                    anchor_mass = 0.32

            if active_quote is not None and not punctuation and not whitespace:
                anchor = active_quote
                anchor_mass = 0.53
                if i == active_quote + 1:
                    anchor_mass = 0.66
                sink = min(sink, 0.29)
            elif anchor is not None and i > 1 and not terminal:
                sink = min(sink, 0.40)

            if sink + anchor_mass > 0.94:
                anchor_mass = max(0.0, 0.94 - sink)

            # A weak causal recency background models unreported smaller edges.
            distances = i - np.arange(i + 1)
            background = np.exp(-distances / 4.0)
            background /= background.sum()
            matrix[i, :i + 1] = (
                1.0 - sink - anchor_mass
            ) * background
            matrix[i, 0] += sink
            if anchor is not None:
                matrix[i, anchor] += anchor_mass

        # Update after constructing the row: an opening quote is a boundary,
        # not an anchor for its own query.
        for mark in marks:
            if mark in opening_marks:
                active_quote = i
            elif mark in closing_marks:
                active_quote = None
            elif active_quote is None:
                active_quote = i
            else:
                active_quote = None

    return (
        "first_token_and_phrase_anchors",
        make_row_stochastic(apply_causal_mask(matrix)),
    )


def prog_L9H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with a small causal-local residual.
    Sink strength weakens mildly with distance and at syntactic boundaries.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.975 - 0.10 * i / (i + 35.0)

        if alignment[i]:
            word = doc[alignment[i][0]]
            if word.pos_ == "PUNCT":
                sink_mass -= 0.14
            elif word.pos_ in ("DET", "ADJ", "ADV", "AUX"):
                sink_mass += 0.012
            elif word.pos_ == "VERB":
                sink_mass -= 0.025

        sink_mass = np.clip(sink_mass, 0.65, 0.995)

        # Allocate the non-sink mass locally, excluding the sink itself.
        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 3.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink", attention


def prog_L9H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, strongest early in the sequence,
    with a small recency-weighted residual over other causal positions.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink_with_local_residual", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.80 + 0.18 * np.exp(-(i - 1) / 7.0)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = np.exp(-distances / 3.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "first_token_sink_with_local_residual", attention


def prog_L9H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with small recency-biased leakage that
    gradually increases with distance from the sequence start."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink_with_local_leakage", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        leakage = min(0.20, 0.006 + 0.002 * i)
        positions = np.arange(1, i + 1)
        local_weights = np.exp(-(i - positions) / 8.0)
        local_weights /= local_weights.sum()

        attention[i, 0] = 1.0 - leakage
        attention[i, 1:i + 1] = leakage * (
            0.75 * local_weights + 0.25 / i
        )

    return "first_token_sink_with_local_leakage", attention


def prog_L9H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with a gradually increasing local/syntactic residual.
    Clause-ending punctuation shifts some mass toward recent content words.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos = [""] * n
    dep = [""] * n
    word_index = [-1] * n
    for i, indices in enumerate(alignment):
        if indices:
            k = indices[-1]
            word_index[i] = k
            pos[i] = doc[k].pos_
            dep[i] = doc[k].dep_

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.970 - 0.050 * np.log(float(i)) - 0.0018 * i

        if pos[i] in ("ADJ", "ADV", "PROPN"):
            sink_mass += 0.035
        elif pos[i] in ("VERB", "AUX"):
            sink_mass -= 0.025
        elif pos[i] == "PUNCT":
            sink_mass -= 0.100

        # Early queries are almost entirely absorbed by the positional sink.
        if i <= 3:
            sink_mass = max(sink_mass, 0.975 - 0.024 * i)

        sink_mass = float(np.clip(sink_mass, 0.35, 0.985))
        residual = np.zeros(i, dtype=np.float64)
        source_word = word_index[i]

        for j in range(1, i + 1):
            distance = i - j
            weight = np.exp(-distance / 6.0) + 0.025

            if pos[j] in ("NOUN", "PROPN", "VERB"):
                weight *= 1.35
            if dep[j] == "ROOT":
                weight *= 1.3
            if pos[j] in ("PUNCT", "SPACE"):
                weight *= 0.45

            target_word = word_index[j]
            if source_word >= 0 and target_word >= 0:
                if doc[source_word].head.i == target_word:
                    weight *= 1.8
                if source_word == target_word and j < i:
                    weight *= 1.4

            if pos[i] == "PUNCT" and pos[j] in ("NOUN", "PROPN"):
                weight *= 2.0

            residual[j - 1] = weight

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "first_token_sink_with_local_residual", attention


def prog_L9H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with mild positional weakening and POS modulation.
    Remaining attention is diffuse and weakly biased toward recent tokens.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.98 - 0.04 * np.log1p(i)

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[0]]
            if word.pos_ in ("NOUN", "PROPN"):
                sink_mass += 0.045
            elif word.pos_ == "ADJ":
                sink_mass += 0.025
            elif word.pos_ == "PRON":
                sink_mass += 0.015
            elif word.pos_ in ("DET", "ADP", "PART", "CCONJ", "SCONJ"):
                sink_mass -= 0.035
            elif word.pos_ == "PUNCT":
                sink_mass -= 0.065

        sink_mass = float(np.clip(sink_mass, 0.65, 0.99))
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.7 / i + 0.3 * (
            np.exp(-distances / 5.0) /
            np.exp(-distances / 5.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink", attention


def prog_L9H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with weak causal leakage increasing with distance.
    Residual attention is diffuse, with a modest recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        leakage_odds = 0.003 + 0.00004 * i * i
        sink_mass = 1.0 / (1.0 + leakage_odds)

        positions = np.arange(1, i + 1)
        residual = 0.7 / i + 0.3 * (
            np.exp(-(i - positions) / 5.0)
            / np.exp(-(i - positions) / 5.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink", attention


def prog_L9H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with local predicate–argument and recency corrections."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_local_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None
        sink = 0.77
        target = i - 1
        strength = 0.65

        if word is not None:
            pos, dep = word.pos_, word.dep_

            if pos in ("VERB", "AUX"):
                sink = 0.86
                if word.tag_ in ("VB", "VBG", "VBN"):
                    sink = 0.70
                # An auxiliary can bind locally to an immediately preceding subject.
                if pos == "AUX" and i > 2:
                    previous = alignment[i - 1]
                    if previous:
                        subject = doc[previous[-1]]
                        if subject.dep_ in ("nsubj", "nsubjpass", "csubj"):
                            sink = 0.43
                            strength = 0.88

            elif pos in ("NOUN", "PROPN"):
                sink = 0.55
                if dep in ("dobj", "obj", "iobj", "dative", "pobj", "attr", "oprd"):
                    sink = 0.34
                    candidates = [j for j in inverse[word.head.i] if 0 < j < i]
                    if candidates:
                        target = candidates[-1]
                        strength = 0.88

            elif pos == "PRON":
                sink = 0.65
                if dep in ("dobj", "obj", "iobj", "dative", "pobj"):
                    sink = 0.35
                    candidates = [j for j in inverse[word.head.i] if 0 < j < i]
                    if candidates:
                        target = candidates[-1]
                        strength = 0.90
                elif dep in ("nsubj", "nsubjpass"):
                    sink = 0.77

            elif pos == "ADJ":
                sink = 0.60
            elif pos == "ADV":
                sink = 0.70
            elif pos in ("DET", "ADP", "PART"):
                sink = 0.75
            elif pos in ("SCONJ", "CCONJ"):
                sink = 0.88
            elif pos == "PUNCT":
                sink = 0.79
                if any(c in ".!?" for c in word.text):
                    sink = 0.84

            # Continuation pieces tend to fall back to the attention sink.
            if inverse[word.i] and inverse[word.i][0] < i:
                sink = max(sink, 0.87)

            # New clauses and sentence openings strengthen the default sink.
            if word.is_sent_start:
                sink = max(sink, 0.91)

        if not tokens[i].strip("ĠĊ \t\r\n"):
            sink = 0.89

        # The first few positions show an especially strong first-token prior.
        if i == 1:
            sink = 0.95
        elif i == 2:
            sink = max(sink, 0.85)

        attention[i, 0] = sink
        remainder = 1.0 - sink
        attention[i, target] += remainder * strength

        positions = np.arange(1, i + 1)
        recency = np.exp(-(i - positions) / 2.0)
        recency /= recency.sum()
        attention[i, 1:i + 1] += remainder * (1.0 - strength) * recency

    return "first_token_sink_with_local_syntax", make_row_stochastic(attention)


def prog_L9H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with gradually increasing causal leakage.
    Residual attention mixes a diffuse background with a weak recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink_with_leakage", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        # Early rows are almost entirely absorbed by the first token.
        # More available keys and increasing distance gradually weaken it.
        leakage_odds = 0.0018 * i * np.exp(min(i / 45.0, 20.0))
        sink_mass = 1.0 / (1.0 + leakage_odds)

        distances = i - np.arange(1, i + 1)
        residual = 0.7 / i + 0.3 * (
            np.exp(-distances / 6.0)
            / np.exp(-distances / 6.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_leakage", attention


def prog_L10H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, weakening with position and function-word queries.
    Residual attention favors nearby tokens and the opening nominal anchor.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_linguistic_modulation", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)

    pos = []
    for indices in alignment:
        candidates = [doc[k] for k in indices if not doc[k].is_space]
        pos.append(candidates[-1].pos_ if candidates else "")

    anchor = None
    for j in range(1, min(n, 8)):
        if pos[j] in ("NOUN", "PROPN", "PRON"):
            anchor = j
            break

    attention[0, 0] = 1.0
    for i in range(1, n):
        logit = 3.95 - 0.040 * i

        if pos[i] in ("NOUN", "PROPN", "VERB"):
            logit += 0.25
        elif pos[i] == "ADJ":
            logit += 0.55
        elif pos[i] in ("DET", "CCONJ", "SCONJ", "PART"):
            logit -= 0.65
        elif pos[i] in ("AUX", "ADP", "ADV", "PRON"):
            logit -= 0.25
        elif pos[i] == "PUNCT":
            logit -= 0.75

        sink_mass = 1.0 / (1.0 + np.exp(-logit))

        # A later sentence-opening determiner can retrieve the initial noun.
        restart = (
            pos[i] == "DET"
            and alignment[i]
            and doc[alignment[i][-1]].is_sent_start
            and anchor is not None
            and anchor < i
        )
        if restart:
            sink_mass *= 0.65

        destinations = np.arange(1, i + 1)
        residual = np.exp(-(i - destinations) / 6.0)
        residual /= residual.sum()

        if anchor is not None and anchor <= i:
            anchor_share = 0.75 if restart else 0.25
            residual *= 1.0 - anchor_share
            residual[anchor - 1] += anchor_share

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_linguistic_modulation", attention


def prog_L10H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with weak causal leakage.
    The initial token dominates, with modest dilution as context grows.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.99 / (1.0 + 0.0025 * (i - 1))
        positions = np.arange(1, i + 1)
        background = 1.0 + 0.5 * np.exp(-(i - positions) / 5.0)
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * background / background.sum()
        )

    return "first_token_sink", attention


def prog_L10H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, gradually weakening with position.
    Residual attention favors nearby tokens and available syntactic heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_local_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        # The absolute initial position dominates regardless of its word or POS.
        sink_logit = 4.7 - 0.85 * np.log1p(i) - 0.012 * i
        indices = alignment[i]
        word = None
        for k in indices:
            if not doc[k].is_space:
                word = doc[k]
                break

        if word is not None:
            if word.pos_ in ("DET", "ADP", "CCONJ", "SCONJ"):
                sink_logit += 0.12
            elif word.pos_ in ("NOUN", "PROPN", "VERB"):
                sink_logit -= 0.10

        if tokens[i].isspace() or tokens[i] == "\u0120":
            sink_logit += 0.35

        sink_mass = 1.0 / (1.0 + np.exp(-sink_logit))
        attention[i, 0] = sink_mass

        # Allocate the small non-sink component only to accessible positions.
        positions = np.arange(1, i + 1)
        residual = 0.25 + np.exp(-(i - positions) / 5.0)
        residual[-1] += 0.35

        if word is not None:
            head_positions = inverse[word.head.i]
            for j in head_positions:
                if 1 <= j <= i:
                    residual[j - 1] += 0.5

        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "first_token_sink_with_local_residual", make_row_stochastic(attention)


def prog_L10H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, gradually weakening with position.
    Residual attention is diffuse and local, with a small syntactic-head bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = doc[alignment[i][-1]] if alignment[i] else None

        sink = 0.975 - 0.42 * (1.0 - np.exp(-(i - 1) / 30.0))
        if word is not None:
            if word.pos_ in ("NOUN", "PROPN", "PRON"):
                sink += 0.015
            elif word.pos_ == "PUNCT":
                sink -= 0.055
                if word.is_sent_end:
                    sink -= 0.10
            if word.is_space:
                sink += 0.10
        elif not tokens[i].replace("\u0120", "").replace("\u010a", "").strip():
            sink += 0.10

        sink = float(np.clip(sink, 0.35, 0.995))

        positions = np.arange(1, i + 1)
        residual = 0.4 / i + 0.6 * np.exp(-(i - positions) / 6.0)
        if word is not None and word.head.i != word.i:
            head_positions = [j for j in inverse[word.head.i] if 0 < j <= i]
            if head_positions:
                for j in head_positions:
                    residual[j - 1] += 0.25 / len(head_positions)

        residual /= residual.sum()
        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * residual

    return "first_token_sink_with_decay", attention


def prog_L10H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with quotation-boundary anchors.
    Local syntactic and punctuation links compete with the sink in longer discourse.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_quote_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for k in indices:
            inverse[k].append(i)

    active_quote = None
    last_quote_end = None
    quote_count = 0
    closing_marks = {'"', '”', '»', '‟'}
    opening_marks = {'"', '“', '«', '„'}

    for i, raw in enumerate(tokens):
        clean = raw.replace("Ġ", " ").replace("Ċ", "\n").strip()
        words = [doc[k] for k in aligned[i]]
        word = max(words, key=lambda w: not w.is_punct) if words else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        opens = False
        closes = False
        for char in clean:
            if char in opening_marks or char in closing_marks:
                if active_quote is None:
                    if char in opening_marks:
                        opens = True
                else:
                    closes = True

        prior_quotes = quote_count
        if opens:
            quote_count += 1

        # Repeated discourse boundaries make the initial sink less exclusive.
        complexity = min(1.0, prior_quotes / 2.0)
        progress = 1.0 - np.exp(-i / 18.0)
        sink = 0.92 - 0.38 * complexity * progress
        if i <= 3:
            sink += 0.035
        sink = min(0.975, max(0.48, sink))

        row = np.zeros(n, dtype=np.float64)
        row[0] = sink

        # Residual attention is mostly local, with a small diffuse causal tail.
        residual = 1.0 - sink
        distances = i - np.arange(i + 1)
        local = np.exp(-distances / 3.0)
        local /= local.sum()
        row[:i + 1] += residual * (0.75 * local + 0.25 / (i + 1))

        if word is not None and i > 0:
            head_tokens = inverse[word.head.i]
            eligible = [j for j in head_tokens if 0 < j < i]
            if eligible and dep not in ("ROOT", "punct"):
                strength = 0.04 + 0.10 * complexity
                row *= 1.0 - strength
                row[eligible[-1]] += strength

        # Inside speech, later predicates and objects favor its opening marker.
        if active_quote is not None and not closes and i > active_quote:
            distance = i - active_quote
            strength = 0.12 + 0.24 * (1.0 - np.exp(-(distance - 1) / 3.0))
            if dep in ("dobj", "obj", "pobj", "attr", "oprd"):
                strength += 0.26
            if pos == "VERB" and dep in ("ROOT", "conj", "ccomp", "xcomp"):
                strength += 0.29
            if pos == "AUX":
                strength += 0.06
            if distance == 1:
                strength = 0.06
            strength = min(0.82, strength)
            row *= 1.0 - strength
            row[active_quote] += strength

        # List separators and coordination often retain the preceding content.
        if i > 0 and (clean in (",", ";") or pos == "CCONJ"):
            previous_content = None
            for j in range(i - 1, max(-1, i - 5), -1):
                if any(doc[k].pos_ in ("NOUN", "PROPN", "ADJ")
                       for k in aligned[j]):
                    previous_content = j
                    break
            if previous_content is not None:
                strength = 0.05 + 0.40 * complexity
                row *= 1.0 - strength
                row[previous_content] += strength
            elif clean == "," and last_quote_end is not None:
                strength = 0.42
                row *= 1.0 - strength
                row[last_quote_end] += strength

        attention[i] = row
        if closes:
            active_quote = None
            last_quote_end = i
        elif opens:
            active_quote = i

    return (
        "first_token_sink_with_quote_anchors",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L10H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with a phrase-completion exception: content heads
    redirect some sink mass to preceding syntactic anchors and modifiers.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_phrase_completion", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_tokens = [[] for _ in doc]
    for ti, aligned in enumerate(alignment):
        for wi in aligned:
            word_tokens[wi].append(ti)

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink = 0.83
        aligned = alignment[i]
        if aligned:
            word = doc[aligned[-1]]
            pos = word.pos_
            dep = word.dep_

            if pos == "DET" or dep in ("det", "poss"):
                sink = 0.965
            elif pos == "ADJ":
                sink = 0.945 if dep == "amod" else 0.73
            elif pos in ("ADP", "PART"):
                sink = 0.91
            elif pos == "AUX":
                sink = 0.92
            elif pos in ("CCONJ", "SCONJ"):
                sink = 0.89
            elif pos == "ADV":
                sink = 0.87
            elif pos == "VERB":
                sink = 0.85
            elif pos == "PRON":
                sink = 0.83
            elif pos in ("NOUN", "PROPN"):
                sink = 0.70
            elif pos in ("PUNCT", "SPACE"):
                sink = 0.65

        if i == 1:
            sink = max(sink, 0.95)

        # Preserve the original residual distribution, including self-attention.
        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 + np.exp(-distances / 4.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()
        attention[i, 0] = sink

        # Only phrase-completing content tokens take this additional path.
        if aligned and i >= 3:
            nominal = pos in ("NOUN", "PROPN") and dep in (
                "dobj", "obj", "pobj", "iobj", "poss", "conj"
            )
            object_pronoun = pos == "PRON" and dep in ("dobj", "obj", "iobj")
            predicate_adjective = pos == "ADJ" and dep in ("acomp", "attr")
            if (
                (nominal or object_pronoun or predicate_adjective)
                and word_tokens[word.i][-1] == i
            ):
                anchors = np.zeros(n, dtype=np.float64)
                candidates = []
                for child in word.children:
                    if child.dep_ in ("det", "poss", "amod", "advmod", "compound"):
                        candidates.append((child, 1.0))

                ancestor = word.head
                for depth in range(3):
                    if ancestor.i == word.i:
                        break
                    if ancestor.i < word.i:
                        candidates.append((ancestor, 1.4 / (depth + 1)))
                        for child in ancestor.children:
                            if child.dep_ in ("aux", "auxpass", "cop"):
                                candidates.append((child, 2.0 / (depth + 1)))
                            elif object_pronoun and child.dep_ in ("nsubj", "nsubjpass"):
                                candidates.append((child, 1.5))
                    if ancestor.head.i == ancestor.i:
                        break
                    ancestor = ancestor.head

                for candidate, weight in candidates:
                    preceding = [j for j in word_tokens[candidate.i] if 0 < j < i]
                    if preceding:
                        anchors[preceding[-1]] += weight

                if anchors.sum() > 0:
                    transfer = 0.45 if object_pronoun else (
                        0.32 if predicate_adjective else 0.40
                    )
                    if nominal and dep == "poss":
                        transfer = 0.55
                    transfer = min(transfer, attention[i, 0])
                    attention[i, 0] -= transfer
                    attention[i] += transfer * anchors / anchors.sum()

    return "first_token_sink_phrase_completion", make_row_stochastic(attention)


def prog_L10H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with modest position-dependent leakage.
    Residual attention mixes a diffuse causal background with recency."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.80 + 0.19 * np.exp(-(i - 1) / 80.0)
        distances = i - np.arange(1, i + 1)
        residual = 0.5 / i + 0.5 * (
            np.exp(-distances / 3.0)
            / np.exp(-distances / 3.0).sum()
        )
        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink", attention


def prog_L10H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with content fallback; ordinary punctuation retains the
    sink, unlike enumeration separators and later quoted-discourse boundaries."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_boundary_guard", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_starts = {}
    aligned_words = []
    for i, indices in enumerate(alignment):
        valid = [k for k in indices if not doc[k].is_space]
        k = valid[-1] if valid else None
        aligned_words.append(k)
        for sid in valid:
            if sid not in word_starts:
                word_starts[sid] = i

    content_pos = {"NOUN", "PROPN", "ADJ", "VERB"}
    nominal_pos = {"NOUN", "PROPN", "PRON"}
    initial_anchor = None
    for word in doc:
        if word.dep_ in {"nsubj", "nsubjpass", "csubj"}:
            initial_anchor = word_starts.get(word.i)
            if initial_anchor is not None:
                break

    has_quotes = any(c in sentence for c in '"“”')
    earlier_terminal = False

    attention[0, 0] = 1.0
    for i in range(1, n):
        sid = aligned_words[i]
        word = doc[sid] if sid is not None else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        sink = 0.94 - 0.22 * (1.0 - np.exp(-i / 28.0))
        if pos in {"NOUN", "PROPN", "ADJ"}:
            sink += 0.035
        elif pos in {"ADP", "CCONJ", "SCONJ", "PART"}:
            sink -= 0.12

        clean = tokens[i].replace("Ġ", "").replace("Ċ", "").strip()
        if not clean:
            sink = max(sink, 0.92)

        continuation = (
            sid is not None and i > 0 and aligned_words[i - 1] == sid
        )
        if continuation:
            sink = max(sink, 0.90)

        prior = np.zeros(i + 1, dtype=np.float64)
        prior[i] = 0.15
        prior[i - 1] += 0.35

        if word is not None:
            head_index = word_starts.get(word.head.i)
            if head_index is not None and 0 < head_index < i:
                prior[head_index] += 1.3

        recent_content = None
        recent_nominal = None
        for j in range(i - 1, 0, -1):
            previous_sid = aligned_words[j]
            if previous_sid is None:
                continue
            previous = doc[previous_sid]
            start = word_starts.get(previous_sid, j)
            if recent_content is None and previous.pos_ in content_pos:
                recent_content = start
            if recent_nominal is None and previous.pos_ in nominal_pos:
                recent_nominal = start
            if recent_content is not None and recent_nominal is not None:
                break

        if recent_content is not None:
            prior[recent_content] += 0.8

        is_punctuation = word is not None and word.is_punct
        if is_punctuation:
            terminal = any(c in clean for c in ".!?")
            sink = min(sink, 0.30 if terminal else 0.60)
            target = recent_nominal if terminal else recent_content
            if target is not None:
                prior[target] += 5.0

        if pos == "CCONJ" and recent_content is not None:
            sink = min(sink, 0.40)
            prior[recent_content] += 6.0

        if (
            pos == "DET"
            and word is not None
            and word.is_sent_start
            and initial_anchor is not None
            and 0 < initial_anchor < i
        ):
            sink = 0.36
            prior[initial_anchor] += 10.0

        if dep == "poss":
            sink -= 0.04

        sink = float(np.clip(sink, 0.15, 0.98))
        prior[0] = 0.0
        total = prior.sum()
        if total > 0:
            attention[i, :i + 1] = (1.0 - sink) * prior / total
            attention[i, 0] = sink
        else:
            attention[i, 0] = 1.0

        # Correct only ordinary punctuation's exaggerated content fallback.
        # Preserve enumeration and quoted-discourse endings, where retrieval
        # can genuinely dominate. The original diagonal remains untouched.
        if is_punctuation:
            previous = doc[sid - 1] if sid > 0 else None
            following = doc[sid + 1] if sid + 1 < len(doc) else None
            enumeration = (
                clean in {",", ";"}
                and previous is not None
                and following is not None
                and previous.pos_ in nominal_pos | {"ADJ"}
                and following.pos_ in nominal_pos | {"ADJ", "DET", "CCONJ"}
                and (
                    previous.dep_ == "conj"
                    or any(child.dep_ == "conj" for child in previous.children)
                )
            )
            ordinary_boundary = not has_quotes or (
                not earlier_terminal and not terminal
            )
            if ordinary_boundary and not enumeration:
                desired_sink = (
                    0.93 if any(c in clean for c in '"“”')
                    else 0.81 if terminal
                    else 0.83
                )
                available = float(attention[i, 1:i].sum())
                transfer = min(
                    available, max(0.0, desired_sink - attention[i, 0])
                )
                if available > 0.0:
                    attention[i, 1:i] *= (available - transfer) / available
                    attention[i, 0] += transfer

            earlier_terminal = earlier_terminal or terminal

    return "first_token_sink_with_boundary_guard", make_row_stochastic(attention)


def prog_L10H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with gradual positional dilution.
    Small residual attention spreads over the causal prefix with a recency bias.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    for i in range(n):
        if i == 0:
            attention[0, 0] = 1.0
            continue

        sink_mass = 0.985 / (1.0 + 0.0025 * i)
        surface = tokens[i].replace("Ġ", " ").replace("Ċ", "\n").strip()
        if surface and all(not c.isalnum() for c in surface):
            sink_mass -= 0.035

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.5 / i + 0.5 * (
            np.exp(-(i - positions) / 7.0)
            / np.exp(-(i - positions) / 7.0).sum()
        )

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_positional_dilution", attention


def prog_L10H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with POS-dependent strength and a residual
    preference for nearby syntactic governors and phrase anchors.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_syntactic_residual", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            inverse[k].append(i)

    attention[0, 0] = 1.0
    strengths = {
        "DET": 0.89,
        "PRON": 0.91,
        "AUX": 0.86,
        "PART": 0.83,
        "PROPN": 0.80,
        "ADJ": 0.78,
        "VERB": 0.70,
        "NOUN": 0.65,
        "ADP": 0.73,
        "ADV": 0.66,
        "CCONJ": 0.72,
        "SCONJ": 0.78,
        "PUNCT": 0.62,
        "SPACE": 0.60,
    }

    for i in range(1, n):
        word = doc[alignment[i][-1]] if alignment[i] else None
        sink = strengths.get(word.pos_, 0.76) if word is not None else 0.76

        if word is not None:
            if word.dep_ in ("nsubj", "nsubjpass", "csubj", "poss"):
                sink = max(sink, 0.90)
            elif word.dep_ in ("dobj", "obj", "pobj", "attr"):
                sink -= 0.12

        # Early positions exhibit an especially strong first-token prior.
        sink += 0.10 * np.exp(-(i - 1) / 3.0)
        sink = float(np.clip(sink, 0.43, 0.97))

        residual = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        residual[1:] = np.exp(-(i - positions) / 2.5)
        residual[i] *= 0.40

        if word is not None:
            head = word.head
            if head.i != word.i:
                candidates = [j for j in inverse[head.i] if 0 < j < i]
                if candidates:
                    residual[candidates[-1]] += 2.5

                # Prepositional objects can point back to the containing phrase.
                if head.pos_ == "ADP" and head.head.i != head.i:
                    candidates = [
                        j for j in inverse[head.head.i] if 0 < j < i
                    ]
                    if candidates:
                        residual[candidates[-1]] += 3.0

            # Split lexical items retain a small within-word connection.
            earlier_pieces = [j for j in inverse[word.i] if 0 < j < i]
            if earlier_pieces:
                residual[earlier_pieces[-1]] += 1.0

        residual /= residual.sum()
        attention[i, :i + 1] = (1.0 - sink) * residual
        attention[i, 0] = sink

    return "first_token_sink_with_syntactic_residual", make_row_stochastic(attention)


def prog_L10H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with slowly increasing causal leakage.
    Initial-token POS weakly modulates sink strength; leakage favors recency.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_leakage", attention

    doc = spacy_parse(sentence)
    initial_pos = doc[0].pos_ if len(doc) else ""
    rate = 0.006 if initial_pos == "DET" else 0.0035

    attention[0, 0] = 1.0
    for i in range(1, n):
        leakage_odds = rate * (i ** 0.9)
        if initial_pos == "DET":
            leakage_odds += 0.012 * np.exp(-i / 6.0)

        sink_mass = 1.0 / (1.0 + leakage_odds)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = 0.4 / i + 0.6 * (
            np.exp(-distances / 5.0)
            / np.exp(-distances / 5.0).sum()
        )
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_leakage", attention


def prog_L10H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with weak, linguistically modulated local attention."""
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        pos = doc[aligned[-1]].pos_ if aligned else ""

        sink_mass = 0.94
        if pos in ("NOUN", "PROPN", "PRON", "DET"):
            sink_mass = 0.91
        elif pos in ("VERB", "ADJ", "ADV"):
            sink_mass = 0.96
        elif tokens[i].strip("ĠĊ \t\r\n") == "":
            sink_mass = 0.97

        # Longer contexts allow a little more non-sink structure.
        sink_mass -= 0.07 * (1.0 - np.exp(-i / 45.0))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1)
        residual = np.exp(-(i - positions) / 5.0) + 0.05
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "first_token_sink", attention


def prog_L11H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """A first-token sink mixed with diffuse early-context attention and self-attention.
    Punctuation favors itself; fragmented words and isolated spaces favor the sink.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_diffuse_context", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    word_counts = np.zeros(len(doc), dtype=np.int64)
    for indices in alignment:
        for index in indices:
            word_counts[index] += 1

    positions = np.arange(n, dtype=np.float64)

    for i, token in enumerate(tokens):
        if i == 0:
            attention[0, 0] = 1.0
            continue

        indices = alignment[i]
        word = doc[indices[0]] if indices else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""
        clean = token.replace("\u0120", " ").replace("\u010a", "\n")
        whitespace = bool(clean) and clean.isspace()
        punctuation = (
            bool(clean.strip())
            and all(not ch.isalnum() for ch in clean.strip())
        )

        j = positions[:i + 1]
        weights = (
            0.70 * np.exp(-j / 5.0)
            + 0.30 * np.exp(-(i - j) / 5.0)
            + 0.065
        )
        weights[0] += 0.80
        weights[i] += 0.70 * np.exp(-i / 15.0) + 0.25

        # Early predicates commonly split their mass between self and the start.
        if pos in ("VERB", "AUX"):
            weights[i] += 0.90 * np.exp(-i / 6.0)
        if dep in ("cc", "ROOT"):
            weights[i] += 0.20 * np.exp(-i / 10.0)

        # Weak preference for a nearby, causally available syntactic head.
        if word is not None and word.head.i != word.i:
            head_indices = [
                k for k in range(i)
                if word.head.i in alignment[k]
            ]
            if head_indices:
                weights[head_indices[-1]] += 0.20

        row = weights / weights.sum()

        if i == 1:
            first_word = doc[alignment[0][0]] if alignment[0] else None
            first_pos = first_word.pos_ if first_word is not None else ""
            first_dep = first_word.dep_ if first_word is not None else ""

            sink = 0.65
            if pos in ("VERB", "AUX"):
                sink = 0.49 if pos == "AUX" else 0.53
            elif pos in ("NOUN", "PROPN") and first_pos == "DET":
                sink = 0.77
            elif pos == "ADJ" and first_pos == "DET":
                sink = 0.81
            elif first_dep == "poss" and pos in ("NOUN", "PROPN"):
                sink = 0.41
            elif punctuation:
                sink = 0.54
            row[:] = (sink, 1.0 - sink)

        if punctuation and i > 1:
            self_mass = 0.39 if "." in clean else 0.27
            previous_mass = row[:i].sum()
            if previous_mass > 0:
                row[:i] *= (1.0 - self_mass) / previous_mass
                row[i] = self_mass

        fragmented = (
            word is not None
            and word_counts[word.i] > 1
            and pos != "PUNCT"
        )
        if whitespace or fragmented:
            continuation = (
                fragmented and i > 0
                and any(index in alignment[i - 1] for index in indices)
            )
            target = 0.54 if whitespace else (0.78 if continuation else 0.58)
            if row[0] < target:
                row[1:] *= (1.0 - target) / max(1.0 - row[0], 1e-12)
                row[0] = target

        attention[i, :i + 1] = row

    return "first_token_sink_with_diffuse_context", make_row_stochastic(attention)


def prog_L11H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, strongest early and on salient nominal queries.
    Residual attention is diffuse and mildly biased toward recent context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        # The dominant destination is positional, not a syntactic antecedent.
        sink_mass = (
            0.79
            + 0.15 * np.exp(-(i - 1) / 4.0)
            - 0.0018 * i
        )

        aligned = alignment[i]
        if aligned:
            word = doc[aligned[-1]]
            if word.pos_ in ("PRON", "PROPN"):
                sink_mass += 0.075
            elif word.pos_ == "NOUN":
                sink_mass += 0.045
            elif word.pos_ in ("VERB", "AUX"):
                sink_mass -= 0.025

            if word.dep_ in ("nsubj", "nsubjpass", "csubj"):
                sink_mass += 0.035
            if word.ent_type_:
                sink_mass += 0.02
            if word.is_punct:
                sink_mass -= 0.10
            if word.is_space:
                sink_mass += 0.045

            # Fragmented words sometimes produce unusually strong sink queries.
            if i > 1 and any(k in alignment[i - 1] for k in aligned):
                sink_mass += 0.045
        elif tokens[i].isspace() or tokens[i] == "\u0120":
            sink_mass += 0.045

        sink_mass = float(np.clip(sink_mass, 0.48, 0.985))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        recent = np.exp(-(i - positions) / 5.0)
        recent /= recent.sum()
        residual = 0.65 * recent + 0.35 / i
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink", make_row_stochastic(attention)


def prog_L11H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, gradually weakening with distance.
    Residual attention follows a weak causal recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink_with_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.65 + 0.33 * np.exp(-(i - 1) / 65.0)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1)
        residual = np.exp(-distances / 8.0)
        attention[i, 1:i + 1] = (
            (1.0 - sink_mass) * residual / residual.sum()
        )

    return "first_token_sink_with_decay", attention


def prog_L11H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, strongest early and on content-bearing queries.
    Remaining attention follows recency, clause subjects, and syntactic heads.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    label = "first_token_sink_with_linguistic_gating"
    if n == 0:
        return label, attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    words = []
    for indices in alignment:
        candidates = [doc[k] for k in indices if not doc[k].is_space]
        words.append(
            max(candidates, key=lambda w: len(w.text)) if candidates else None
        )

    attention[0, 0] = 1.0
    for i in range(1, n):
        word = words[i]
        if word is None:
            base = 0.48
        elif word.pos_ in ("NOUN", "PROPN"):
            base = 0.61
        elif word.pos_ == "ADJ":
            base = 0.62
        elif word.pos_ == "VERB":
            base = 0.43
        elif word.pos_ == "AUX":
            base = 0.32
        elif word.pos_ == "PRON":
            base = 0.58 if word.dep_ in ("nsubj", "nsubjpass") else 0.31
        elif word.pos_ == "ADV":
            base = 0.36
        elif word.pos_ == "PUNCT":
            base = 0.33
        else:
            base = 0.27

        # Early queries have a particularly strong positional sink.
        sink = base + (0.91 - base) * np.exp(-(i - 1) / 3.2)

        if word is not None:
            if word.ent_type_:
                sink += 0.04
            if word.pos_ == "ADJ" and word.dep_ in ("acomp", "ROOT", "attr"):
                sink += 0.07
            if any(doc[k].dep_ == "neg" for k in alignment[i]):
                sink += 0.22
            if word.is_punct and any(c in ".!?" for c in word.text):
                sink *= 0.60

        sink = float(np.clip(sink, 0.12, 0.97))

        # Allocate the non-sink mass only over noninitial causal keys.
        positions = np.arange(1, i + 1)
        weights = 0.18 + np.exp(-(i - positions) / 4.5)
        weights[-1] += 0.35

        if word is not None:
            for j in range(1, i + 1):
                key = words[j]
                if key is None:
                    continue
                if key.i == word.head.i and key.i != word.i:
                    weights[j - 1] += 0.65
                if key.dep_ in ("nsubj", "nsubjpass", "csubj"):
                    weights[j - 1] += 0.40 * np.exp(-(i - j) / 20.0)
                if key.is_punct:
                    weights[j - 1] += 0.15 * np.exp(-(i - j) / 6.0)

        attention[i, 0] = sink
        attention[i, 1:i + 1] = (1.0 - sink) * weights / weights.sum()

    return label, attention


def prog_L11H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink whose dominance gradually declines with position.
    Residual attention is distributed causally with a mild recency preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink_with_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        sink_mass = 0.97 / (1.0 + 0.045 * i ** 0.85)
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 + np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_decay", attention


def prog_L11H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink with mild positional decay.
    Residual attention favors recent tokens, especially around punctuation.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink_with_decay", attention

    attention[0, 0] = 1.0

    for i in range(1, n):
        clean = tokens[i].lstrip("Ġ").lstrip("Ċ").strip()
        is_punctuation = bool(clean) and all(
            not c.isalnum() and not c.isspace() for c in clean
        )

        sink_mass = 0.98 - 0.0025 * i
        if is_punctuation:
            sink_mass -= 0.07
        sink_mass = float(np.clip(sink_mass, 0.65, 0.985))

        positions = np.arange(1, i + 1)
        residual = 0.25 + np.exp(-(i - positions) / 8.0)
        residual /= residual.sum()

        attention[i, 0] = sink_mass
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_decay", attention


def prog_L11H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, weakening with distance and at punctuation.
    Residual attention follows a weak causal recency prior.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_decay", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        aligned = alignment[i]
        is_punct = any(doc[k].is_punct for k in aligned)
        is_space = bool(aligned) and all(doc[k].is_space for k in aligned)

        # Strong positional anchor rather than a particular lexical target.
        sink_odds = 75.0 / (1.0 + 0.09 * i) ** 1.65
        if is_punct:
            sink_odds *= 0.65
        elif is_space:
            sink_odds *= 0.85

        sink_mass = sink_odds / (1.0 + sink_odds)
        attention[i, 0] = sink_mass

        distances = i - np.arange(1, i + 1, dtype=np.float64)
        residual = 0.35 / i + 0.65 * np.exp(-distances / 6.0)
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_decay", attention


def prog_L11H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, strongest for early tokens and grammatical subjects.
    A small residual is distributed over recent causal context.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    attention[0, 0] = 1.0

    for i in range(1, n):
        words = [doc[k] for k in alignment[i] if k < len(doc)]
        pos = {w.pos_ for w in words}
        deps = {w.dep_ for w in words}

        sink = 0.91 - 0.12 * i / (i + 20.0)
        sink += 0.045 * np.exp(-i / 6.0)

        if pos & {"PRON"}:
            sink += 0.075
        elif pos & {"DET", "PROPN"}:
            sink += 0.04

        if deps & {"nsubj", "nsubjpass", "csubj", "poss"}:
            sink += 0.045

        if pos & {"VERB"}:
            sink -= 0.07
        elif pos & {"ADP", "CCONJ", "SCONJ"}:
            sink -= 0.035

        if pos & {"PUNCT"}:
            sink -= 0.08
        if pos & {"SPACE"}:
            sink += 0.015

        sink = float(np.clip(sink, 0.60, 0.985))
        attention[i, 0] = sink

        distances = i - np.arange(1, i + 1)
        residual = 0.35 + np.exp(-distances / 5.0)
        attention[i, 1:i + 1] = (1.0 - sink) * residual / residual.sum()

    return "first_token_sink", attention


def prog_L11H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Causal clause-and-phrase anchors, with prepositional complements
    attending through their preposition to an accessible content predicate.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "causal_clause_and_phrase_anchors", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = align_spacy_to_tokens(sentence, tokens, tokenizer)

    representatives = []
    for ids in aligned:
        nonspace = [k for k in ids if not doc[k].is_space]
        representatives.append(nonspace[-1] if nonspace else None)

    quote_anchor = None
    quote_onset = None
    quote_open = False
    sentence_onset = True

    for i in range(n):
        text = tokens[i].replace("\u0120", " ").replace("\u010a", "\n").strip()
        sid = representatives[i]
        word = doc[sid] if sid is not None else None
        pos = word.pos_ if word is not None else ""
        dep = word.dep_ if word is not None else ""

        # A diffuse causal background preserves the head's weaker structure.
        distances = i - np.arange(i + 1)
        background = np.exp(-distances / 16.0)
        attention[i, :i + 1] = 0.38 * background / background.sum()
        attention[i, i] += 0.90
        if i:
            attention[i, i - 1] += 0.18

        is_quote = any(c in text for c in ('"', '“', '”', '«', '»'))
        is_closer = is_quote and (
            quote_open or any(c in text for c in ("”", "»"))
        )
        is_opener = is_quote and not is_closer
        is_terminal = any(c in text for c in (".", "!", "?"))

        if sentence_onset and word is not None and not word.is_punct:
            attention[i, i] += 1.10
            sentence_onset = False

        if word is not None and not word.is_punct:
            # Select the nearest accessible ancestor, skipping future heads.
            ancestor = word.head
            visited = {word.i}
            depth = 0
            while ancestor.i not in visited and depth < 8:
                visited.add(ancestor.i)
                candidates = [j for j in inverse[ancestor.i] if j < i]
                if candidates:
                    target = candidates[-1]
                    strength = 1.30 if depth == 0 else 0.85
                    if dep in ("dobj", "obj", "iobj", "attr", "acomp", "oprd"):
                        strength += 0.90
                    if ancestor.pos_ in ("VERB", "AUX"):
                        strength += 0.35
                    if pos in ("VERB", "AUX"):
                        strength *= 0.65
                    attention[i, target] += strength
                    break
                ancestor = ancestor.head
                depth += 1

            # Nominal modifiers often point to the beginning of their phrase.
            nominal = word if pos in ("NOUN", "PROPN") else word.head
            if nominal.pos_ in ("NOUN", "PROPN"):
                determiners = []
                for child in nominal.children:
                    if child.dep_ in ("det", "poss"):
                        determiners.extend(j for j in inverse[child.i] if j < i)
                if determiners and pos in ("ADJ", "ADV", "NOUN", "PROPN"):
                    strength = 1.95 if pos in ("ADJ", "ADV") else 0.40
                    attention[i, determiners[0]] += strength

            # Auxiliary-led predicates form persistent local clause anchors.
            predicate = word
            visited = set()
            while predicate.i not in visited:
                visited.add(predicate.i)
                if predicate.pos_ in ("VERB", "AUX"):
                    break
                if predicate.head.i == predicate.i:
                    break
                predicate = predicate.head

            if predicate.pos_ in ("VERB", "AUX"):
                auxiliaries = []
                subjects = []
                for child in predicate.children:
                    if child.dep_ in ("aux", "auxpass", "cop"):
                        auxiliaries.extend(j for j in inverse[child.i] if j < i)
                    if child.dep_ in ("nsubj", "nsubjpass", "csubj"):
                        subjects.extend(j for j in inverse[child.i] if j < i)
                if auxiliaries:
                    attention[i, auxiliaries[0]] += 0.90
                if subjects and pos in ("VERB", "AUX"):
                    attention[i, subjects[-1]] += 0.65

            if pos == "AUX":
                attention[i, i] += 0.85

            # Split words generally retain their linguistic anchor rather than
            # receiving an automatic, dominant previous-subtoken connection.
            if i and sid == representatives[i - 1]:
                attention[i, i - 1] += 0.15

            # Targeted exception: a predicate-attached preposition is a bridge,
            # not the semantic anchor of its nominal complement. Leave nominal
            # PP attachments and all other dependency configurations unchanged.
            if dep == "pobj" and word.head.pos_ == "ADP":
                preposition = word.head
                governor = preposition.head
                if governor.pos_ in ("VERB", "ADJ"):
                    targets = [j for j in inverse[governor.i] if j < i]
                    bridges = [j for j in inverse[preposition.i] if j < i]
                    if targets and bridges:
                        target = targets[-1]
                        bridge = bridges[-1]
                        transferred = 0.85 * attention[i, bridge]
                        attention[i, bridge] -= transferred
                        attention[i, target] += transferred + 1.80

        if word is not None and word.is_punct:
            attention[i, i] += 0.35
            if not is_terminal and not is_quote:
                for j in range(i - 1, -1, -1):
                    previous_sid = representatives[j]
                    if previous_sid is None:
                        continue
                    previous = doc[previous_sid]
                    if previous.pos_ in ("VERB", "AUX"):
                        attention[i, j] += 1.30
                        break
                    if previous.is_punct and previous.text in (".", "!", "?"):
                        break

        if quote_anchor is not None and not is_opener:
            distance = i - quote_anchor
            attention[i, quote_anchor] += 2.80 * np.exp(-distance / 6.0)
            if quote_onset is not None and quote_onset < i:
                onset_sid = representatives[quote_onset]
                if onset_sid is not None:
                    onset = doc[onset_sid]
                    if onset.tag_ in ("WDT", "WP", "WP$", "WRB"):
                        attention[i, quote_onset] += 1.15 * np.exp(
                            -(i - quote_onset) / 10.0
                        )

        if is_opener:
            attention[i, i] += 5.0
            quote_anchor = i
            quote_onset = None
            quote_open = True
        elif quote_open and quote_onset is None and word is not None:
            if not word.is_punct and not word.is_space:
                quote_onset = i

        if is_terminal:
            attention[i, i] += 2.10
            sentence_onset = True

        if is_closer:
            quote_open = False
            quote_anchor = None
            quote_onset = None

        # This unusually strong positional signature holds across the examples.
        if i < 2:
            attention[i, :] = 0.0
            attention[i, i] = 1.0

    return (
        "causal_clause_and_phrase_anchors",
        make_row_stochastic(apply_causal_mask(attention)),
    )


def prog_L11H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with mild positional weakening.
    Residual attention follows a causal recency bias rather than semantic links.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)

    if n == 0:
        return "first_token_sink_with_recency", attention

    attention[0, 0] = 1.0
    for i in range(1, n):
        sink_mass = 0.985 / (1.0 + 0.0035 * (i - 1))
        attention[i, 0] = sink_mass

        positions = np.arange(1, i + 1, dtype=np.float64)
        residual = 0.8 * np.exp(-(i - positions) / 4.0) + 0.2
        residual /= residual.sum()
        attention[i, 1:i + 1] = (1.0 - sink_mass) * residual

    return "first_token_sink_with_recency", attention


def prog_L11H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention sink, with weaker recency and syntactic-head attention.
    Immediate verb–object links can override the default sink preference.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_syntax", attention

    doc = spacy_parse(sentence)
    alignment = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(alignment):
        for k in indices:
            if k < len(doc):
                inverse[k].append(i)

    attention[0, 0] = 1.0

    for i in range(1, n):
        indices = alignment[i]
        word = doc[indices[-1]] if indices else None

        # Strong positional sink, slightly weaker as the context grows.
        sink = 0.66 + 0.18 * np.exp(-(i - 1) / 7.0)
        head_index = None
        immediate_object = False

        if word is not None:
            if word.pos_ in ("VERB", "AUX", "ADJ"):
                sink += 0.055
            elif word.pos_ in ("NOUN", "PROPN"):
                sink += 0.025
            elif word.pos_ == "PUNCT":
                sink -= 0.13
            elif word.pos_ in ("CCONJ", "SCONJ", "ADV"):
                sink -= 0.055
            elif word.pos_ == "DET":
                sink -= 0.035

            if word.dep_ in ("ROOT", "nsubj", "nsubjpass"):
                sink += 0.025

            if word.head.i != word.i:
                candidates = [
                    j for j in inverse[word.head.i]
                    if j < i and j not in inverse[word.i]
                ]
                if candidates:
                    head_index = candidates[-1]
                    immediate_object = (
                        word.dep_ in ("dobj", "obj", "attr", "oprd")
                        and word.head.pos_ == "VERB"
                        and head_index == i - 1
                    )

            if immediate_object:
                sink -= 0.40

        if tokens[i].isspace() or not tokens[i].strip("ĠĊ \t\r\n"):
            sink += 0.07

        sink = float(np.clip(sink, 0.22, 0.94))

        # Residual attention favors recent positions and available parse heads.
        residual = np.zeros(i + 1, dtype=np.float64)
        positions = np.arange(1, i + 1)
        residual[1:] = np.exp(-(i - positions) / 4.0)
        residual[i] *= 0.40
        residual /= residual.sum()

        if head_index is not None and head_index > 0:
            syntactic_share = 0.88 if immediate_object else 0.40
            residual *= 1.0 - syntactic_share
            residual[head_index] += syntactic_share

        attention[i, :i + 1] = (1.0 - sink) * residual
        attention[i, 0] = sink

    return "first_token_sink_with_syntax", make_row_stochastic(attention)


def prog_L11H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token sink with quote anchors and selective verb–argument retrieval.
    Weak syntactic argument links return excess mass to the sink, preserving self-attention.
    """
    tokens = tokenize(sentence, tokenizer)
    n = len(tokens)
    attention = np.zeros((n, n), dtype=np.float64)
    if n == 0:
        return "first_token_sink_with_selective_argument_and_quote_links", attention

    doc = spacy_parse(sentence)
    aligned = align_tokens_to_spacy(sentence, tokens, tokenizer)
    inverse = [[] for _ in doc]
    for i, indices in enumerate(aligned):
        for index in indices:
            inverse[index].append(i)

    # Track opening double quotes, including quotes merged with punctuation.
    opening = np.zeros(n, dtype=bool)
    prior_opening = [-1] * n
    inside_quote = False
    last_opening = -1
    for i, token in enumerate(tokens):
        prior_opening[i] = last_opening
        for char in token:
            if char in ('"', '\u201c', '\u201d'):
                if char == '\u201c':
                    is_open = True
                elif char == '\u201d':
                    is_open = False
                else:
                    is_open = not inside_quote
                if is_open:
                    opening[i] = True
                    last_opening = i
                    inside_quote = True
                else:
                    inside_quote = False

    attention[0, 0] = 1.0
    for i in range(1, n):
        quote_anchor = prior_opening[i]
        sink = 0.64 + 0.30 * np.exp(-i / 5.0)
        if quote_anchor >= 0:
            sink -= 0.11 * (1.0 - np.exp(-i / 10.0))

        argument_target = -1
        argument_strength = 0.0
        argument_cap = 1.0
        for index in aligned[i]:
            word = doc[index]
            head = word.head
            strength = 0.0
            target_word = None

            if (
                word.dep_ in ("dobj", "obj", "iobj", "attr", "oprd")
                and head.pos_ in ("VERB", "AUX")
                and head.i < word.i
            ):
                target_word = head
                strength = 0.76 if word.pos_ == "PRON" else 0.57
                if word.pos_ in ("NOUN", "PROPN"):
                    strength += 0.07
            elif (
                word.dep_ in ("nsubj", "nsubjpass")
                and head.dep_ in ("relcl", "acl")
                and head.head.i < word.i
            ):
                target_word = head.head
                strength = 0.65

            if target_word is not None:
                candidates = inverse[target_word.i]
                preceding = [j for j in candidates if 0 < j < i]
                if preceding:
                    target = preceding[-1]
                    distance_factor = np.exp(-max(0, i - target - 3) / 12.0)
                    strength *= distance_factor
                    if strength > argument_strength:
                        argument_target = target
                        argument_strength = strength

                        # Dependency attachment alone overstates retrieval.
                        # Retain strong nominal objects of imperative-like verbs.
                        imperative_object = (
                            word.dep_ in ("dobj", "obj", "iobj")
                            and word.pos_ == "NOUN"
                            and head.pos_ == "VERB"
                            and head.tag_ == "VB"
                            and head.dep_ in ("ROOT", "conj")
                            and not any(
                                child.dep_ in ("nsubj", "nsubjpass", "csubj")
                                for child in head.children
                            )
                        )
                        if imperative_object:
                            argument_cap = 1.0
                        elif word.dep_ not in ("dobj", "obj", "iobj"):
                            argument_cap = 0.08
                        elif word.pos_ == "PROPN":
                            argument_cap = 0.25
                        elif word.pos_ == "PRON":
                            argument_cap = 0.32
                        else:
                            argument_cap = 0.35

        # A comma introducing another quotation strongly retrieves the
        # preceding opening quotation rather than the sentence-initial sink.
        clean = tokens[i].replace("\u0120", "").strip()
        quotation_transition = (
            clean == ","
            and i + 1 < n
            and opening[i + 1]
            and quote_anchor > 0
        )
        if quotation_transition:
            attention[i, 0] = 0.045
            attention[i, quote_anchor] = 0.925
            attention[i, i] += 0.03
            continue

        if argument_target > 0:
            sink = min(sink, 0.94 - argument_strength)

        attention[i, 0] = sink
        remaining = 1.0 - sink

        if argument_target > 0:
            mass = min(argument_strength, remaining * 0.94)
            attention[i, argument_target] += mass
            remaining -= mass

        if quote_anchor > 0:
            mass = remaining * 0.42
            attention[i, quote_anchor] += mass
            remaining -= mass

        # Diffuse residual attention, weakly favoring recent causal positions.
        positions = np.arange(1, i + 1)
        background = 0.35 + np.exp(-(i - positions) / 5.0)
        attention[i, 1:i + 1] += remaining * background / background.sum()

        # Change only the argument edge and sink; preserve every other weight.
        if argument_target > 0 and argument_cap < 1.0:
            excess = max(0.0, attention[i, argument_target] - argument_cap)
            attention[i, argument_target] -= excess
            attention[i, 0] += excess

    return (
        "first_token_sink_with_selective_argument_and_quote_links",
        make_row_stochastic(attention),
    )


